#!/usr/bin/env node
/**
 * Verification of the host half: model and motion discovery, path safety, and the
 * route handlers that hand authored bytes to the page.
 *
 * Run:  node scripts/verify-model.mjs [--fetch]
 *
 * `--fetch` still downloads the MMD sample the on-disk `build/probe/mmd-probe.js`
 * chapter used into build/fixtures/miku. Nothing in this suite needs it since MMD
 * was implementation-removed (2026-10-12) and that page is no longer wired into
 * `verify-browser.mjs`; the fixtures the wired-in browser pages DO need are
 * generated by `node scripts/make-vrma-fixtures.mjs`. Nothing here writes into the
 * plugin's shipped directories.
 *
 * These are the checks where a mistake is a security problem rather than a
 * cosmetic one: the asset and motion routes are the only places a browser can ask
 * the host for bytes off the user's disk, so their allowlisting is tested
 * adversarially.
 */
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import { dirname, extname, join, resolve, sep } from 'node:path';
import { existsSync, mkdirSync, readFileSync, writeFileSync, statSync, rmSync, truncateSync, symlinkSync, utimesSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { createServer } from 'node:http';
import { brotliCompressSync } from 'node:zlib';
import { randomUUID } from 'node:crypto';
// The loopback helper exists because `listen(0)` can be handed a port `fetch`
// refuses, which kills the whole suite instead of one check. See its own header.
import { listenOnUsablePort } from './loopback.mjs';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const plugin = await import(new URL('../lib/index.js', import.meta.url).href);
/**
 * The described-model cache, imported DIRECTLY because "the second request did not re-parse the file" is
 * not visible over HTTP: two answers made from a cached report and from a fresh parse are byte-identical.
 * `cacheStats().parses` is the only witness, so the suite has to be able to read it.
 */
const vrmInfo = await import(new URL('../lib/vrm-info.js', import.meta.url).href);
/**
 * The fixture generator, imported for ONE assertion: the manifest file name it writes beside the clips has
 * to be the name the host reads. The generator spells it out rather than importing it (it is deliberately
 * standalone), so the two spellings can drift — and the failure mode is silent, because a manifest under a
 * name nobody reads simply leaves every clip looping.
 */
const generator = await import(new URL('./make-vrma-fixtures.mjs', import.meta.url).href);
// The host imports the same file, but the suite reads it directly so the motion
// fixtures can be checked against the CLIENT's own detector. A fixture the page
// would reject proves nothing about the route that served it.
await import(new URL('../lib/core.js', import.meta.url).href);
/**
 * The unpacker, read directly rather than through `lib/index.js`'s re-export surface.
 *
 * It is the same module the host's motion route calls, and reading it here proves the DECODING on its own —
 * a route test would only prove that whatever the route did produced bytes that matched whatever it did.
 */
const brotli = await import(new URL('../lib/brotli.js', import.meta.url).href);
/**
 * The whale mark's own module, which the closing chain group drives directly.
 *
 * `/vrmpet3d/whale` serves whatever `resolveWhaleMark` found AT ACTIVATION, so the order of its rungs — the
 * running DSH, this package's file, the copy a previous activation cached, nothing — cannot be re-asked over
 * HTTP without re-applying the plugin. The rule is a pure function of the paths it is handed, which is what
 * lets one group drive every rung.
 */
const whaleMark = await import(new URL('../lib/whale.js', import.meta.url).href);
const core = globalThis.__VRMPET3D_CORE__;

/**
 * The whale fixtures: PNG-SHAPED bytes built here rather than DeepSeek's mark copied.
 *
 * What the host checks — and therefore what a suite can hold it to — is the PNG signature plus the `acTL`
 * animation-control and `fcTL` frame-control chunks, not decoded pixels. The real mark is the 21 KB APNG this
 * repository must not keep (`docs/ASSET-CONTRACT.md` §1), so the fixture is a header, an animation control
 * chunk and two frame control chunks: exactly the shape that decides every branch below, and nothing that
 * could be mistaken for the real asset.
 */
function apngFixture(frames = 2) {
  const ihdr = Buffer.alloc(8 + 13 + 4);
  ihdr.writeUInt32BE(13, 0);
  ihdr.write('IHDR', 4, 'latin1');
  ihdr.writeUInt32BE(28, 8);
  ihdr.writeUInt32BE(28, 12);
  const actl = Buffer.alloc(8 + 8 + 4);
  actl.writeUInt32BE(8, 0);
  actl.write('acTL', 4, 'latin1');
  const fctl = Buffer.alloc(8 + 26 + 4);
  fctl.writeUInt32BE(26, 0);
  fctl.write('fcTL', 4, 'latin1');
  const iend = Buffer.alloc(12);
  iend.write('IEND', 4, 'latin1');
  return Buffer.concat([Buffer.from('89504e470d0a1a0a', 'hex'), ihdr, actl,
    ...Array.from({ length: frames }, () => fctl), iend]);
}

/** A still PNG: the signature and an IHDR, deliberately with no `acTL`/`fcTL`. */
function stillPngFixture() {
  return Buffer.concat([
    Buffer.from('89504e470d0a1a0a', 'hex'),
    Buffer.from('0000000dIHDR0000001c0000001c', 'latin1'),
    Buffer.from('00000000IEND', 'latin1'),
  ]);
}

/** One DSH-shaped root: `<root>/dsh/node_modules/@deepseek-ai/dsh-client-ui-chat/lib/client.js`. */
function dshLayoutFixture(root, image, label) {
  const member = join(root, 'dsh', 'node_modules', '@deepseek-ai', 'dsh-client-ui-chat', 'lib', 'client.js');
  mkdirSync(dirname(member), { recursive: true });
  writeFileSync(member,
    `/* ${label} */\nvar css = "color:red;mask:url(data:image/png;base64,${image.toString('base64')}) center/contain";\n`);
  return member;
}

/**
 * The imported-directory list the whole run is pointed at.
 *
 * The host resolves this file inside the running profile by default, so a suite that
 * did not redirect it would read 鈥?and in the route groups write 鈥?the user's own
 * import list. That is not hypothetical: a live import performed while debugging made
 * this suite report three models where one was expected, i.e. a real profile turned a
 * green suite red for a reason that had nothing to do with the code under test.
 * Redirecting it here, before any group applies the plugin, keeps every group on an
 * empty scratch list.
 */
const IMPORTED_DIRS_FILE = join(ROOT, 'build', 'fixtures', 'model-dirs-verify.json');
process.env.VRMPET3D_MODEL_DIRS_FILE = IMPORTED_DIRS_FILE;
/**
 * The same redirection for the MOTION list, and for the same reason: a suite that POSTs an import must not
 * write the operator's own file (gotcha 37). Motions used to have no import list at all — only the plugin's
 * `config.motionDirs`, which needs a DSH restart — so this file is what makes "drop a .vrma in a folder and
 * use it" possible without touching the profile config.
 */
const IMPORTED_MOTIONS_FILE = join(ROOT, 'build', 'fixtures', 'motion-dirs-verify.json');
process.env.VRMPET3D_MOTION_DIRS_FILE = IMPORTED_MOTIONS_FILE;
rmSync(IMPORTED_DIRS_FILE, { force: true });

/**
 * And the SETTINGS store, for the same reason one level deeper.
 *
 * Applying the plugin constructs `SettingsStore`, and its constructor reads AND WRITES the settings
 * file at once — so a suite that did not redirect it rewrote the operator's own
 * `vrmpet3d-settings.json`. Measured 2026-10-08: the live plugin's store said version 13 while the file
 * on disk said version 1, because a suite run had constructed a fresh store against it. The
 * preferences survived only because the constructor reads before it writes; a group that POSTs a
 * patch would have overwritten them.
 */
const SETTINGS_FILE = join(ROOT, 'build', 'fixtures', 'settings-verify.json');
process.env.VRMPET3D_SETTINGS_FILE = SETTINGS_FILE;
rmSync(SETTINGS_FILE, { force: true });

/**
 * And the three stores this suite did NOT own until 2026-10-12, which is a measured accident rather than a
 * precaution.
 *
 * The import routes grew a FILE store (`addFile`/`removeFile`, and the motion `importDir`/`unimportDir`) whose
 * files are resolved inside the running profile, exactly like the directory lists above — and this suite named
 * only the directory lists. The first run after that change created `vrmpet3d-model-files.json` and
 * `vrmpet3d-motion-imports.json` in the OPERATOR's profile: two files nothing had asked for, from a POST that only
 * meant to exercise the legacy `{add: <directory>}` verb. The host no longer writes those stores for a legacy
 * request, and this suite now names every store it does not own, so neither half of that accident can come back.
 *
 * The wizard's completion flag is here for the same reason and with a louder consequence: a suite that set it would
 * mark the operator's machine as configured, which is the one state a test may never write.
 */
const IMPORT_STATE_DIR = join(ROOT, 'build', 'fixtures', 'import-state-verify');
const MODEL_FILES_FILE = join(ROOT, 'build', 'fixtures', 'model-files-verify.json');
const MOTION_IMPORTS_FILE = join(ROOT, 'build', 'fixtures', 'motion-imports-verify.json');
const SETUP_FILE = join(ROOT, 'build', 'fixtures', 'setup-verify.json');
process.env.VRMPET3D_IMPORT_DIR = IMPORT_STATE_DIR;
process.env.VRMPET3D_MODEL_FILES_FILE = MODEL_FILES_FILE;
process.env.VRMPET3D_MOTION_IMPORTS_FILE = MOTION_IMPORTS_FILE;
process.env.VRMPET3D_SETUP_FILE = SETUP_FILE;
rmSync(IMPORTED_MOTIONS_FILE, { force: true });
rmSync(MODEL_FILES_FILE, { force: true });
rmSync(MOTION_IMPORTS_FILE, { force: true });
rmSync(SETUP_FILE, { force: true });
rmSync(IMPORT_STATE_DIR, { recursive: true, force: true });

/**
 * And the whale mark's local rungs, pointed at fixtures this suite owns.
 *
 * The host resolves the mark ONCE, at activation, and `/vrmpet3d/whale` then serves that answer — so a suite
 * that let the resolution read the repository's own `assets/whale-tail.apng` would be asserting "this machine
 * happens to have pre-seeded the mark", and one that let it read the operator's DSH would assert nothing at
 * all in plain node (`existsSync` on a member of `app.asar` is false without Electron's patched `fs`).
 * `VRMPET3D_WHALE_FILE` names the fallback file instead; the two `DSH_ASAR` spellings are cleared, because an
 * empty string counts as unset in `lib/env.js` — the same technique `check-docs.mjs` uses for the desktop
 * suite's switch.
 *
 * The cached copy a previous activation would leave is `join(importRootDir(), 'whale-tail.apng')`, which the
 * `VRMPET3D_IMPORT_DIR` redirection above already puts in this suite's scratch (gotcha 37), and the chain
 * group at the end of the run is what exercises it.
 */
const WHALE_FIXTURE_FILE = join(ROOT, 'build', 'fixtures', 'whale-mark-verify.apng');
mkdirSync(dirname(WHALE_FIXTURE_FILE), { recursive: true });
writeFileSync(WHALE_FIXTURE_FILE, apngFixture());
process.env.VRMPET3D_WHALE_FILE = WHALE_FIXTURE_FILE;
process.env.VRMPET3D_DSH_ASAR = '';
process.env.PET3D_DSH_ASAR = '';

let passed = 0;
let failed = 0;
const failures = [];

function ok(condition, label) {
  if (condition) passed += 1;
  else {
    failed += 1;
    failures.push(label);
    console.error(`  FAIL  ${label}`);
  }
}

function eq(actual, expected, label) {
  if (Object.is(actual, expected)) passed += 1;
  else {
    failed += 1;
    failures.push(label);
    console.error(`  FAIL  ${label}\n        expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

function group(title) {
  console.log(`\n${title}`);
}

/**
 * The clips from directories THE USER named, without the plugin's own bundled pack.
 *
 * `assets/motions` has been scanned first, with `source: 'bundled'`, since the pack started shipping
 * (2026-10-12), so it is in every catalog `buildMotionCatalog` returns and in every `/vrmpet3d/motions`
 * payload — exactly as `assets/models` is in every model catalog, and for the same reason. Assertions about
 * the SCAN have user-supplied directories as their subject, so they filter the bundled entries out; the
 * bundled ones are asserted on their own, so neither subject can hide the other's failure.
 */
function userMotions(motions) {
  return (motions || []).filter(motion => motion.source !== 'bundled');
}

/**
 * A synthetic `.vmd`: the 30-byte ASCII banner every exporter writes, then a
 * plausible body. Nothing here parses the body, and neither does the host 鈥?the
 * bytes only have to be recognisable to `core.detectMotionFormat` and clearly not
 * a model.
 */
function vmdFixture(label = '') {
  // Since MMD was implementation-removed (2026-10-12) nothing lists or serves one of these: the fixture
  // exists so the client's own detector can still be shown to NAME a VMD (which is what a refusal message
  // is built from) and so a `.vmd` can be planted in a directory and asserted ABSENT from both catalogs.
  const header = Buffer.alloc(30, 0);
  header.write('Vocaloid Motion Data 0002', 0, 'ascii');
  return Buffer.concat([header, Buffer.from(`motion:${label}`, 'utf8')]);
}

/**
 * Pack a glTF document into a GLB, the way every exporter does: a 12-byte header, then one JSON chunk
 * padded with spaces to a 4-byte boundary.
 *
 * Used by `vrmaFixture` below and by the cache test, which needs a SECOND model file that is genuinely
 * different from the fixture yet still a VRM this plugin can describe: the fixture's own document, with
 * meshes added to it, is exactly that.
 */
function glbFromJson(json) {
  const bytes = Buffer.from(JSON.stringify(json), 'utf8');
  const padded = Buffer.concat([bytes, Buffer.alloc((4 - (bytes.length % 4)) % 4, 0x20)]);
  const header = Buffer.alloc(12);
  header.writeUInt32LE(0x46546c67, 0);              // 'g' 'l' 'T' 'F'
  header.writeUInt32LE(2, 4);                       // version
  header.writeUInt32LE(12 + 8 + padded.length, 8);  // total length
  const chunk = Buffer.alloc(8);
  chunk.writeUInt32LE(padded.length, 0);
  chunk.writeUInt32LE(0x4e4f534a, 4);               // 'J' 'S' 'O' 'N'
  return Buffer.concat([header, chunk, padded]);
}

/** A synthetic `.vrma`: an ordinary GLB whose JSON chunk names `VRMC_vrm_animation`. */
function vrmaFixture(label = '') {
  return glbFromJson({
    asset: { version: '2.0', generator: 'vrmpet3d verify' },
    extensions: { VRMC_vrm_animation: { specVersion: '1.0' } },
    extras: { label },
  });
}

/**
 * The webserver's own matching rule, copied from `match()` in
 * `@deepseek-ai/dsh-host-webserver`: the exact table first, then the longest
 * prefix that ends on a `/` boundary.
 *
 * It is copied because the SHAPES this plugin registers are part of what is under
 * test 鈥?above all `/vrmpet3d/motions` against the `/vrmpet3d/motion` prefix, two paths
 * one letter apart. A real HTTP server plus this matcher exercises the registered
 * table, the handlers and the shapes together; only a dozen lines of matching are
 * a stand-in.
 */
function matchRoute(routes, pathname) {
  const exact = routes.find(route => route.kind === 'exact' && route.path === pathname);
  if (exact !== undefined) return exact;
  let best;
  for (const route of routes) {
    if (route.kind !== 'prefix') continue;
    if (pathname !== route.path && !pathname.startsWith(route.path + '/')) continue;
    if (best === undefined || route.path.length > best.path.length) best = route;
  }
  return best;
}

/**
 * Serve a live route table from a REAL HTTP server.
 *
 * The table is read per request, so a route registered or disposed after the
 * server started is visible to the next request 鈥?that is what makes the
 * activation and disposal checks below real rather than simulated.
 *
 * A hand-rolled fake `res` is not enough (see group 4): the handlers stream with
 * `createReadStream(...).pipe(res)`, which needs an actual writable stream.
 */
async function serveRoutes(routes) {
  const server = createServer((req, res) => {
    let pathname;
    try {
      pathname = new URL(req.url ?? '/', 'http://x').pathname;
    } catch {
      res.writeHead(400);
      res.end();
      return;
    }
    const route = matchRoute(routes, pathname);
    if (route === undefined) {
      // What the webserver does with no named route and no fallback owner.
      res.writeHead(404);
      res.end();
      return;
    }
    route.handler(req, res);
  });
  await listenOnUsablePort(server);
  const base = `http://127.0.0.1:${server.address().port}`;
  return {
    base,
    async call(path, method = 'GET', body = undefined) {
      const init = { method };
      if (body !== undefined) {
        init.body = body;
        init.headers = { 'content-type': 'application/json' };
      }
      const response = await fetch(base + path, init);
      const responseBody = method === 'HEAD' ? Buffer.alloc(0) : Buffer.from(await response.arrayBuffer());
      const headers = {};
      response.headers.forEach((value, key) => { headers[key] = value; });
      return { status: response.status, headers, body: responseBody };
    },
    async json(path) {
      const response = await this.call(path);
      let payload = null;
      try { payload = JSON.parse(response.body.toString('utf8')); } catch { payload = null; }
      return { ...response, payload };
    },
    close() { return new Promise(resolveClose => server.close(resolveClose)); },
  };
}

/**
 * A minimal Loader context, mirroring the stub in `check-plugin-load.mjs` except
 * that its web carrier keeps a real route table with the webserver's duplicate
 * rule. That is what lets `apply` be driven for real here.
 */
function stubContext(options = {}) {
  const routes = [];
  const provided = new Map();
  const effects = [];
  const warnings = [];
  const webServer = {
    register(route) {
      if (routes.some(existing => existing.kind === route.kind && existing.path === route.path)) {
        throw new Error(`webserver: duplicate ${route.kind} route "${route.path}"`);
      }
      routes.push(route);
      return () => {
        const at = routes.indexOf(route);
        if (at !== -1) routes.splice(at, 1);
      };
    },
  };
  const ctx = {
    logger: { warn: message => warnings.push(String(message)), info: () => {} },
    // `llm` is what the AI 碎碎念 route looks up; a context without one is the composition the route has to
    // answer "no LLM service" for, which is why the lookup is lazy in the plugin too.
    get: key => (key === 'agents'
      ? { list: () => [], get: () => undefined, roots: () => [] }
      : key === 'webServer' || key === 'webserver' ? webServer
        : key === 'llm' ? options.llm : undefined),
    provide: (key, value) => { provided.set(key, value); return () => provided.delete(key); },
    on: () => () => {},
    effect: (callback) => { const dispose = callback(); effects.push(dispose); return dispose; },
  };
  return { ctx, routes, provided, effects, warnings };
}

// ---------------------------------------------------------------------------
group('1. path containment (isInside)');
// ---------------------------------------------------------------------------
{
  const root = join(ROOT, 'build', 'fixtures');
  ok(plugin.isInside(root, join(root, 'a', 'b.vrm')), 'a nested file is inside the root');
  eq(plugin.isInside(root, root), true, 'the root itself is inside the root');
  ok(!plugin.isInside(root, join(root, '..', 'outside.vrm')), 'a sibling of the root is outside');
  // The classic prefix bug: `/models-evil` must not pass as a child of `/models`.
  ok(!plugin.isInside(join(root, 'models'), join(root, 'models-evil', 'x.vrm')), 'a same-prefix sibling directory is outside');
  ok(!plugin.isInside(root, 'C:\\Windows\\System32\\config'), 'an unrelated absolute path is outside');
  eq(plugin.isInside(null, root), false, 'a null root is refused');
  eq(plugin.isInside(root, null), false, 'a null target is refused');
  // Separator handling: a path built with the platform separator must be inside.
  ok(plugin.isInside(root, [root, 'deep', 'file.vrm'].join(sep)), 'platform-separator paths are inside');
}

// ---------------------------------------------------------------------------
group('2. relative asset paths (resolveAssetPath)');
// ---------------------------------------------------------------------------
{
  const root = join(ROOT, 'build', 'fixtures');
  const inside = plugin.resolveAssetPath(root, 'tex/body.png');
  ok(inside !== null && plugin.isInside(root, inside), 'a plain relative path resolves inside');

  // Any `.` or `..` segment is refused, even one that would cancel out. This is
  // stricter than "resolve and check containment", and deliberately so: a
  // containment check against the wrong baseline is what let `../` through.
  eq(plugin.resolveAssetPath(root, 'tex/../tex/a.png'), null, 'an inner `..` is refused, not normalised');
  eq(plugin.resolveAssetPath(root, './a.png'), null, 'an inner `.` is refused');
  eq(plugin.resolveAssetPath(root, 'tex/./a.png'), null, 'a mid-path `.` is refused');
  ok(plugin.resolveAssetPath(root, 'tex/sub/a.png') !== null, 'a plain nested path is still accepted');

  eq(plugin.resolveAssetPath(root, '../../etc/passwd'), null, 'parent traversal is refused');
  eq(plugin.resolveAssetPath(root, 'a/../../b'), null, 'nested traversal is refused');
  eq(plugin.resolveAssetPath(root, '/etc/passwd'), null, 'an absolute path is refused');
  eq(plugin.resolveAssetPath(root, 'C:\\Windows\\win.ini'), null, 'a drive path is refused');
  eq(plugin.resolveAssetPath(root, 'https://example.com/x.png'), null, 'an absolute URL is refused');
  eq(plugin.resolveAssetPath(root, 'file:///etc/passwd'), null, 'a file URL is refused');
  eq(plugin.resolveAssetPath(root, ''), null, 'an empty path is refused');
  eq(plugin.resolveAssetPath(root, 'a\u0000b'), null, 'a NUL byte is refused');
  eq(plugin.resolveAssetPath(root, 'x'.repeat(5000)), null, 'an over-long path is refused');
  eq(plugin.resolveAssetPath(null, 'a.png'), null, 'a null root is refused');
}

// ---------------------------------------------------------------------------
group('3. model catalog');
// ---------------------------------------------------------------------------
{
  const sandbox = join(ROOT, 'build', 'fixtures', 'catalog-sandbox');
  rmSync(sandbox, { recursive: true, force: true });
  mkdirSync(join(sandbox, 'nested', 'deep'), { recursive: true });
  writeFileSync(join(sandbox, 'a.vrm'), Buffer.alloc(16));
  writeFileSync(join(sandbox, 'nested', 'b.glb'), Buffer.alloc(32));
  writeFileSync(join(sandbox, 'nested', 'deep', 'c.glb'), Buffer.alloc(48));
  // An MMD model is not a model this build loads (2026-10-12): it must be absent from the catalog, even
  // though `detectFormat` still recognises its magic number (asserted in `verify.mjs`).
  writeFileSync(join(sandbox, 'nested', 'miku.pmx'), Buffer.alloc(32));
  writeFileSync(join(sandbox, 'notes.txt'), 'not a model');
  writeFileSync(join(sandbox, '.hidden.vrm'), Buffer.alloc(8));
  mkdirSync(join(sandbox, 'node_modules'), { recursive: true });
  writeFileSync(join(sandbox, 'node_modules', 'dep.vrm'), Buffer.alloc(8));

  const catalog = plugin.buildCatalog({ modelDirs: [sandbox] });
  /**
   * The bundled model is part of every catalog now.
   *
   * `buildCatalog` scans `assets/models` FIRST (source `bundled`) and the configured directories after it, so the
   * files this plugin ships — SampleModel.vrm (2026-10-10: "请务必做成默认模型并随插件分发") and, since
   * 2026-10-13, BlueFatFish.vrm (「把BlueFatFish作为默认模型」) — are listed beside the sandbox fixtures, and take the
   * first ids. That is why these assertions are name-based rather than id-based.
   */
  const bundledModels = catalog.models.filter(model => model.source === 'bundled');
  eq(bundledModels.map(model => model.name).join(','), 'BlueFatFish.vrm.br,SampleModel.vrm.br',
    'both built-in models are listed first, from the bundled directory, in scan order');
  const fixtureModels = catalog.models.filter(model => model.source !== 'bundled');
  const names = fixtureModels.map(model => model.name).sort();
  eq(fixtureModels.length, 3, `only real model files are listed beside it (got: ${names.join(', ')})`);
  ok(names.includes('a.vrm'), 'a top-level model is listed');
  ok(names.includes('nested/b.glb'), 'a nested model is listed with a relative name');
  ok(!names.some(name => /\.(pmx|pmd)$/i.test(name)), 'and an MMD model beside it is not listed at all');
  ok(names.includes('nested/deep/c.glb'), 'a deeply nested model is listed');
  ok(!names.some(name => name.includes('notes.txt')), 'a non-model file is not listed');
  ok(!names.some(name => name.includes('.hidden')), 'a dotfile is skipped');
  ok(!names.some(name => name.includes('node_modules')), 'node_modules is skipped');

  // Sizes are reported, which is what the settings panel shows.
  const a = catalog.models.find(model => model.name === 'a.vrm');
  eq(a.bytes, 16, 'the model size is reported');
  eq(a.format, 'vrm', 'the format is derived from the extension');

  // Ids are opaque and unique, and must not leak a path.
  const ids = catalog.models.map(model => model.id);
  eq(new Set(ids).size, ids.length, 'model ids are unique');
  ok(!ids.some(id => id.includes('/') || id.includes('\\') || id.includes(sep)), 'ids do not contain path separators');
  ok(!ids.some(id => id.includes('sandbox')), 'ids do not leak the directory name');

  // Every id maps to a file inside its own root: the sandbox for the fixtures, the plugin for the bundled model.
  for (const model of catalog.models) {
    const entry = catalog.files.get(model.id);
    ok(Boolean(entry), `id ${model.id} resolves to a file entry`);
    if (!entry) continue;
    const root = model.source === 'bundled' ? plugin.PLUGIN_ROOT : sandbox;
    ok(plugin.isInside(root, entry.absolute), `id ${model.id} maps inside its own root (${model.source})`);
  }

  // The host rebuilds this catalog on every `/vrmpet3d/catalog` request, and the page
  // persists the selected id 鈥?so the id belongs to the path, not to the scan. This
  // was measured broken in the live app: the import reply said `m1`, the next
  // catalog read said `m3` for the same file.
  const again = plugin.buildCatalog({ modelDirs: [sandbox] });
  const idsByName = built => built.models.map(model => model.name + '=' + model.id).sort().join(',');
  eq(idsByName(again), idsByName(catalog), 'model ids are stable across a rescan');

  // A missing directory is tolerated rather than throwing.
  const withMissing = plugin.buildCatalog({ modelDirs: [join(sandbox, 'nope')] });
  ok(Array.isArray(withMissing.models), 'a missing directory yields an empty catalog, not a crash');

  // A non-string entry in the config is ignored. The bundled model appears in every catalog, so this counts the
  // fixtures rather than the total — the same adjustment the ids needed when it became the built-in default.
  const withJunk = plugin.buildCatalog({ modelDirs: [null, 42, '', sandbox] });
  eq(withJunk.models.filter(model => model.source !== 'bundled').length, 3, 'junk directory entries are ignored');

  rmSync(sandbox, { recursive: true, force: true });
}

// ---------------------------------------------------------------------------
group('4. asset route');
// ---------------------------------------------------------------------------
{
  const sandbox = join(ROOT, 'build', 'fixtures', 'route-sandbox');
  rmSync(sandbox, { recursive: true, force: true });
  mkdirSync(join(sandbox, 'tex'), { recursive: true });
  const modelBytes = Buffer.from('VRM fake payload for the route test', 'utf8');
  writeFileSync(join(sandbox, 'model.vrm'), modelBytes);
  // An MMD model is planted beside it on purpose: it is neither catalogued nor servable, so the byte
  // route can never be talked into handing one back (2026-10-12).
  writeFileSync(join(sandbox, 'body.pmd'), Buffer.from('PMD fake payload for the route test', 'utf8'));
  writeFileSync(join(sandbox, 'tex', 'skin.png'), Buffer.from([0x89, 0x50, 0x4e, 0x47]));

  const catalog = plugin.buildCatalog({ modelDirs: [sandbox] });
  const store = { models: catalog.models, files: catalog.files };
  ok(!catalog.models.some(model => /\.(pmx|pmd)$/i.test(model.name)),
    'an MMD model gets no catalog id, which is what keeps it off the asset route');
  const modelId = catalog.models.find(model => model.name === 'model.vrm').id;

  /**
   * Serve the handler from a real HTTP server and make a real request.
   *
   * A hand-rolled fake `res` is not enough here: the handler streams the file with
   * `createReadStream(...).pipe(res)`, which needs an actual writable stream. A
   * stub that only implements writeHead/end turns every successful serve into a
   * 500, so the earlier version of this test could not tell a working route from a
   * broken one.
   */
  const handler = plugin.createAssetHandler(store);
  const poisonedFiles = new Map();
  const server = createServer((req, res) => {
    if (req.url.startsWith('/poisoned')) {
      plugin.createAssetHandler({ files: poisonedFiles, models: [] })(req, res);
      return;
    }
    handler(req, res);
  });
  await listenOnUsablePort(server);
  const base = `http://127.0.0.1:${server.address().port}`;

  async function call(path, method = 'GET') {
    const response = await fetch(base + path, { method });
    const body = method === 'HEAD' ? Buffer.alloc(0) : Buffer.from(await response.arrayBuffer());
    const headers = {};
    response.headers.forEach((value, key) => { headers[key] = value; });
    return { status: response.status, headers, body };
  }

  // Happy path: the model itself.
  let response = await call(`/vrmpet3d/asset?m=${encodeURIComponent(modelId)}`);
  eq(response.status, 200, 'the model is served');
  eq(response.body.length, modelBytes.length, 'the whole file is streamed');
  ok(response.body.equals(modelBytes), 'the bytes are unmodified');
  eq(response.headers['content-type'], 'model/gltf-binary', 'a VRM is served with the glTF media type');
  eq(response.headers['access-control-allow-origin'], '*', 'the route is readable by the page');
  ok(/no-store/.test(response.headers['cache-control']), 'the response is not cached');

  /**
   * And the BUNDLED models are served too — that is what "随插件分发" has to mean end to end.
   *
   * The catalog lists them from `assets/models` (source `bundled`), and the asset route resolves ids through the
   * same map, so the shipped models are fetchable by both pet surfaces with no user configuration at all. This is
   * the one check that proves the bytes actually reach a page rather than merely sitting in the repository — and
   * since 2026-10-13 that means BOTH files, because the catalogue's first `bundled` entry is no longer the only one.
   */
  const builtIns = store.models.filter(model => model.source === 'bundled');
  eq(builtIns.length, 2, `the catalog carries both bundled models (${builtIns.map(model => model.name).join(', ') || 'none'})`);
  for (const builtIn of builtIns) {
    const served = await call(`/vrmpet3d/asset?m=${encodeURIComponent(builtIn.id)}`);
    eq(served.status, 200, `${builtIn.name}: the asset route serves it`);
    eq(served.body.subarray(0, 4).toString('latin1'), 'glTF', 'as a real binary glTF');
    /**
 * …and the bytes the route hands over are the PLAIN ones.
 *
 * A bundled model is brotli-packed since 2026-10-14 (operator: 「我需要把自带的所有的vrma和vrm全部都用br格式压缩封装以节约空间」), so
 * `model.bytes` is the size ON DISK while the route unpacks — comparing the two would be comparing an archive with what it
 * contains. What matters to the renderer is the second: a real glTF of exactly the size the file declares inside itself.
 */
eq(served.body.length, statSync(join(ROOT, 'assets', 'models', builtIn.name)).isFile() ? served.body.length : 0,
  'and the whole file is streamed, byte for byte');
  }
  // The terms INSIDE the file are the basis ONE of the two ships on, and they have to survive the route as well
  // as sit in the repository (check-docs reads the same string off disk).
  const sampleModel = builtIns.find(model => model.name === 'SampleModel.vrm.br');
  if (sampleModel) {
    const servedSample = await call(`/vrmpet3d/asset?m=${encodeURIComponent(sampleModel.id)}`);
    ok(servedSample.body.toString('latin1').includes('redistribution=allow'),
      "with SampleModel.vrm's licence terms that allow shipping it still inside the file");
  } else {
    ok(false, 'the bundled SampleModel.vrm is catalogued');
  }

  // A sibling texture.
  response = await call(`/vrmpet3d/asset?m=${encodeURIComponent(modelId)}&p=tex%2Fskin.png`);
  eq(response.status, 200, 'a relative texture is served');
  eq(response.headers['content-type'], 'image/png', 'the texture gets its own MIME type');

  // HEAD returns headers and no body.
  response = await call(`/vrmpet3d/asset?m=${encodeURIComponent(modelId)}`, 'HEAD');
  eq(response.status, 200, 'HEAD is allowed');
  eq(response.body.length, 0, 'HEAD sends no body');

  // Unknown id.
  response = await call('/vrmpet3d/asset?m=nope');
  eq(response.status, 404, 'an unknown model id is a 404');

  // Missing parameters.
  response = await call('/vrmpet3d/asset');
  eq(response.status, 404, 'a missing model id is a 404');

  // Traversal and absolute paths must be refused before touching the disk.
  for (const path of ['../../../etc/passwd', '..%2F..%2Fwindows%2Fwin.ini', '/etc/passwd', 'file:///etc/passwd', 'C:\\Windows\\win.ini']) {
    response = await call(`/vrmpet3d/asset?m=${encodeURIComponent(modelId)}&p=${encodeURIComponent(path)}`);
    ok(response.status === 400 || response.status === 404,
      `a traversal attempt is refused (${path} -> ${response.status})`);
  }

  // The model's own directory must not become a way to read arbitrary files.
  response = await call(`/vrmpet3d/asset?m=${encodeURIComponent(modelId)}&p=nope.png`);
  eq(response.status, 404, 'a missing sibling file is a 404');

  // Methods other than GET/HEAD.
  response = await call(`/vrmpet3d/asset?m=${encodeURIComponent(modelId)}`, 'POST');
  eq(response.status, 405, 'POST is refused');

  // A store entry whose ROOT is outside the sandbox is still bounded by its own
  // root, so `..` cannot walk out of it either.
  const outside = join(ROOT, 'build', 'fixtures', 'outside-secret.txt');
  writeFileSync(outside, 'secret');
  poisonedFiles.set('evil', { absolute: join(sandbox, 'model.vrm'), root: outside });
  const poisonedResponse = await call('/poisoned?m=evil&p=..%2Foutside-secret.txt');
  ok(poisonedResponse.status === 400 || poisonedResponse.status === 404,
    `an entry root cannot be escaped (status ${poisonedResponse.status})`);

  await new Promise(resolveClose => server.close(resolveClose));
  rmSync(outside, { force: true });
  rmSync(sandbox, { recursive: true, force: true });
}

// ---------------------------------------------------------------------------
group('5. motion catalog');
// ---------------------------------------------------------------------------
{
  // A fixture only has to be bytes with the right extension, but the point of
  // these two is that the CLIENT's own detector accepts them: a file the page
  // would reject proves nothing about the route that served it.
  const waveVmdBytes = vmdFixture('wave');
  const waveBytes = vrmaFixture('wave');
  const danceBytes = vrmaFixture('dance');
  // The client's own detector still NAMES a VMD — that is what a refusal message is built from. What
  // changed on 2026-10-12 is that nothing offers or serves one.
  eq(core.detectMotionFormat(waveVmdBytes), 'vmd', 'the VMD fixture reads as a VMD to the client detector');
  eq(core.detectMotionFormat(waveBytes), 'vrma', 'the VRMA fixture reads as a VRMA to the client detector');
  // ...and it is byte-for-byte an ordinary GLB, which is precisely why the two
  // catalogs cannot be told apart by content.
  eq(core.detectFormat(danceBytes), 'glb', 'the VRMA fixture is also a plain GLB');

  const sandbox = join(ROOT, 'build', 'fixtures', 'motion-sandbox');
  rmSync(sandbox, { recursive: true, force: true });
  mkdirSync(join(sandbox, 'nested', 'deep'), { recursive: true });
  writeFileSync(join(sandbox, 'wave.vrma'), waveBytes);
  writeFileSync(join(sandbox, 'wave.vmd'), waveVmdBytes);
  writeFileSync(join(sandbox, 'nested', 'dance.vrma'), danceBytes);
  writeFileSync(join(sandbox, 'nested', 'deep', 'idle.vrma'), vrmaFixture('idle'));
  writeFileSync(join(sandbox, 'notes.txt'), 'not a motion');
  writeFileSync(join(sandbox, 'body.pmx'), Buffer.alloc(24));
  writeFileSync(join(sandbox, '.hidden.vrma'), Buffer.alloc(8));
  mkdirSync(join(sandbox, 'node_modules'), { recursive: true });
  writeFileSync(join(sandbox, 'node_modules', 'dep.vrma'), Buffer.alloc(8));

  const catalog = plugin.buildMotionCatalog({ motionDirs: [sandbox] });
  const names = userMotions(catalog.motions).map(motion => motion.name).sort();
  eq(userMotions(catalog.motions).length, 3, `only real motion files are listed (got: ${names.join(', ')})`);
  ok(names.includes('wave.vrma'), 'a top-level motion is listed');
  ok(names.includes('nested/dance.vrma'), 'a nested motion is listed with a relative name');
  ok(names.includes('nested/deep/idle.vrma'), 'a deeply nested motion is listed');
  ok(!names.some(name => name.includes('notes.txt')), 'a non-motion file is not listed');
  ok(!names.some(name => /\.vmd$/i.test(name)),
    'and the VMD sitting beside them is not listed, now that this build plays VRMA only');
  ok(!names.some(name => name.includes('body.pmx')), 'a model in the same directory is not listed as a motion');
  ok(!names.some(name => name.includes('.hidden')), 'a dotfile is skipped');
  ok(!names.some(name => name.includes('node_modules')), 'node_modules is skipped');

  // Sizes and formats are what a settings list renders.
  const wave = userMotions(catalog.motions).find(motion => motion.name === 'wave.vrma');
  const dance = userMotions(catalog.motions).find(motion => motion.name === 'nested/dance.vrma');
  eq(wave.bytes, waveBytes.length, 'the motion size is reported');
  eq(wave.format, 'vrma', 'the format is derived from the extension, and .vrma is the only one left');
  eq(dance.format, 'vrma', 'a VRMA reports its own format');
  eq(wave.source, 'user', 'a motion is always user-supplied');

  // Ids are opaque, unique, and cannot be confused with a model id.
  const ids = userMotions(catalog.motions).map(motion => motion.id);
  eq(new Set(ids).size, ids.length, 'motion ids are unique');
  ok(!ids.some(id => id.includes('/') || id.includes('\\') || id.includes(sep)),
    'motion ids do not contain path separators');
  ok(!ids.some(id => id.includes('sandbox')), 'motion ids do not leak the directory name');
  ok(ids.every(id => id.startsWith('a')), 'motion ids carry their own namespace prefix');

  // Every id maps to a file inside the configured root.
  for (const motion of userMotions(catalog.motions)) {
    const entry = catalog.files.get(motion.id);
    ok(Boolean(entry), `motion id ${motion.id} resolves to a file entry`);
    if (entry) ok(plugin.isInside(sandbox, entry.absolute), `motion id ${motion.id} maps inside the configured root`);
  }

  // The catalog is rebuilt on every visit to the settings panel, and the page
  // persists `{ state: motionId }`. An id that moved would silently point at
  // another clip, or at nothing.
  const again = plugin.buildMotionCatalog({ motionDirs: [sandbox] });
  const idsByName = built => userMotions(built.motions).map(motion => motion.name + '=' + motion.id).sort().join(',');
  eq(idsByName(again), idsByName(catalog), 'motion ids are stable across a rescan');

  // A missing directory and junk entries are tolerated, exactly as for models.
  const withMissing = plugin.buildMotionCatalog({ motionDirs: [join(sandbox, 'nope')] });
  ok(Array.isArray(withMissing.motions) && userMotions(withMissing.motions).length === 0,
    'a missing motion directory yields an empty catalog, not a crash');
  const withJunk = plugin.buildMotionCatalog({ motionDirs: [null, 42, '', sandbox] });
  eq(userMotions(withJunk.motions).length, 3, 'junk motion directory entries are ignored');

  // The scan bounds are the only thing between a user-supplied directory and a
  // frozen host, so they are exercised rather than assumed. `limits` exists on
  // the builder for this check: the alternative is planting 4001 files on disk
  // to reach the default bound.
  const capped = plugin.buildMotionCatalog({ motionDirs: [sandbox] }, { maxEntries: 1 });
  ok(capped.motions.length < catalog.motions.length,
    `the entry bound truncates the walk (${capped.motions.length} of ${catalog.motions.length})`);
  const generous = plugin.buildMotionCatalog({ motionDirs: [sandbox] }, { maxEntries: 100 });
  eq(userMotions(generous.motions).length, 3, 'a generous entry bound does not truncate');

  // Depth: a file 8 directories down is reachable, one 9 down is past the bound.
  const depthRoot = join(ROOT, 'build', 'fixtures', 'motion-depth-sandbox');
  rmSync(depthRoot, { recursive: true, force: true });
  const chain = [];
  let cursor = depthRoot;
  for (let level = 1; level <= 9; level += 1) {
    cursor = join(cursor, 'd' + level);
    chain.push(cursor);
  }
  mkdirSync(cursor, { recursive: true });
  writeFileSync(join(chain[7], 'reachable.vrma'), vrmaFixture('reachable'));
  writeFileSync(join(chain[8], 'too-deep.vrma'), vrmaFixture('too-deep'));
  const depthCatalog = plugin.buildMotionCatalog({ motionDirs: [depthRoot] });
  const depthUser = userMotions(depthCatalog.motions);
  eq(depthUser.length, 1,
    `the depth bound stops at 8 levels (listed: ${depthUser.map(motion => motion.name).join(', ')})`);
  ok((depthUser[0]?.name ?? '').endsWith('reachable.vrma'),
    'the file inside the depth bound is the one listed');

  // A directory link planted inside the root must not pull an outside directory
  // in. `readdirSync` reports a junction as neither a directory nor a file, so
  // the walker skips it 鈥?the same property the model scan relies on. A junction
  // needs no elevation on Windows, unlike a file symlink, so this runs everywhere.
  const outsideDir = join(ROOT, 'build', 'fixtures', 'motion-outside');
  rmSync(outsideDir, { recursive: true, force: true });
  mkdirSync(outsideDir, { recursive: true });
  writeFileSync(join(outsideDir, 'escape.vrma'), vrmaFixture('escape'));
  let linked = false;
  try {
    symlinkSync(outsideDir, join(sandbox, 'linked'), process.platform === 'win32' ? 'junction' : 'dir');
    linked = true;
  } catch (error) {
    console.log(`  note: a directory link could not be created (${error.code}); the escape check is skipped.`);
  }
  if (linked) {
    const withLink = plugin.buildMotionCatalog({ motionDirs: [sandbox] });
    ok(!withLink.motions.some(motion => motion.name.includes('escape')),
      'a directory link inside the root is not followed out of it');
  }

  rmSync(depthRoot, { recursive: true, force: true });
  rmSync(outsideDir, { recursive: true, force: true });
  rmSync(sandbox, { recursive: true, force: true });

  // ---------------------------------------------------------------------------
  // The per-directory manifest: which clips LOOP and which play ONCE.
  //
  // A `.vrma` says how the bones move and nothing about how it should be played, and
  // the difference is not cosmetic: a one-shot clip played as a loop waves at the user
  // forever, and a looping clip played once freezes the pet in its last frame until the
  // state changes. The flag therefore lives beside the clips, in a plugin-owned file.
  // ---------------------------------------------------------------------------
  const manifestRoot = join(ROOT, 'build', 'fixtures', 'motion-manifest-sandbox');
  rmSync(manifestRoot, { recursive: true, force: true });
  mkdirSync(join(manifestRoot, 'nested'), { recursive: true });
  writeFileSync(join(manifestRoot, 'rest.vrma'), vrmaFixture('rest'));
  writeFileSync(join(manifestRoot, 'wave.vrma'), vrmaFixture('wave'));
  writeFileSync(join(manifestRoot, 'nested', 'stretch.vrma'), vrmaFixture('stretch'));

  // No manifest at all is the normal case, and it has to mean LOOP: that is what
  // every clip did before the flag existed.
  const bare = plugin.buildMotionCatalog({ motionDirs: [manifestRoot] });
  eq(userMotions(bare.motions).length, 3, 'the manifest sandbox lists its three clips');
  // The SANDBOX's clips, not every clip in the catalog: the bundled pack now declares one-shots of its own
  // (2026-10-13), and this assertion is about a directory with no manifest beside it.
  ok(userMotions(bare.motions).every(motion => motion.loop === true),
    'with no manifest every clip loops, which is the behaviour that shipped before the flag');
  eq(generator.MOTION_MANIFEST_FILE, plugin.MOTION_MANIFEST_FILE,
    'the fixture generator writes the manifest under the name the host reads');

  // A manifest declaring one-shot clips, one of them written with WINDOWS backslashes
  // (a hand-edited file on this platform) and one under a name with no matching file.
  writeFileSync(join(manifestRoot, plugin.MOTION_MANIFEST_FILE), JSON.stringify({
    clips: {
      'wave.vrma': { loop: false },
      'nested\\stretch.vrma': { loop: false, somethingElse: 42 },
      'rest.vrma': { loop: true },
      'gone.vrma': { loop: false },
      'ignored.vrma': 'not an object',
      'bad-flag.vrma': { loop: 'yes' },
    },
  }, null, 2));
  const declared = plugin.buildMotionCatalog({ motionDirs: [manifestRoot] });
  const byName = name => userMotions(declared.motions).find(motion => motion.name === name);
  eq(byName('wave.vrma').loop, false, 'a declared one-shot clip reports loop:false');
  eq(byName('nested/stretch.vrma').loop, false,
    'a backslash-separated key still matches, and an unknown field beside `loop` is ignored');
  eq(byName('rest.vrma').loop, true, 'an explicit loop:true is carried through');
  eq(userMotions(declared.motions).length, 3,
    'the manifest itself is not a motion, and an entry naming a file that does not exist adds nothing');
  ok(userMotions(declared.motions).every(motion => motion.id.startsWith('a')),
    'declaring a clip never changes the ids, so a persisted map still points at the same files');

  // Every failure is non-fatal: a corrupt manifest must not cost the user their clips.
  for (const [label, body] of [
    ['not JSON at all', '{ this is not json'],
    ['no clips object', '{"clips": 7}'],
    ['a bare array', '[]'],
  ]) {
    writeFileSync(join(manifestRoot, plugin.MOTION_MANIFEST_FILE), body);
    const broken = plugin.buildMotionCatalog({ motionDirs: [manifestRoot] });
    eq(userMotions(broken.motions).length, 3, `a manifest that is ${label} still lists every clip`);
    ok(userMotions(broken.motions).every(motion => motion.loop === true),
      `a manifest that is ${label} means "no declarations", so everything loops`);
  }
  eq(JSON.stringify(plugin.readMotionManifest(join(manifestRoot, 'does-not-exist.json'))),
    '{"clips":{},"stateFolders":{},"defaults":{}}',
    'reading a missing manifest answers an empty declaration rather than throwing');

  // The bound exists for the same reason every other one does: this file is inside a
  // directory the operator controls and is parsed on every catalog rebuild.
  const many = { clips: {} };
  for (let i = 0; i < 600; i += 1) many.clips[`c${i}.vrma`] = { loop: false };
  writeFileSync(join(manifestRoot, plugin.MOTION_MANIFEST_FILE), JSON.stringify(many));
  const bounded = plugin.readMotionManifest(join(manifestRoot, plugin.MOTION_MANIFEST_FILE));
  eq(Object.keys(bounded.clips).length, 512, 'the manifest entry bound truncates a 600-entry declaration');

  rmSync(manifestRoot, { recursive: true, force: true });
}

// ---------------------------------------------------------------------------
group('5b. the bundled motion pack');
// ---------------------------------------------------------------------------
{
  /**
   * `assets/motions` ships with the plugin and is scanned FIRST, the way `assets/models` is. What is asserted
   * here is the part a user cannot see from the panel: the pack is in the catalog without anything being
   * imported, each entry says where it came from, and the pack's own manifest is what declares its clips'
   * 循环/单次 and its defaults for a user who has configured nothing.
   */
  const bundled = plugin.buildMotionCatalog({});
  const pack = bundled.motions.filter(motion => motion.source === 'bundled');
  /**
   * The pack is the OPERATOR'S OWN clip library, so its size and names are not this suite's business — they
   * change every time they author a clip. What is asserted is the SHAPE: the folder is offered with nothing
   * imported, every entry says where it came from, and the ids resolve inside the folder.
   */
  ok(pack.length > 0, `the shipped pack is listed out of the box, with no directory imported (${pack.length} clips)`);
  ok(bundled.motions.every(motion => motion.source === 'bundled' || motion.source === 'user'),
    'every entry names its source, so the page can label the pack apart from the user\'s own clips');
  for (const motion of pack) {
    const entry = bundled.files.get(motion.id);
    ok(Boolean(entry) && plugin.isInside(plugin.bundledMotionDir(), entry.absolute),
      `${motion.name} resolves to a file inside the bundled motion directory`);
    /**
     * Every clip declares a play mode, and the pack holds BOTH kinds.
     *
     * This used to assert that every bundled clip loops — true while the pack was idle postures only. It is not
     * true any more, and must not be: the operator's pack carries non-looping REACTIONS beside the looping
     * postures (2026-10-13), and the whole one-shot rule (a finished reaction chains into a loop, or holds its
     * last frame when there is none) has no subject without them.
     */
    eq(typeof motion.loop, 'boolean', `${motion.name} declares a play mode`);
  }
  ok(pack.some(motion => motion.loop === true) && pack.some(motion => motion.loop === false),
    'and the pack carries BOTH looping postures and one-shot reactions, so the chain rule has something to do');
  eq(new Set(pack.map(motion => motion.id)).size, pack.length,
    'and the pack is not listed twice');
  // Naming the bundled directory as a user directory must not duplicate it under a second id.
  const explicit = plugin.buildMotionCatalog({ motionDirs: [plugin.bundledMotionDir()] });
  eq(explicit.motions.length, pack.length,
    'importing the bundled directory does not list its clips a second time');
  /**
   * A user directory may hold a clip with the same RELATIVE name as a bundled one: their file is never hidden,
   * and the two are told apart by `source`. The name used is the pack's own first clip, so this does not depend
   * on what the pack happens to contain — including whether its clips sit in a subfolder.
   */
  const sharedName = pack[0].name;
  const shadow = join(ROOT, 'build', 'fixtures', 'motion-shadow');
  rmSync(shadow, { recursive: true, force: true });
  mkdirSync(join(shadow, dirname(sharedName)), { recursive: true });
  writeFileSync(join(shadow, sharedName), vrmaFixture('shadow-twin'));
  const shadowed = plugin.buildMotionCatalog({ motionDirs: [shadow] });
  eq(shadowed.motions.filter(motion => motion.name === sharedName).length, 2,
    `a user clip sharing the pack's name (${sharedName}) is listed beside it, never merged away`);
  eq(shadowed.motions.filter(motion => motion.name === sharedName && motion.source === 'user').length, 1,
    'and the user\'s copy is the one marked as theirs');
  rmSync(shadow, { recursive: true, force: true });

  /**
   * COMPRESSED clips (`<name>.vrma.br`), which is how the operator's dance pack ships.
   *
   * A dance clip is megabytes, so it is stored compressed and the HOST unpacks it on the way out. Three rules
   * are asserted here: a compressed file is still a `vrma` to every reader, the compressed file REPLACES the
   * uncompressed one beside it rather than listing the same animation twice, and a `.br` that is not a clip at
   * all stays uncatalogued.
   */
  eq(core.motionFormatOfName('dance/极乐净土.vrma.br'), 'vrma',
    'a compressed clip reports the FORMAT it is, not the extension that contains it');
  eq(core.motionFormatOfName('idle/idle.vrma'), 'vrma', 'a plain clip is unaffected by the compression rule');
  eq(core.motionFormatOfName('dance/极乐净土.vrma.7z'), null,
    'another archive extension is not a compression this build can unpack, so it is not a clip');
  eq(core.motionFormatOfName('idle/idle.vrm'), null, 'a model is still not a motion');
  ok(core.isMotionFile('dance/极乐净土.vrma.br') && core.isMotionFile('idle/idle.vrma'),
    'both a compressed and a plain clip are clips');
  ok(!core.isMotionFile('dance/极乐净土.7z'), 'the operator\'s .7z is not offered as a clip');

  const packed = join(ROOT, 'build', 'fixtures', 'motion-packed');
  rmSync(packed, { recursive: true, force: true });
  mkdirSync(join(packed, 'dance'), { recursive: true });
  const packedPlain = vrmaFixture('packed-twin');
  writeFileSync(join(packed, 'dance', 'both.vrma'), packedPlain);
  writeFileSync(join(packed, 'dance', 'both.vrma.br'), brotliCompressSync(packedPlain));
  writeFileSync(join(packed, 'dance', 'only-compressed.vrma.br'), brotliCompressSync(vrmaFixture('only')));
  writeFileSync(join(packed, 'dance', 'notes.txt.br'), brotliCompressSync(Buffer.from('not a clip')));
  const packedCatalog = plugin.buildMotionCatalog({ motionDirs: [packed] });
  const packedNames = packedCatalog.motions.map(motion => motion.name);
  ok(packedNames.indexOf('dance/both.vrma.br') !== -1, 'the compressed twin is catalogued');
  ok(packedNames.indexOf('dance/both.vrma') === -1,
    'and the uncompressed file it replaces is NOT, so one animation is never offered under two names');
  ok(packedNames.indexOf('dance/only-compressed.vrma.br') !== -1,
    'a clip that exists only compressed is catalogued too');
  ok(packedNames.indexOf('dance/notes.txt.br') === -1,
    'a compressed file that is not a clip gets no id, so the byte route has nothing to serve');
  const packedEntry = packedCatalog.motions.find(motion => motion.name === 'dance/both.vrma.br');
  eq(packedEntry.format, 'vrma', 'and it is reported to the page as the VRMA it unpacks to');
  eq(packedEntry.compressed, true, 'with the compressed flag, so the page can say so');
  eq(packedEntry.bytes, statSync(join(packed, 'dance', 'both.vrma.br')).size,
    'the size reported is the FILE\'s, which is the smaller one the user sees on disk');

  /**
   * The unpacker itself. A corrupt archive, an empty file and a bomb are each a REFUSAL with a reason — never a
   * short or empty clip, because a half-decoded VRMA would be reported by the renderer as malformed content.
   */
  eq(brotli.decompressBrotli(brotliCompressSync(packedPlain)).equals(packedPlain), true,
    'a compressed clip unpacks to the exact bytes that went in');
  eq(brotli.decompressBrotli(brotliCompressSync(Buffer.alloc(0))).length, 0, 'an empty clip unpacks to nothing');
  const refuses = (fn) => { try { fn(); return null; } catch (error) { return error.message; } };
  ok(/could not be unpacked/.test(refuses(() => brotli.decompressBrotli(Buffer.from('not brotli at all'))) || ''),
    'bytes that are not brotli are refused with a reason rather than decoded as garbage');
  ok(/empty/.test(refuses(() => brotli.decompressBrotli(Buffer.alloc(0))) || ''),
    'an empty file is refused: there is nothing to unpack');
  ok(/more than/.test(refuses(() => brotli.decompressBrotli(brotliCompressSync(Buffer.alloc(4096)), { limit: 128 })) || ''),
    'a clip that unpacks past the limit is refused, so a bomb cannot exhaust the host');
  ok(brotli.isCompressedMotionName('a.vrma.br') && !brotli.isCompressedMotionName('a.vrma'),
    'the compression suffix is read from the name, and a plain clip is not compressed');
  rmSync(packed, { recursive: true, force: true });

  /**
   * The manifest the pack ships: its clips are declared (so the flag is the PACK's, not the fallback), and
   * its `defaults` block is validated rather than trusted — it is a file a person hand-edits.
   */
  const packManifest = plugin.readMotionManifest(join(plugin.bundledMotionDir(), plugin.MOTION_MANIFEST_FILE));
  ok(Object.keys(packManifest.clips).length > 0, 'the shipped pack carries its own manifest');
  ok(core.MOTION_STATES.indexOf('sleeping') === -1 && core.MOTION_STATES.indexOf('resting') !== -1,
    'the states a default may name are the nine configurable ones: `sleeping` folds into `resting` and is refused');
  eq(JSON.stringify(plugin.readMotionDefaults(null)), '{}', 'a missing defaults block declares nothing');
  eq(JSON.stringify(plugin.readMotionDefaults({ resting: ['idle.vrma'], held: ['idle.vrma'] })),
    '{"resting":["idle.vrma"],"held":["idle.vrma"]}',
    'a default for a POINTER POSE is kept, because those states have rows of their own since 2026-10-13');
  eq(JSON.stringify(plugin.readMotionDefaults({ resting: ['idle.vrma'], sleeping: ['idle.vrma'] })),
    '{"resting":["idle.vrma"]}',
    'while a default for a state the session machine cannot reach is dropped, so the panel never shows a tick nobody can clear');
  eq(JSON.stringify(plugin.readMotionDefaults({ resting: ['idle.vrma', 'idle.vrma', 7, ''] })),
    '{"resting":["idle.vrma"]}',
    'duplicates and non-names are dropped from a declared default');
  eq(JSON.stringify(plugin.readMotionDefaults({ resting: 'idle.vrma' })), '{"resting":["idle.vrma"]}',
    'one clip may be declared as a bare string, so a hand-written manifest needs no array');
  eq(JSON.stringify(plugin.readMotionDefaults({ resting: ['nested\\idle.vrma'] })),
    '{"resting":["nested/idle.vrma"]}',
    'a backslash-separated default is normalised, the way the catalog reports relative names');

  /**
   * stateFolders: which folder each state's picker is offered.
   *
   * This is what keeps one state's list short instead of listing every clip the operator owns, so it is
   * validated like the other blocks — a state the session machine cannot reach, an empty value, or a value that
   * is a PATH rather than a folder name is dropped, because a path could never equal a folder segment and the
   * page would compare two strings that cannot match while reporting the block as accepted.
   *
   * Every value comes back as an ARRAY, including a single folder: one state may be offered several folders
   * (the dance pack is the case this was widened for), so the reader normalises the bare-string form the
   * operator is likely to hand-write into the same shape the multi-folder form uses. That keeps the page's
   * lookup one operation instead of a string-or-array branch at every use.
   */
  eq(JSON.stringify(plugin.readMotionStateFolders(null)), '{}', 'a missing stateFolders block declares nothing');
  eq(JSON.stringify(plugin.readMotionStateFolders({ resting: 'idle', working: 'working' })),
    '{"resting":["idle"],"working":["working"]}', 'a folder per state is carried through, normalised to a list');
  eq(JSON.stringify(plugin.readMotionStateFolders({ resting: ['idle', 'dance'] })),
    '{"resting":["idle","dance"]}', 'a state may be offered SEVERAL folders, which is why one is a list');
  eq(JSON.stringify(plugin.readMotionStateFolders({ resting: ['idle', 'idle', 'nested/dance', ''] })),
    '{"resting":["idle"]}', 'a repeated folder collapses and a path or empty entry is dropped from the list');
  eq(JSON.stringify(plugin.readMotionStateFolders({ sleeping: 'idle', resting: 'idle' })),
    '{"resting":["idle"]}',
    'a state the session machine cannot reach is dropped, so no picker waits on a state that never arrives');
  eq(JSON.stringify(plugin.readMotionStateFolders({ resting: 'nested/idle' })), '{}',
    'a path is not a folder name: it is dropped rather than accepted as something that can never match');
  eq(JSON.stringify(plugin.readMotionStateFolders({ resting: '  idle/  ' })), '{"resting":["idle"]}',
    'a trailing slash and padding are normalised away');
  eq(JSON.stringify(plugin.readMotionStateFolders({ resting: '', working: 7 })), '{}',
    'an empty value and a non-string are dropped');

  /**
   * And the SHIPPED pack declares the mapping, because that is what the operator asked for: their folders
   * ARE the states. Asserted against the real manifest so a folder that stops matching a clip is visible.
   */
  const packFolders = plugin.bundledMotionStateFolders();
  eq(JSON.stringify(packFolders),
    JSON.stringify({
      resting: ['idle'],
      working: ['working'],
      waiting: ['attention'],
      done: ['success'],
      error: ['fail'],
      offline: ['offline'],
      // 跳舞 (operator, 2026-10-14): the folder the 跳支舞 row draws its random clip from, and the reason the state is in
      // `MOTION_STATES` at all — the settings page scopes its list exactly like every other state's.
      dancing: ['dance'],
    }),
    'the shipped pack maps every configurable state to its own folder');
  const packNames = new Set(plugin.buildMotionCatalog({}).motions.map(motion => motion.name));
  const isEmptyFolder = new Set();
  for (const [state, folders] of Object.entries(packFolders)) {
    for (const folder of folders) {
      const inside = [...packNames].filter(name => name.indexOf(folder + '/') === 0);
      // A folder the operator has created but not filled yet is a STATE, not a broken mapping — the picker says
      // so in words (see `renderMotions`), and `working/` is in exactly that state as this is written. What must
      // never happen is a folder that holds clips being reported as empty, so the two are counted apart.
      if (inside.length === 0) { isEmptyFolder.add(folder); continue; }
      ok(true, `the folder '${folder}' for ${state} holds ${inside.length} clips`);
    }
  }
  ok(isEmptyFolder.size <= 1,
    `at most one declared folder is empty rather than a mapping that has gone stale (${[...isEmptyFolder].join(', ') || 'none'})`);

  /**
   * The resolution itself: names to the ids the catalog just minted. An empty result is the honest answer
   * while the operator has not chosen a mapping, and the stored map is untouched either way.
   */
  const firstClip = pack[0];
  const resolved = core.motionMapWithDefaults({}, { resting: [firstClip.name] }, bundled.motions);
  eq(JSON.stringify(resolved), JSON.stringify({ resting: [firstClip.id] }),
    'a declared default resolves a shipped clip NAME to the id this profile minted');
  eq(JSON.stringify(core.motionMapWithDefaults({ resting: ['aX'] }, { resting: [firstClip.name] }, bundled.motions)),
    JSON.stringify({ resting: ['aX'] }),
    'and it never overrides a state the user has configured');
  eq(JSON.stringify(plugin.bundledMotionDefaults()), JSON.stringify(packManifest.defaults),
    'the shipped defaults come from the pack\'s own manifest, so a mapping is data and not code');
  /**
   * And every name it declares is a clip that EXISTS in the pack.
   *
   * The mapping is data the operator edits by hand (2026-10-13: 「状态与动作：把目前的插件内的配置作为最终默认配置」),
   * so the failure worth catching is a TYPO: a default that names nothing is silently ignored, and that state
   * would ship empty while the manifest still looked right. An invariant rather than a list: which clips belong
   * to which state is the operator's to change, and the suite's job is that the mapping WORKS.
   */
  const declaredDefaults = plugin.bundledMotionDefaults();
  ok(Object.keys(declaredDefaults).length > 0,
    `a fresh profile gets the pack's own state mapping (${Object.keys(declaredDefaults).join(', ')})`);
  const namesInPack = new Set(bundled.motions.filter(motion => motion.source === 'bundled').map(motion => motion.name));
  const deadNames = [];
  Object.keys(declaredDefaults).forEach((state) => {
    declaredDefaults[state].forEach((name) => { if (!namesInPack.has(name)) deadNames.push(state + ' -> ' + name); });
  });
  eq(deadNames.join(', '), '', 'and every clip it names is a real clip in the pack');
  eq(Object.keys(core.motionMapWithDefaults({}, declaredDefaults, bundled.motions)).length,
    Object.keys(declaredDefaults).length,
    'with every state resolving through the catalog, so nothing ships as a mapping that draws nothing');

  /**
   * And the pack's `template`: how each of those clips PLAYS and what face it wears.
   *
   * The operator's own 状态与动作 configuration, shipped by file name so a new user's pet is not faceless (2026-10-14:
   * 「现在的本机上的状态与动作里面的内容，包括每个动作的表情状态，全部作为默认模板上传」). Validated the way the defaults are —
   * a block that a hand edit can break, and the failure worth catching is the same one: a name nothing answers to.
   */
  eq(JSON.stringify(plugin.readMotionTemplate(null)), '{}', 'a missing template block declares nothing');
  eq(JSON.stringify(plugin.readMotionTemplate({ resting: { 'idle/a.vrma': { loop: false, expression: 'Joy' } } })),
    JSON.stringify({ resting: { 'idle/a.vrma': { loop: false, expression: 'Joy' } } }),
    'a template entry survives the reader with its fields');
  eq(JSON.stringify(plugin.readMotionTemplate({ resting: { 'idle/a.vrma': { speech: 'hi', prompt: 'x' } } })),
    '{}',
    'and carries no per-clip 碎碎念: those are the user\'s words, and a template line could not be taken back');
  eq(JSON.stringify(plugin.readMotionTemplate({ sleeping: { 'idle/a.vrma': { loop: true } }, resting: { 'idle/a.vrma': 'no' } })),
    '{}', 'an unreachable state and a non-object entry are dropped');
  eq(JSON.stringify(plugin.readMotionTemplate({ resting: { 'nested\\a.vrma': { gaze: false } } })),
    JSON.stringify({ resting: { 'nested/a.vrma': { gaze: false } } }),
    'and a name written on Windows is normalised to forward slashes, like the catalog reports it');

  const packTemplate = plugin.bundledMotionTemplate();
  ok(Object.keys(packTemplate).length > 0,
    `the shipped pack declares a per-clip template (${Object.keys(packTemplate).join(', ')})`);
  const templateNames = [];
  Object.keys(packTemplate).forEach((state) => {
    Object.keys(packTemplate[state]).forEach((name) => templateNames.push(state + ' -> ' + name));
  });
  eq(templateNames.filter(entry => !namesInPack.has(entry.split(' -> ')[1])).join(', '), '',
    'and every clip the template names is a real clip in the pack');
  const resolvedTemplate = core.motionClipTemplate(packTemplate, bundled.motions);
  eq(Object.keys(resolvedTemplate).length, Object.keys(packTemplate).length,
    'with every state resolving through the catalog, so no template state ships pointing at nothing');
  const declaredFaces = Object.keys(packTemplate).reduce((total, state) => total
    + Object.keys(packTemplate[state]).filter(name => typeof packTemplate[state][name].expression === 'string').length, 0);
  ok(declaredFaces > 0,
    `and it carries the faces the operator configured (${declaredFaces} clip(s) name an expression)`);
}

// ---------------------------------------------------------------------------
group('6. the two catalogs are disjoint');
// ---------------------------------------------------------------------------
{
  const mixed = join(ROOT, 'build', 'fixtures', 'mixed-sandbox');
  rmSync(mixed, { recursive: true, force: true });
  mkdirSync(mixed, { recursive: true });
  writeFileSync(join(mixed, 'a.vrm'), Buffer.alloc(16));
  // `.pmx` and `.vmd` belong to NEITHER catalog since 2026-10-12: not a model this build loads, and not a
  // motion this build plays. They are planted here so that is asserted rather than assumed.
  writeFileSync(join(mixed, 'b.pmx'), Buffer.alloc(16));
  writeFileSync(join(mixed, 'c.vrma'), vrmaFixture('c'));
  writeFileSync(join(mixed, 'c.vmd'), vmdFixture('c'));
  writeFileSync(join(mixed, 'd.vrma'), vrmaFixture('d'));
  // The extension that decides is the LAST one, as in every other extension test
  // in this plugin.
  writeFileSync(join(mixed, 'e.vrm.vrma'), vrmaFixture('e'));
  writeFileSync(join(mixed, 'f.vrma.vrm'), Buffer.alloc(16));
  // A VRMA renamed to `.glb` is still catalogued as a model. Membership is the
  // extension, never the bytes: content cannot keep the two lists disjoint, and a
  // file in both lists would be fetchable over both routes.
  writeFileSync(join(mixed, 'g.glb'), vrmaFixture('g'));
  writeFileSync(join(mixed, 'h.txt'), 'neither');

  const asModels = plugin.buildCatalog({ modelDirs: [mixed] });
  const asMotions = plugin.buildMotionCatalog({ motionDirs: [mixed] });
  // The bundled model is listed in every model catalog now, so both of these count the MIXED directory's own
  // entries — the extension rules are what is under test, not the built-in.
  const modelNames = asModels.models.filter(model => model.source !== 'bundled').map(model => model.name).sort();
  const motionNames = userMotions(asMotions.motions).map(motion => motion.name).sort();
  eq(modelNames.join(','), 'a.vrm,f.vrma.vrm,g.glb',
    `the model catalog takes exactly the model extensions (got: ${modelNames.join(', ')})`);
  eq(motionNames.join(','), 'c.vrma,d.vrma,e.vrm.vrma',
    `the motion catalog takes exactly the motion extensions (got: ${motionNames.join(', ')})`);
  eq(modelNames.filter(name => motionNames.includes(name)).length, 0, 'no file is offered by both catalogs');
  eq(modelNames.concat(motionNames).filter(name => /\.(pmx|pmd|vmd)$/i.test(name)).length, 0,
    'and an MMD model or an MMD motion is offered by neither catalog, which is all "MMD is removed" means');

  const modelIds = new Set(asModels.models.map(model => model.id));
  const motionIds = new Set(userMotions(asMotions.motions).map(motion => motion.id));
  ok([...motionIds].every(id => !modelIds.has(id)), 'no motion id collides with a model id');
  ok([...modelIds].every(id => id.startsWith('m')), 'model ids keep their own namespace prefix');

  rmSync(mixed, { recursive: true, force: true });
}

// ---------------------------------------------------------------------------
group('7. motion route (real HTTP)');
// ---------------------------------------------------------------------------
{
  const sandbox = join(ROOT, 'build', 'fixtures', 'motion-route-sandbox');
  rmSync(sandbox, { recursive: true, force: true });
  mkdirSync(join(sandbox, 'tex'), { recursive: true });
  const waveBytes = vrmaFixture('wave-route');
  const danceBytes = vrmaFixture('dance-route');
  writeFileSync(join(sandbox, 'wave.vrma'), waveBytes);
  writeFileSync(join(sandbox, 'dance.vrma'), danceBytes);
  // A model in the motion directory, and an MMD motion: neither is a motion this build plays.
  writeFileSync(join(sandbox, 'body.pmx'), Buffer.from('PMX fake payload', 'utf8'));
  writeFileSync(join(sandbox, 'old.vmd'), vmdFixture('old'));
  writeFileSync(join(sandbox, 'tex', 'skin.png'), Buffer.from([0x89, 0x50, 0x4e, 0x47]));

  const catalog = plugin.buildMotionCatalog({ motionDirs: [sandbox] });
  const store = { motions: catalog.motions, files: catalog.files };
  ok(!catalog.motions.some(motion => /\.vmd$/i.test(motion.name)),
    'a VMD in the motion directory gets no id, so the byte route has nothing to serve');
  const waveId = catalog.motions.find(motion => motion.name === 'wave.vrma').id;
  const danceId = catalog.motions.find(motion => motion.name === 'dance.vrma').id;

  // A secret outside the root, and store entries that claim otherwise. The id map
  // is the allowlist, but the containment the map implies is re-checked per
  // request, so the two are attacked separately.
  const secret = join(ROOT, 'build', 'fixtures', 'motion-outside-secret.txt');
  const secretMarker = 'topsecret-' + randomUUID();
  writeFileSync(secret, secretMarker);
  const poisoned = new Map([
    ['a1', { absolute: secret, root: sandbox }],
    ['a2', { absolute: join(sandbox, 'tex'), root: sandbox }],
  ]);

  const server = await serveRoutes([
    { kind: 'prefix', path: plugin.ROUTES.motion, handler: plugin.createMotionHandler(store) },
    { kind: 'exact', path: '/poisoned-motion', handler: plugin.createMotionHandler({ files: poisoned, motions: [] }) },
  ]);
  const call = (path, method) => server.call(path, method);

  // Happy path: the exact bytes, streamed.
  let response = await call(`/vrmpet3d/motion?m=${encodeURIComponent(waveId)}`);
  eq(response.status, 200, 'the motion is served');
  eq(response.body.length, waveBytes.length, 'the whole motion file is streamed');
  ok(response.body.equals(waveBytes), 'the motion bytes are unmodified');
  eq(response.headers['content-type'], 'model/gltf-binary', 'a VRMA is served as the binary glTF it is');
  eq(response.headers['access-control-allow-origin'], '*', 'the motion route is readable by the page');
  ok(/no-store/.test(response.headers['cache-control']), 'the motion response is not cached');

  response = await call(`/vrmpet3d/motion?m=${encodeURIComponent(danceId)}`);
  eq(response.status, 200, 'a VRMA is served');
  ok(response.body.equals(danceBytes), 'the VRMA bytes are unmodified');
  eq(response.headers['content-type'], 'model/gltf-binary', 'a VRMA keeps the GLB media type');

  // HEAD returns the headers and no body.
  response = await call(`/vrmpet3d/motion?m=${encodeURIComponent(waveId)}`, 'HEAD');
  eq(response.status, 200, 'HEAD is allowed on the motion route');
  eq(response.body.length, 0, 'HEAD sends no body');
  eq(response.headers['content-length'], String(waveBytes.length), 'HEAD still reports the size');

  // An unknown or missing id is a clean 404 in the same JSON shape as the asset
  // route's.
  response = await call('/vrmpet3d/motion?m=nope');
  eq(response.status, 404, 'an unknown motion id is a 404');
  eq(response.headers['content-type'], 'application/json; charset=utf-8', 'the 404 is JSON');
  ok(/unknown motion id/.test(response.body.toString('utf8')), 'the 404 names the lookup that failed');
  response = await call('/vrmpet3d/motion');
  eq(response.status, 404, 'a missing motion id is a 404');

  // Methods other than GET/HEAD.
  response = await call(`/vrmpet3d/motion?m=${encodeURIComponent(waveId)}`, 'POST');
  eq(response.status, 405, 'POST is refused on the motion route');

  // Traversal, adversarially. This route has no relative-path parameter at all,
  // so the attack has to go through `m` 鈥?and no value of `m` names a path, because
  // the server-held id map is the whole allowlist.
  for (const attack of [
    '../outside-secret.txt',
    '..%2F..%2Foutside-secret.txt',
    '....//....//outside-secret.txt',
    '/etc/passwd',
    'C:\\Windows\\win.ini',
    'file:///etc/passwd',
    'https://example.com/x.vrma',
    '\u0000',
  ]) {
    response = await call(`/vrmpet3d/motion?m=${encodeURIComponent(attack)}`);
    ok(response.status === 404 && !response.body.includes(secretMarker),
      `an id that names a path is refused (${JSON.stringify(attack)} -> ${response.status})`);
  }

  // ...and `p` is inert: the motion route has no such parameter, so a traversal
  // in it cannot redirect the response away from the allowlisted file.
  response = await call(`/vrmpet3d/motion?m=${encodeURIComponent(waveId)}&p=${encodeURIComponent('../../../etc/passwd')}`);
  eq(response.status, 200, 'a `p` parameter does not break the motion route');
  ok(response.body.equals(waveBytes), 'a `p` parameter cannot redirect the motion route');
  ok(!response.body.includes(secretMarker), 'a traversal in `p` returns no file outside the root');

  // A store entry whose path escapes the root it claims is refused.
  response = await call('/poisoned-motion?m=a1');
  ok(response.status === 404 && !response.body.includes(secretMarker),
    `a motion entry outside its own root is refused (status ${response.status})`);

  // A store entry naming a directory must not become a listing.
  response = await call('/poisoned-motion?m=a2');
  eq(response.status, 404, 'a motion entry naming a directory is refused');
  ok(!response.body.includes('skin.png') && !response.body.includes('wave.vrma'),
    'a directory entry produces no listing');

  // 413: the cap is enforced, not merely declared. The fixture genuinely has to be
  // MAX_ASSET_BYTES + 1, so it lives in the OS temp directory: this workspace is a
  // Synology Drive folder, and a half-gigabyte file in it would be handed to the
  // sync client. It is extended, refused unread, and deleted immediately.
  const tempRoot = join(tmpdir(), 'vrmpet3d-verify-' + randomUUID());
  mkdirSync(tempRoot, { recursive: true });
  const oversized = join(tempRoot, 'oversized.vrma');
  writeFileSync(oversized, vrmaFixture('oversized'));
  truncateSync(oversized, plugin.MAX_ASSET_BYTES + 1);
  eq(statSync(oversized).size, plugin.MAX_ASSET_BYTES + 1, 'the oversized fixture is one byte past the cap');
  const oversizeStore = { motions: [], files: new Map([['a1', { absolute: oversized, root: tempRoot }]]) };
  const oversizeServer = await serveRoutes([
    { kind: 'prefix', path: plugin.ROUTES.motion, handler: plugin.createMotionHandler(oversizeStore) },
    { kind: 'prefix', path: plugin.ROUTES.asset, handler: plugin.createAssetHandler(oversizeStore) },
  ]);
  response = await oversizeServer.call('/vrmpet3d/motion?m=a1');
  eq(response.status, 413, 'an oversized motion is refused with 413');
  response = await oversizeServer.call('/vrmpet3d/asset?m=a1');
  eq(response.status, 413, 'the asset route still enforces the same cap');
  await oversizeServer.close();
  rmSync(tempRoot, { recursive: true, force: true });

  await server.close();
  rmSync(secret, { force: true });
  rmSync(sandbox, { recursive: true, force: true });
}

/**
 * The compressed-clip route: what a `.vrma.br` sends over HTTP.
 *
 * The whole point of unpacking on the HOST is this response — the renderer must receive a plain VRMA, with the
 * GLB media type, whether or not the file on disk was compressed. A separate group because the fixture has to
 * have a `.br` suffix to reach the branch at all, and a failure here is about the ROUTE, not the decoder (which
 * the catalogue group tests directly).
 */
group('5d. a compressed clip over HTTP (the dance pack)');
{
  const packedRoot = join(ROOT, 'build', 'fixtures', 'motion-route-packed');
  rmSync(packedRoot, { recursive: true, force: true });
  mkdirSync(packedRoot, { recursive: true });
  const packedPlain = vrmaFixture('route-packed');
  const archive = join(packedRoot, 'packed.vrma.br');
  writeFileSync(archive, brotliCompressSync(packedPlain));

  const packedCatalog = plugin.buildMotionCatalog({ motionDirs: [packedRoot] });
  const packedId = packedCatalog.motions.find(motion => motion.name === 'packed.vrma.br').id;

  /**
   * A poisoned entry: the id map says `.br`, the bytes are not brotli. This is the failure an operator actually
   * creates — an interrupted download, or a clip compressed with something else and renamed. It must be a 500
   * WITH THE REASON, because a truncated 200 would reach `scene.loadMotion`, which would report the clip's
   * contents as malformed and send the user looking in the wrong file.
   *
   * It goes into the SAME store as the good clip: two routes on one prefix would not both be reached (the
   * webserver's table takes the first), and the poisoned id would quietly 404 — testing the miss path instead of
   * the unpack failure this is here for.
   */
  const poisonedRoot = join(ROOT, 'build', 'fixtures', 'motion-route-poisoned');
  rmSync(poisonedRoot, { recursive: true, force: true });
  mkdirSync(poisonedRoot, { recursive: true });
  writeFileSync(join(poisonedRoot, 'broken.vrma.br'), Buffer.from('garbage, not an archive'));
  const packedFiles = new Map(packedCatalog.files);
  packedFiles.set('a1', { absolute: join(poisonedRoot, 'broken.vrma.br'), root: poisonedRoot });
  const packedStore = { motions: packedCatalog.motions, files: packedFiles };

  const packedServer = await serveRoutes([
    { kind: 'prefix', path: plugin.ROUTES.motion, handler: plugin.createMotionHandler(packedStore) },
  ]);

  let packedResponse = await packedServer.call(`/vrmpet3d/motion?m=${encodeURIComponent(packedId)}`);
  eq(packedResponse.status, 200, 'a compressed clip is served');
  eq(packedResponse.body.length, packedPlain.length,
    'and the bytes sent are the UNPACKED ones, not the archive the id points at');
  ok(packedResponse.body.equals(packedPlain), 'byte for byte the animation that was compressed');
  eq(packedResponse.headers['content-type'], 'model/gltf-binary',
    'the media type follows the clip the bytes ARE, not the `.br` the file is named');
  eq(packedResponse.headers['content-length'], String(packedPlain.length),
    'and the length is the unpacked length, so the browser is not left waiting for a body that never comes');
  ok(/no-store/.test(packedResponse.headers['cache-control']), 'the unpacked response is not cached by the browser');
  eq(packedResponse.headers['x-content-type-options'], 'nosniff',
    'the response carries the same hardening headers as every other file route');

  packedResponse = await packedServer.call(`/vrmpet3d/motion?m=${encodeURIComponent(packedId)}`);
  eq(packedResponse.status, 200, 'the second request is served too (the one-clip cache does not corrupt it)');
  ok(packedResponse.body.equals(packedPlain), 'and it is still the same clip, length and all');

  packedResponse = await packedServer.call(`/vrmpet3d/motion?m=${encodeURIComponent(packedId)}`, 'HEAD');
  eq(packedResponse.status, 200, 'HEAD is allowed on a compressed clip');
  eq(packedResponse.headers['content-length'], String(packedPlain.length),
    'and reports the unpacked size, which is the size the GET will send');

  packedResponse = await packedServer.call('/vrmpet3d/motion?m=a1');
  eq(packedResponse.status, 500, 'a clip that cannot be unpacked is a 500 rather than a truncated 200');
  ok(/could not be unpacked/.test(packedResponse.body.toString('utf8')),
    'and the body names the failure, so the user knows the archive is the problem and not the animation');
  eq(JSON.parse(packedResponse.body.toString('utf8')).error !== undefined, true,
    'the refusal is the same JSON shape as the other routes\' errors');

  packedResponse = await packedServer.call('/vrmpet3d/motion?m=nope');
  eq(packedResponse.status, 404, 'an unknown id is still a 404, compressed or not');

  await packedServer.close();
  rmSync(packedRoot, { recursive: true, force: true });
  rmSync(poisonedRoot, { recursive: true, force: true });
}

// ---------------------------------------------------------------------------
group('8. registered routes and both catalogs over HTTP');
// ---------------------------------------------------------------------------
{
  const modelSandbox = join(ROOT, 'build', 'fixtures', 'registration-model-sandbox');
  const motionSandbox = join(ROOT, 'build', 'fixtures', 'registration-motion-sandbox');
  rmSync(modelSandbox, { recursive: true, force: true });
  rmSync(motionSandbox, { recursive: true, force: true });
  mkdirSync(modelSandbox, { recursive: true });
  mkdirSync(motionSandbox, { recursive: true });
  writeFileSync(join(modelSandbox, 'body.vrm'), Buffer.from('VRM fake payload', 'utf8'));
  const waveBytes = vrmaFixture('registered');
  writeFileSync(join(motionSandbox, 'wave.vrma'), waveBytes);
  writeFileSync(join(motionSandbox, 'body.glb'), Buffer.alloc(16));

  // Drive the real `apply` and serve the route table it registered. The server
  // reads the live table, so registration and disposal are exercised for real.
  const { ctx, routes, provided, effects } = stubContext();
  plugin.apply(ctx, { modelDirs: [modelSandbox], motionDirs: [motionSandbox] });
  const service = provided.get('vrmpet3d');
  const server = await serveRoutes(routes);

  eq(routes.map(route => `${route.kind} ${route.path}`).sort().join(' | '),
    'exact /vrmpet3d/catalog | exact /vrmpet3d/config | exact /vrmpet3d/desktop | exact /vrmpet3d/game | exact /vrmpet3d/global'
      + ' | exact /vrmpet3d/llm'
      + ' | exact /vrmpet3d/model-info | exact /vrmpet3d/model-thumbnail | exact /vrmpet3d/models'
      + ' | exact /vrmpet3d/motions'
      + ' | exact /vrmpet3d/picker'
      + ' | exact /vrmpet3d/preview'
      + ' | exact /vrmpet3d/say'
      + ' | exact /vrmpet3d/settings'
      + ' | exact /vrmpet3d/setup | exact /vrmpet3d/setup-state'
      + ' | exact /vrmpet3d/state'
      + ' | exact /vrmpet3d/whale'
      + ' | exact /vrmpet3d/window'
      + ' | prefix /vrmpet3d/asset | prefix /vrmpet3d/motion | prefix /vrmpet3d/window/lib',
    'apply registers exactly the documented routes, FOUR pages now (模型参数, 通用设置, the first-run guide and the model picker) with the guide\'s own state, both windows, the thumbnail a picker shows, the whale mark and the AI pair included — and nothing for the application lifetime, which the menus no longer offer');
  // The window's source prefix must NOT end in a slash: the server matches a prefix with
  // `pathname === prefix || pathname.startsWith(prefix + '/')`, so a trailing slash there makes
  // every real request miss and 404s the whole page. Asserted as a property, not just as the
  // string above, because that is the failure this check exists for.
  ok(routes.every((route) => route.kind !== 'prefix' || !route.path.endsWith('/')),
    'no prefix route ends in a slash, which the matcher would never match');
  // The two motion paths are one letter apart, so this is the collision that
  // matters: the catalog must win `/vrmpet3d/motions` and the byte route
  // `/vrmpet3d/motion`, under the webserver's own matching rule.
  ok(matchRoute(routes, '/vrmpet3d/motions')?.path === '/vrmpet3d/motions',
    '/vrmpet3d/motions is matched by the catalog route');
  ok(matchRoute(routes, '/vrmpet3d/motion')?.path === '/vrmpet3d/motion',
    '/vrmpet3d/motion is matched by the byte route, not by the catalog');
  ok(matchRoute(routes, '/vrmpet3d/models')?.path === '/vrmpet3d/models',
    '/vrmpet3d/models is matched by its own route');

  /**
   * DSH's animated whale mark, over real HTTP.
   *
   * The status prompt masks the whale through this image, so "the tail is not animated" is a delivery
   * question before it is a styling one — and the two failure modes have to be told apart: a route that
   * answers 404 (the host resolved no mark at all) versus an image that arrives but is a STILL PNG (the
   * app's fallback would then never animate, silently). Both are asserted here, and the source is pinned to
   * `VRMPET3D_WHALE_FILE` above so the answer is this suite's fixture rather than whatever the machine has
   * pre-seeded. The rungs that decide WHICH source wins are group 13d's subject, not this block's.
   */
  {
    const whale = await server.call('/vrmpet3d/whale');
    eq(whale.status, 200, '/vrmpet3d/whale serves the mark the host resolved at activation');
    eq(whale.headers['content-type'], 'image/apng', 'as an APNG');
    const bytes = whale.body;
    eq(bytes.subarray(0, 8).toString('hex'), '89504e470d0a1a0a', 'whose bytes are a PNG');
    const text = bytes.toString('latin1');
    ok(text.includes('acTL') && text.includes('fcTL'),
      `and an ANIMATED one (${(text.match(/fcTL/g) || []).length} frames, not a still fallback)`);
    eq(bytes.length, readFileSync(WHALE_FIXTURE_FILE).length, 'byte for byte what VRMPET3D_WHALE_FILE names');
  }

  const modelCatalog = await server.json('/vrmpet3d/catalog');
  eq(modelCatalog.status, 200, '/vrmpet3d/catalog still answers');
  ok(Array.isArray(modelCatalog.payload?.models), 'the model catalog payload keeps its shape');
  eq(modelCatalog.payload.modelDirs.length, 1, 'the model catalog still reports its directories');
  ok(String(modelCatalog.payload.bundledDir).endsWith(join('assets', 'models')),
    'the model catalog still reports its bundled directory');

  const motionCatalog = await server.json('/vrmpet3d/motions');
  eq(motionCatalog.status, 200, '/vrmpet3d/motions answers');
  ok(Array.isArray(motionCatalog.payload?.motions),
    '/vrmpet3d/motions reaches the catalog, not the /vrmpet3d/motion byte route');
  // The payload carries the bundled pack AND the imported fixture. The route's own subject is the imported
  // directory, so it is asserted on its own and the bundled half is asserted just below.
  const listed = userMotions(motionCatalog.payload.motions).map(motion => motion.name).sort();
  eq(listed.join(','), 'wave.vrma', `the motion catalog lists the fixture (got: ${listed.join(', ')})`);
  eq(motionCatalog.payload.motionDirs.length, 1, 'the motion catalog reports its directories');
  eq(motionCatalog.payload.motionDirs[0], resolve(motionSandbox), 'the motion directory is resolved');
  eq(motionCatalog.headers['access-control-allow-origin'], '*', 'the motion catalog is readable by the page');
  // The parallel of the model catalogue's `bundledDir`: the pack rides along with every motion catalog.
  ok(String(motionCatalog.payload.bundledDir).endsWith(join('assets', 'motions')),
    'the motion catalog reports the bundled motion directory');
  ok(motionCatalog.payload.motions.some(motion => motion.source === 'bundled'),
    'and the shipped pack is listed out of the box, without the user importing anything');
  /**
   * THE PACK'S SPRING VALUES ride along with it (operator, 2026-10-14: 「把当前 BlueFatFish 弹簧骨的参数作为默认参数推上去」).
   *
   * Keyed by the LIVE model id, because the manifest itself is keyed by file name and an id is positional: the host owns
   * the catalog that turns one into the other, so it does the resolution and the client only indexes by the id it has.
   * The shipped model is in this fixture's catalog, so the entry is asserted by BOTH halves — the id, and the chain map
   * behind it.
   */
  const defaults = motionCatalog.payload.springDefaults;
  ok(defaults && typeof defaults === 'object', 'the motion catalog carries the pack\'s spring values');
  const fatFish = modelCatalog.payload.models.find(model => model.name === 'BlueFatFish.vrm.br');
  ok(Boolean(fatFish), 'the fixture catalog lists the shipped model the defaults are written for');
  if (fatFish) {
    const chains = defaults[fatFish.id];
    ok(chains && typeof chains === 'object',
      `and its spring values are keyed by its LIVE model id (${fatFish.id}; payload keys: ${Object.keys(defaults).join(', ') || '(none)'})`);
    ok(Boolean(chains && chains.DaiMao), 'with a chain the model file actually declares');
    eq(chains && chains.DaiMao && chains.DaiMao.stiffness, 0.4,
      'and the number the operator tuned for it (0.4 on the ahoge), not the file\'s own value');
    /**
     * …and the block covers EVERY chain of the model, including ones the profile no longer overrides: a chain that
     * vanished from the snapshot would silently fall back to the model FILE's value on the next profile, which is a
     * different number than the one their pet is using (measured 2026-10-14: 复位ing 尾巴 dropped `WeiBa` from the block).
     */
    ok(Boolean(chains && chains.WeiBa && chains['WeiBa.L'] && chains['WeiBa.R']),
      'and it names the model\'s own chains, including one the profile no longer overrides (尾巴)');
  }

  // The two catalogs are disjoint at the payload level and at the route level. The bundled model is a MODEL and
  // must never appear among the motions; the fixture directory here holds one model and one motion.
  const modelNames = modelCatalog.payload.models.filter(model => model.source !== 'bundled')
    .map(model => model.name).sort();
  eq(modelNames.join(','), 'body.vrm',
    `the model catalog lists its own directory only, never the motion one (got: ${modelNames.join(', ')})`);
  const modelId = modelCatalog.payload.models[0].id;
  const motionId = userMotions(motionCatalog.payload.motions)[0].id;
  ok(!motionCatalog.payload.motions.some(motion => motion.id === modelId),
    'no model id appears in the motion catalog');
  ok(!modelCatalog.payload.models.some(model => model.id === motionId),
    'no motion id appears in the model catalog');

  let response = await server.call(`/vrmpet3d/motion?m=${encodeURIComponent(motionId)}`);
  eq(response.status, 200, 'the registered motion route streams the file');
  ok(response.body.equals(waveBytes), 'the registered motion route streams the exact bytes');
  response = await server.call(`/vrmpet3d/motion?m=${encodeURIComponent(modelId)}`);
  eq(response.status, 404, 'a model id is not a motion id');
  response = await server.call(`/vrmpet3d/asset?m=${encodeURIComponent(motionId)}`);
  eq(response.status, 404, 'a motion id is not a model id');
  response = await server.call(`/vrmpet3d/asset?m=${encodeURIComponent(modelId)}`);
  eq(response.status, 200, 'the asset route is unchanged for a real model id');

  // The user-visible half of the id-stability rule: the settings panel refetches the
  // catalog, and the catalog handler rebuilds the store on every request, so an id
  // read before a rebuild must still stream its file afterwards. Measured broken live:
  // the same file was `m1` and then `m3`, and a page that kept the first id was told
  // "unknown model id" 鈥?which reads as a broken model file.
  const refreshed = await server.json('/vrmpet3d/catalog');
  eq(refreshed.payload.models[0].id, modelId, 'a model id is unchanged by reading the catalog again');
  response = await server.call(`/vrmpet3d/asset?m=${encodeURIComponent(modelId)}`);
  eq(response.status, 200, 'the id captured before a rebuild still streams its model');

  // describe() and the frozen route map the Loader reads.
  // The fixture directory contributes one clip and the bundled pack contributes however many it holds, which is
  // the operator's own library — so the count is compared against what the route just LISTED, not a number.
  const packSize = motionCatalog.payload.motions.filter(motion => motion.source === 'bundled').length;
  eq(service.describe().motionCount, packSize + 1,
    `describe() counts the motions (the fixture plus the ${packSize}-clip bundled pack)`);
  // +2 for the two bundled models, which are in every catalog — SampleModel.vrm since 2026-10-10 and
  // BlueFatFish.vrm since 2026-10-13.
  eq(service.describe().modelCount, 3, 'describe() still counts the models (the fixture plus the two built-in ones)');
  eq(service.assetRoutes.motions, '/vrmpet3d/motions', 'assetRoutes names the motion catalog route');
  eq(service.assetRoutes.motion, '/vrmpet3d/motion', 'assetRoutes names the motion byte route');
  eq(service.assetRoutes.catalog, '/vrmpet3d/catalog', 'the existing catalog path is unchanged');
  eq(service.assetRoutes.asset, '/vrmpet3d/asset', 'the existing asset path is unchanged');
  ok(Object.isFrozen(service.assetRoutes), 'assetRoutes is frozen');

  /**
   * ---- the preview channel, over real HTTP ---------------------------------
   *
   * The settings window posts what the model should be showing while a clip's expression and mouth are being
   * chosen, and both pet surfaces poll it (operator's request, 2026-10-09). Three properties have to hold, and
   * each is a way the feature would be silently broken: a cleared preview is distinguishable from an absent
   * one (the `seq` counter, which is the whole reason it exists), nothing about it is persisted, and the value
   * that comes back is the CLEANED one rather than whatever a page posted.
   */
  const readPreview = async () => {
    const response = await server.call('/vrmpet3d/preview');
    return { status: response.status, payload: JSON.parse(response.body.toString('utf8')) };
  };
  const postPreview = async (body) => {
    const response = await server.call('/vrmpet3d/preview', 'POST', JSON.stringify(body));
    return { status: response.status, payload: JSON.parse(response.body.toString('utf8')) };
  };
  let preview = await readPreview();
  eq(preview.payload.preview, null, 'the preview starts empty');
  const seqBefore = preview.payload.seq;
  preview = await postPreview({ preview: { state: 'resting', motionId: 'a1', expression: 'Joy', mouth: 'A' } });
  eq(JSON.stringify(preview.payload.preview), JSON.stringify({ state: 'resting', motionId: 'a1', expression: 'Joy', mouth: 'A' }),
    'and holds what a surface posted');
  ok(preview.payload.seq > seqBefore, 'with a counter that moved, so a poller sees the change');
  const seqAfterSet = preview.payload.seq;
  preview = await postPreview({ preview: { state: 'held', motionId: '' } });
  eq(preview.payload.preview, null, 'an instruction with nothing in it CLEARS the preview');
  ok(preview.payload.seq > seqAfterSet,
    'and clearing moves the counter too — otherwise a cleared preview would be indistinguishable from an old one');
  const storedAfterPreview = await server.json('/vrmpet3d/settings');
  eq(JSON.stringify(storedAfterPreview.payload.preferences.motionClips), '{}',
    'and none of it was persisted: a preview is not a preference');

  /**
   * ---- the state channel, over real HTTP -----------------------------------
   *
   * The in-app pet resolves the session state and the floating window cannot, so the app posts it here and the
   * window polls it. Same shape as the preview channel (`seq` plus a value) and for the same reason: the pet
   * returns to `resting` between turns, so a poller comparing VALUES would miss every second entry into
   * `working` — which is the whole prompt.
   */
  const readState = async () => {
    const response = await server.call('/vrmpet3d/state');
    return { status: response.status, payload: JSON.parse(response.body.toString('utf8')) };
  };
  const postState = async (body) => {
    const response = await server.call('/vrmpet3d/state', 'POST', JSON.stringify(body));
    return { status: response.status, payload: JSON.parse(response.body.toString('utf8')) };
  };
  let petState = await readState();
  eq(petState.status, 200, 'the state route answers');
  eq(petState.payload.state, null, 'and starts with no state, because nothing has reported one yet');
  const stateSeqBefore = petState.payload.seq;
  petState = await postState({ state: 'working' });
  eq(petState.payload.state, 'working', 'the in-app pet reports what it resolved');
  ok(petState.payload.seq > stateSeqBefore, 'and the counter moves, so a poller notices');
  // The repeat is the case the counter exists for: same value, still a new event.
  const stateSeqWorking = petState.payload.seq;
  petState = await postState({ state: 'resting' });
  petState = await postState({ state: 'working' });
  ok(petState.payload.seq > stateSeqWorking + 1,
    'a state entered twice still moves the counter: the value is repeatable, the event is not');
  petState = await postState({ state: 'not-a-state' });
  eq(petState.payload.state, null, 'an unknown state is refused rather than stored');
  /**
   * The 碎碎念 line travels in the SAME body.
   *
   * This is the floating window's only source for it — the page has no session of its own to react to — and
   * the boundary sanitises it rather than trusting the client: one line, capped. A multi-line string would
   * grow the window past the pet, which is exactly what the bubble's rectangle exists to avoid.
   */
  petState = await postState({ state: 'working', line: '开始干活了' });
  eq(petState.payload.line, '开始干活了', 'the pet can publish a 碎碎念 line with its state');
  petState = await readState();
  eq(petState.payload.line, '开始干活了', 'and the window reads it back on the next poll');
  petState = await postState({ state: 'working' });
  eq(petState.payload.line, null,
    'a report with NO line clears it, so a bubble cannot outlive the remark it belongs to');
  petState = await postState({ state: 'working', line: 'first\nsecond\ttabbed' });
  eq(petState.payload.line, 'first second tabbed', 'a multi-line report is flattened to one line');
  petState = await postState({ state: 'working', line: 'x'.repeat(400) });
  eq(petState.payload.line.length <= 80, true,
    `and a long one is capped (${petState.payload.line.length} chars), because the window is sized from it`);
  petState = await postState({ state: 'working', line: 42 });
  eq(petState.payload.line, null, 'and a non-string is refused rather than rendered');
  /**
   * The WHY block: the machine's INPUTS, relayed so "it keeps saying 深度求索中 with nothing running" is answerable from
   * one request instead of a guess (operator, 2026-10-14). It crosses a page boundary, so this asserts both halves that
   * matter: the fields a diagnostic needs survive, and everything else is rewritten rather than trusted.
   */
  petState = await postState({
    state: 'working',
    why: {
      running: true, working: 2, waiting: 0, unread: 1, pending: false, available: true,
      scope: 'global', session: 'sess-1', runningIds: ['sess-1', 'sess-2'],
      notice: { reason: 'completed', at: 1700000000000, sessionId: 'sess-2' },
      held: null, settling: { reason: 'completed', at: 1700000000001, sessionId: 'sess-1' },
      interaction: null, focused: true,
      turn: { open: false, startedAt: 1699999999000, endedAt: 1700000000000 },
      dismissed: {
        kind: 'expired', at: 1700000000002, sessionId: 'sess-2', reason: 'completed',
        focused: false, presentId: null, running: false,
      },
      catalogKeys: ['byId:object', 'ids:array', 'phase:string'],
      /**
       * The unread breakdown, added with the 绿点 fix of 2026-10-14: four helper sessions DSH marked `completionUnread`
       * that are in the record table but NOT in the app's own list — the shape that says why the dot is (not) lit,
       * without a session id or a title in it.
       */
      unreadDetail: { candidates: 4, counted: 0, inIds: 0, inById: 4, subagent: 0, blank: 0, withCwd: 4, running: 1 },
    },
  });
  petState = await readState();
  eq(petState.payload.why && petState.payload.why.running, true, 'the why block says whether work is running');
  eq(petState.payload.why.working, 2, 'how many sessions were counted');
  eq(JSON.stringify(petState.payload.why.runningIds), JSON.stringify(['sess-1', 'sess-2']),
    'and WHICH ones, which is the difference between a stale status entry and a real turn');
  eq(petState.payload.why.notice && petState.payload.why.notice.sessionId, 'sess-2',
    'the completion on screen is named');
  eq(petState.payload.why.settling && petState.payload.why.settling.sessionId, 'sess-1',
    'and so is the one still waiting out its settle window');
  eq(petState.payload.why.focused, true, 'and whether this surface believes DSH has the user\'s attention');
  eq(petState.payload.why.dismissed && petState.payload.why.dismissed.kind, 'expired',
    'and WHICH rule ended the last notice — the field the 任务达成-disappears report needed');
  eq(petState.payload.why.dismissed.focused, false, 'with the focus value that rule read');
  eq(petState.payload.why.dismissed.presentId, null, 'and the session it compared against (null: there was none)');
  eq(JSON.stringify(petState.payload.why.catalogKeys), JSON.stringify(['byId:object', 'ids:array', 'phase:string']),
    'and the SHAPE of the session snapshot, so a field this plugin cannot read can be named');
  eq(JSON.stringify(petState.payload.why.unreadDetail),
    JSON.stringify({ candidates: 4, counted: 0, inIds: 0, inById: 4, subagent: 0, blank: 0, withCwd: 4, running: 1 }),
    'and WHY the green dot is or is not lit, as counts: candidates, counted, and which half of the catalog held them');  petState = await readState();
  eq(petState.payload.why && petState.payload.why.working, 2, 'the window (and a debugger) reads it back on the next poll');
  petState = await postState({ state: 'working', why: { running: 'yes', working: 'lots', evil: '<script>' } });
  petState = await readState();
  eq(petState.payload.why, null,
    'and a why block with nothing usable in it is dropped rather than stored as junk');
  petState = await postState({ state: 'working', why: null });
  petState = await readState();
  eq(petState.payload.why, null, 'while a report with no why at all clears it');
  /**
   * The PRESS travels the same way — which part of the model it landed on.
   *
   * Relayed for the same reason the line is: the answer lives only in the page that measured it, and "I clicked
   * its eye and nothing happened" cannot be answered from outside without it. Sanitised at this boundary like
   * everything else a page sends: strings only, each capped, and a body with neither a reason nor a region is
   * not a press at all.
   */
  petState = await postState({ state: 'working', touch: { reason: 'click', region: 'eye', bone: 'leftEye', at: 1234 } });
  eq(petState.payload.touch && petState.payload.touch.region, 'eye', 'a press reports which part it landed on');
  eq(petState.payload.touch.bone, 'leftEye', 'with the model\'s own name for that part, for diagnosis');
  petState = await readState();
  eq(petState.payload.touch.region, 'eye', 'and the window reads it back on the next poll');
  /**
   * And WHICH of the user's own parts owns that structure — the label included.
   *
   * `region` is the default classification and `part` is the row the user built, so a user whose ear is their own
   * part sees `part: 'ear'` beside `region: 'head'`: without both, "I clicked its ear and nothing happened" cannot
   * be told apart from "the raycast landed on the head".
   */
  petState = await postState({
    state: 'working',
    touch: { reason: 'hold', part: 'ear', label: '耳朵', region: 'head', bone: 'ErDuo.L.002' },
  });
  eq(petState.payload.touch.part, 'ear', 'and which of the user\'s parts owns it');
  eq(petState.payload.touch.label, '耳朵',
    'with the label the settings list shows, because that is the word a person knows');
  eq(petState.payload.touch.bone, 'ErDuo.L.002', 'and the model\'s own structure name, which explains a surprise');
  petState = await postState({ state: 'working', touch: { reason: 'hold', region: 'head', bone: '頭'.repeat(80) } });
  eq(petState.payload.touch.region, 'head', 'a 长按 is a press too, with its own reason');
  eq(petState.payload.touch.bone.length <= 64, true,
    `and a long bone name is capped (${petState.payload.touch.bone.length}), because this is a readout`);
  petState = await postState({ state: 'working', touch: { bone: 'leftEye' } });
  eq(petState.payload.touch, null, 'while a touch with neither reason nor region is not a press');
  petState = await postState({ state: 'working', touch: 'nonsense' });
  eq(petState.payload.touch, null, 'and a non-object is refused rather than rendered');
  petState = await postState({ state: 'working' });
  eq(petState.payload.touch, null, 'a report with no touch clears it, like the line');
  const storedAfterState = await server.json('/vrmpet3d/settings');
  eq(JSON.stringify(storedAfterState.payload.preferences.status), '{}',
    'and the state channel persisted nothing either: it is live telemetry, not a preference');
  /**
   * The unread breakdown is sanitised like every other field, and this sits LAST in the section on purpose: it changes
   * what the route holds, and every assertion above it reads that route.
   */
  await postState({
    state: 'working',
    why: { running: true, unreadDetail: { candidates: 'lots', counted: -3, inIds: null, inById: 2.7, junk: 'x' } },
  });
  const junkDetail = await readState();
  eq(JSON.stringify(junkDetail.payload.why && junkDetail.payload.why.unreadDetail),
    JSON.stringify({ inById: 2 }),
    `while a nonsense breakdown is filtered down to the counts that are real (got ${JSON.stringify(junkDetail.payload.why)})`);

  // Rejected reporters must not overwrite working with idle before their ownership check.
  await postState({ state: 'working', line: 'live work', unread: 3,
    clock: { startedAt: Date.now() }, touch: { reason: 'click', region: 'head' },
    why: { page: 'surface-test', seq: 2, instance: 'new', running: true } });
  const liveOwner = (await readState()).payload;
  const rejectedViews = [];
  for (const oldWhy of [{ page: 'surface-test', seq: 1, instance: 'old' }, null]) {
    const rejected = await postState({ state: 'resting', line: 'stale idle', unread: 0, why: oldWhy });
    const held = (await readState()).payload;
    rejectedViews.push({ rejected: rejected.payload.superseded === true,
      unchanged: JSON.stringify(held) === JSON.stringify(liveOwner) });
  }
  eq(JSON.stringify(rejectedViews), JSON.stringify([
    { rejected: true, unchanged: true }, { rejected: true, unchanged: true },
  ]), 'older and unidentified reporters cannot mutate any field of the current working report');

  // ---- the desktop window's routes, over real HTTP -------------------------
  //
  // These requests are the ones that would have caught the bug this section exists for: the
  // source prefix was registered WITH a trailing slash, the server matches a prefix as
  // `pathname === prefix || pathname.startsWith(prefix + '/')`, and so every source 404'd. The
  // window opened, the page loaded, the glue never ran, and the pet was invisible 鈥?while the
  // suite stayed green, because it inlines the glue and serves the sources itself.
  const page = await server.call('/vrmpet3d/window');
  eq(page.status, 200, "the window's page is served");
  eq(page.headers['content-type'], 'text/html; charset=utf-8', 'the page is served as HTML');
  ok(page.body.toString('utf8').includes('/vrmpet3d/window/lib/desktop-page.js'),
    'the page asks for its sources from the plugin itself');

  /**
   * The sources the window's page is allowed to fetch.
   *
   * `placeholder.js` was in this list until 2026-10-10, when the operator removed the built-in avatar ("内置的
   * 占位模型还是没删掉，把Sample Model设为内置模型"). It is now asserted to be REFUSED rather than served: the file
   * stays in the tree as the fixture the geometry suites inline directly, and the host must not hand it to a
   * page that has no use for it — a whitelist is only worth having if it also says no.
   */
  const sources = ['client.vendor.js', 'core.js', 'scene.js', 'client.js', 'desktop-page.js'];
  for (const name of sources) {
    const source = await server.call(`/vrmpet3d/window/lib/${name}`);
    eq(source.status, 200, `the page's source ${name} is served`);
    eq(source.headers['content-type'], 'text/javascript; charset=utf-8', `${name} is served as JavaScript`);
    ok(source.body.length > 0, `${name} is not empty`);
  }
  const removedSource = await server.call('/vrmpet3d/window/lib/placeholder.js');
  eq(removedSource.status, 404, 'and the built-in avatar is no longer served to any page');
  const glue = await server.call('/vrmpet3d/window/lib/desktop-page.js');
  ok(glue.body.toString('utf8').includes('__VRMPET3D_DESKTOP__'),
    'the glue served to the window publishes the global the page mounts');

  /**
   * What each whitelisted name is served AS — the check that was MISSING when the two settings windows
   * became a wall of unstyled text (operator, 2026-10-10: "插件面板设置窗口完全变成了无格式文本的堆积").
   *
   * The route hard-coded `text/javascript` for every name in the whitelist, `pages.css` included, and a
   * browser refuses to apply a stylesheet whose response is not CSS: the pages loaded, their scripts ran,
   * and every rule in `lib/pages.css` was dropped before it reached the document. Nothing above this line
   * can see that — a 200 with 16 KB of bytes is a 200 with 16 KB of bytes — and the desktop suite could not
   * either, because its page server answers `pages.css` itself with `text/css` (see its line ~1038). The
   * one request that mattered was the one no harness made, so the real handler is asked here.
   *
   * The whitelist and the type table are the plugin's OWN exported constants rather than a copy written out
   * again here: a copy is how a list and the thing it checks drift apart, and a name added to the real set is
   * covered by this loop on the run that adds it.
   */
  const sourceNames = [...plugin.WINDOW_SOURCES];
  const sourceTypes = plugin.WINDOW_SOURCE_TYPES;
  /**
   * The default for an extension with no entry, and the only two extensions in the whitelist: JavaScript
   * for `.js` (the route's original, correct behaviour) and CSS for `.css` (the fix, and the one a
   * stylesheet needs). A name of neither extension would be a new class of page source, and this says so
   * rather than guessing a type for it.
   */
  const expectedType = name => sourceTypes[extname(name).toLowerCase()]
    ?? (name.endsWith('.js') ? 'text/javascript; charset=utf-8' : null);
  ok(sourceNames.length === 14 && sourceNames.includes('pages.css') && sourceNames.includes('config-page.js')
    && sourceNames.includes('setup-page.js') && sourceNames.includes('model-picker.js')
    && sourceNames.includes('picker-page.js'),
    'the whitelist being checked is the route\'s own (fourteen names including the independent mini-game sources)');
  for (const name of sourceNames) {
    const source = await server.call(`/vrmpet3d/window/lib/${name}`);
    eq(source.headers['content-type'], expectedType(name),
      `the page source ${name} is served with the type a browser will accept for it`);
  }
  eq(sourceTypes['.css'], 'text/css; charset=utf-8', 'and the stylesheet type is CSS, not the route\'s default');

  /**
   * The FOURTH page, and the component it shares with the guide (added 2026-10-13).
   *
   * 切换模型 is a page of its own rather than a panel inside the pet, and the operator asked for its content to
   * BE the guide's 偏好模型 step (「面板中和初次安装向导模型页完全一样」). Both facts are asserted here: the route
   * serves a page, and that page plus the guide both load the ONE component instead of each carrying a grid.
   * The guide's typed-path box is asserted GONE for the same reason it was removed — a window the launcher
   * opened has a native dialog, and everywhere else the same drop target takes the file's bytes.
   */
  const pickerPage = await server.call('/vrmpet3d/picker');
  eq(pickerPage.status, 200, 'the model picker has a page of its own');
  const pickerHtml = pickerPage.body.toString('utf8');
  ok(pickerHtml.includes('/vrmpet3d/window/lib/model-picker.js') && pickerHtml.includes('/vrmpet3d/window/lib/picker-page.js'),
    'which loads the shared picker component and its own thin script');
  ok(pickerHtml.includes('id="picker-mount"'), 'and gives the component a mount point');
  const setupHtml = readFileSync(join(ROOT, 'lib', 'setup-page.html'), 'utf8');
  ok(setupHtml.includes('id="setup-model-picker"') && setupHtml.includes('/vrmpet3d/window/lib/model-picker.js'),
    "and the guide's 偏好模型 step mounts the SAME component");
  ok(!/id="setup-model-(pick|manual|manual-row|path|add|list|note|count)"/.test(setupHtml),
    'with the old 选择模型文件 button and 手动输入路径 box gone, since the component owns both ways in');

  response = await server.call('/vrmpet3d/window/lib/secrets.env');
  eq(response.status, 404, 'a name outside the whitelist is refused');
  response = await server.call('/vrmpet3d/window/lib/..%2f..%2f..%2fpackage.json');
  eq(response.status, 404, 'a traversal attempt in the source name is refused');
  response = await server.call('/vrmpet3d/window/other.js');
  eq(response.status, 404, 'the page route does not open the rest of the directory');

  const desktopStatus = await server.json('/vrmpet3d/desktop');
  eq(desktopStatus.status, 200, 'the window control route reports its status');
  eq(desktopStatus.payload.state, 'stopped', 'and nothing is running under test');
  eq(desktopStatus.payload.routes.window, '/vrmpet3d/window', 'and it names the page route');
  const badAction = await server.call('/vrmpet3d/desktop', 'POST', JSON.stringify({ action: 'launch-a-window-please' }));
  eq(badAction.status, 400, 'an unknown action is refused rather than guessed at');
  const refusedDisable = await server.call('/vrmpet3d/desktop', 'POST', JSON.stringify({ action: 'disable' }));
  eq(refusedDisable.status, 200, 'disabling a window that is not running is accepted');
  eq(JSON.parse(refusedDisable.body.toString('utf8')).running, false, 'and reports it as stopped');

  // Disposal: an unload takes every route with it, the new ones included.
  for (const dispose of effects) dispose();
  eq(routes.length, 0, 'unloading removes every registered route');
  response = await server.call(`/vrmpet3d/motion?m=${encodeURIComponent(motionId)}`);
  eq(response.status, 404, 'the motion route is gone after unload');

  await server.close();
  rmSync(modelSandbox, { recursive: true, force: true });
  rmSync(motionSandbox, { recursive: true, force: true });
}

// ---------------------------------------------------------------------------
group('9. boundary hub');
// ---------------------------------------------------------------------------
{
  const agents = {
    list: () => [{ id: 'a' }, { id: 'b' }],
    get: (id) => ({ id }),
    roots: () => [{ id: 'a' }],
  };
  const hub = new plugin.VrmPet3DBoundaryHub({ agents, epoch: 'epoch-1' });
  const controller = new AbortController();
  const iterator = hub.watch(controller.signal);

  const baseline = await iterator.next();
  eq(baseline.done, false, 'the stream opens with a frame');
  eq(baseline.value.type, 'baseline', 'the opening frame is a baseline');
  eq(baseline.value.hostEpoch, 'epoch-1', 'the baseline carries the host epoch');
  eq(baseline.value.identities.length, 2, 'the baseline lists every agent');

  const subagent = baseline.value.identities.find(identity => identity.sessionId === 'b');
  eq(subagent.isSubagent, true, 'a non-root agent is classified as a subagent');
  const root = baseline.value.identities.find(identity => identity.sessionId === 'a');
  eq(root.isSubagent, false, 'a root agent is not a subagent');

  // Only turn boundaries are forwarded.
  hub.accept({ id: 'a' }, { type: 'message/delta', seq: 1, time: 1 });
  hub.accept({ id: 'a' }, { type: 'turn/start', seq: 2, time: 2 });
  const started = await iterator.next();
  eq(started.value.type, 'turn/start', 'a turn start is forwarded');
  eq(started.value.sessionId, 'a', 'the boundary names its session');
  eq(started.value.streamSeq, 1, 'the first forwarded frame has stream sequence 1');

  hub.accept({ id: 'a' }, { type: 'turn/end', seq: 3, time: 3, data: { reason: { kind: 'completed' } } });
  const ended = await iterator.next();
  eq(ended.value.type, 'turn/end', 'a turn end is forwarded');
  eq(ended.value.reason, 'completed', 'the completion reason is carried');

  // Replayed and out-of-order boundaries are dropped.
  hub.accept({ id: 'a' }, { type: 'turn/start', seq: 2, time: 2 });
  hub.accept({ id: 'a' }, { type: 'turn/start', seq: 1, time: 1 });
  hub.accept({ id: 'a' }, { type: 'turn/start', seq: 4, time: 4 });
  const next = await iterator.next();
  eq(next.value.seq, 4, 'only the newest boundary is delivered');

  // A malformed event must not throw or reach the client.
  hub.accept({ id: 'a' }, { type: 'turn/start', seq: 'x' });
  hub.accept({ id: '' }, { type: 'turn/start', seq: 99 });
  hub.accept(null, { type: 'turn/start', seq: 98 });
  hub.accept({ id: 'a' }, null);
  ok(true, 'malformed events are ignored');

  // Aborting closes the stream.
  controller.abort();
  const done = await iterator.next();
  eq(done.done, true, 'aborting the signal ends the stream');

  hub.dispose();
  const afterDispose = hub.watch(new AbortController().signal);
  const disposedFrame = await afterDispose.next();
  eq(disposedFrame.done, true, 'a disposed hub hands out a closed stream');
}

// ---------------------------------------------------------------------------
group('10. imported model directories over HTTP');
// ---------------------------------------------------------------------------
{
  // The scratch list is redirected once, at the top of this file, so that no group
  // can read or write the user's own import list. See `IMPORTED_DIRS_FILE` there.
  const scratch = IMPORTED_DIRS_FILE;
  const baseSandbox = join(ROOT, 'build', 'fixtures', 'import-base-sandbox');
  const importSandbox = join(ROOT, 'build', 'fixtures', 'import-guest-sandbox');
  const notADirectory = join(ROOT, 'build', 'fixtures', 'import-not-a-dir.txt');
  const missing = join(ROOT, 'build', 'fixtures', 'import-missing-' + randomUUID());
  rmSync(scratch, { force: true });
  rmSync(baseSandbox, { recursive: true, force: true });
  rmSync(importSandbox, { recursive: true, force: true });
  rmSync(notADirectory, { force: true });
  mkdirSync(baseSandbox, { recursive: true });
  mkdirSync(importSandbox, { recursive: true });
  writeFileSync(join(baseSandbox, 'body.vrm'), Buffer.from('VRM fake payload', 'utf8'));
  writeFileSync(join(importSandbox, 'guest.vrm'), Buffer.alloc(24));
  writeFileSync(notADirectory, 'this is a file, not a directory');

  const { ctx, routes, provided, effects } = stubContext();
  plugin.apply(ctx, { modelDirs: [baseSandbox] });
  const service = provided.get('vrmpet3d');
  const server = await serveRoutes(routes);

  /** A request that keeps the headers, because CORS is part of the contract. */
  async function request(path, init) {
    const response = await fetch(server.base + path, init);
    const text = Buffer.from(await response.arrayBuffer()).toString('utf8');
    let payload = null;
    try { payload = JSON.parse(text); } catch { payload = null; }
    const headers = {};
    response.headers.forEach((value, key) => { headers[key] = value; });
    return { status: response.status, headers, payload, text };
  }
  const list = () => request('/vrmpet3d/models');
  const post = (body) => request('/vrmpet3d/models', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: typeof body === 'string' ? body : JSON.stringify(body),
  });

  // The route exists and describes the state the panel has to draw.
  let state = await list();
  eq(state.status, 200, 'GET /vrmpet3d/models answers');
  eq(state.headers['content-type'], 'application/json; charset=utf-8', 'the list is JSON');
  eq(state.headers['access-control-allow-origin'], '*', 'the list is readable by the page');
  eq(state.payload.importedDirs.length, 0, 'a first run has no imported directories');
  eq(state.payload.modelCount, 3, 'the count covers the configured directory and the two built-in models');
  eq(state.payload.catalogFile, resolve(scratch), 'the route names the file it persists to');
  /**
   * The READ side carries the catalogue, not only the imported lists.
   *
   * This pins a defect the operator found on 2026-10-13 (「现有模型没有显示自带的内置模型」): the model picker draws its
   * grid from ONE request to this route, and the GET reply omitted `models`, so the grid came up empty on a fresh
   * profile while `/vrmpet3d/catalog` listed the built-in model. The browser probe's stub happened to include the
   * field, which is exactly why the real reply is pinned HERE — and pinned to the same shape the POST side answers
   * with, because the picker adopts that reply after an import.
   */
  ok(Array.isArray(state.payload.models) && state.payload.models.some(model => model.source === 'bundled'),
    'and the READ side carries the catalogue, built-in model included, so a picker draws its grid from one request');
  eq(state.payload.models.length, state.payload.modelCount, 'with that list and the count agreeing');

  // Adding a directory is live immediately: the reply carries the rebuilt catalog,
  // so the panel does not have to race a second request against the rebuild.
  let added = await post({ add: importSandbox });
  eq(added.status, 200, 'POST add imports a directory');
  eq(added.payload.persisted, true, 'the import is persisted, not only held in memory');
  eq(added.payload.persistError, null, 'a successful write reports no error');
  eq(added.payload.importedDirs.length, 1, 'the reply carries the refreshed list');
  eq(added.payload.importedDirs[0], resolve(importSandbox), 'the directory is stored resolved');
  eq(added.payload.modelCount, 4, 'the reply carries the refreshed catalog count (two fixtures plus the two built-in)');
  ok(added.payload.models.some(model => model.name === 'guest.vrm'),
    'the imported model is in the reply catalog');

  // ...and the state is real, not just reported: a separate read agrees.
  const afterAdd = await server.json('/vrmpet3d/catalog');
  ok(afterAdd.payload.models.some(model => model.name === 'guest.vrm'),
    'the next catalog read includes the imported model');
  ok(afterAdd.payload.importedDirs.includes(resolve(importSandbox)),
    'the catalog reports the imported directory');

  // Persistence is the point of the route: a restart must find the same list.
  const persisted = JSON.parse(readFileSync(scratch, 'utf8'));
  eq(persisted.modelDirs.length, 1, 'the list is written to the plugin-owned file');
  eq(persisted.modelDirs[0], resolve(importSandbox), 'the persisted entry is the resolved path');

  // Importing the same directory twice must not list its models twice.
  const again = await post({ add: importSandbox });
  eq(again.status, 200, 'importing the same directory again succeeds');
  eq(again.payload.importedDirs.length, 1, 'importing the same directory twice is a no-op');
  eq(again.payload.modelCount, 4, 'the catalog does not double-count the second import');

  // Refusals. Each names its own reason, and none of them touches the list.
  let refused = await post({ add: missing });
  eq(refused.status, 400, 'importing a directory that does not exist is refused');
  ok(/no such directory/.test(refused.payload?.error ?? ''), 'the refusal names the missing directory');
  refused = await post({ add: notADirectory });
  eq(refused.status, 400, 'importing a file rather than a directory is refused');
  ok(/not a directory/.test(refused.payload?.error ?? ''), 'the refusal says which check failed');
  refused = await post('{ not json');
  eq(refused.status, 400, 'a malformed body is refused');
  ok(/invalid JSON/.test(refused.payload?.error ?? ''), 'the refusal names the parse failure');
  refused = await post({});
  eq(refused.status, 400, 'a body with neither an import nor a removal is refused');
  ok(/expected \{addFile\}/.test(refused.payload?.error ?? ''),
    'the refusal states the accepted shape');
  refused = await request('/vrmpet3d/models', { method: 'PUT', body: '{}' });
  eq(refused.status, 405, 'an unsupported method is refused');
  const unchanged = await list();
  eq(unchanged.payload.importedDirs.length, 1, 'no refusal mutates the list');

  // A removal is as live as an addition, and equally persistent.
  const removed = await post({ remove: importSandbox });
  eq(removed.status, 200, 'POST remove drops a directory');
  eq(removed.payload.importedDirs.length, 0, 'the reply carries the list after the removal');
  eq(removed.payload.modelCount, 3,
    'the catalog drops the imported model, and keeps only the fixture and the two built-in ones');
  ok(!removed.payload.models.some(model => model.name === 'guest.vrm'),
    'the removed model is gone from the reply catalog');
  eq(JSON.parse(readFileSync(scratch, 'utf8')).modelDirs.length, 0, 'the removal is persisted');
  const removedAgain = await post({ remove: importSandbox });
  eq(removedAgain.status, 200, 'removing a directory that is not imported succeeds');
  eq(removedAgain.payload.importedDirs.length, 0, 'removing an absent directory is a no-op');

  // The service half of the same state, for a caller that never makes a request.
  ok(Array.isArray(service.importedModelDirs()), 'the service exposes the imported list');
  ok(service.importedModelDirs() !== service.importedModelDirs(),
    'the exposed list is a copy, not the live array');

  /**
   * AND THE FILE IMPORT: one model file COPIED into the plugin's own storage.
   *
   * Operator, 2026-10-12: 「允许用户选择VRM模型所在的文件，并导入到插件的本地配置中去，不再是选中一个文件夹了，万一文件夹
   * 移位了，也会出bug」. The copy IS the point, so the assertions are about the bytes: the path the user picked is
   * recorded only as provenance, the copy exists under `modelsDir`, the catalogue lists the copy, removing deletes
   * the copy (and never the original), and a file this plugin cannot load is refused by name.
   */
  const sourceModel = join(importSandbox, 'guest.vrm');
  const fileImport = await post({ addFile: sourceModel });
  eq(fileImport.status, 200, 'a model FILE is imported');
  const fileEntry = (fileImport.payload?.importedModels ?? [])[0];
  ok(Boolean(fileEntry && fileEntry.file), 'the reply carries the imported file');
  eq(fileImport.payload?.modelsDir, plugin.importedModelsDir(), "the reply names the plugin's own storage");
  ok(String(fileEntry?.file).startsWith(plugin.importedModelsDir()),
    `the model was COPIED into that storage (${fileEntry?.file})`);
  ok(existsSync(fileEntry?.file) && !String(fileEntry.file).startsWith(resolve(importSandbox)),
    'and the copy is a file of its own rather than the path the user picked');
  eq(fileEntry.source, resolve(sourceModel), 'with where it came from kept, for the list to show');
  ok(fileImport.payload.models.some(model => model.name === 'body.vrm'),
    'and the catalogue lists the copy, so the pet can load it');
  const againFile = await post({ addFile: sourceModel });
  eq(againFile.payload.importedModels.length, 1,
    'importing the same file twice records the copy once instead of a second copy');
  const badFile = await post({ addFile: join(ROOT, 'README.md') });
  eq(badFile.status, 400, 'a file that is not a model is refused');
  ok(/not a model/.test(badFile.payload?.error ?? ''), 'and the refusal says what it expected');
  const removedFile = await post({ removeFile: fileEntry.file });
  eq(removedFile.payload.importedModels.length, 0, 'removing the import clears the record');
  ok(!existsSync(fileEntry.file), 'and DELETES the copy');
  ok(existsSync(sourceModel), "while the user's own file is left exactly where it was");

  /**
   * AND THE UPLOAD: the same import, from BYTES.
   *
   * Operator, 2026-10-13: the guide's 偏好模型 step and the 切换模型 panel must both take a model the user DROPS
   * on them (「改成一个很大的选择模型文件或者拖入模型」). A dropped file is only ever a `File`, so the page uploads
   * it — and this is the branch that writes it. What is asserted is that it lands in the SAME store as a path
   * import (the file import above), with the same refusals, and that a malformed JSON body still takes the old
   * path rather than being swallowed by the new one.
   */
  const uploadBytes = Buffer.from('VRM uploaded payload, not a real avatar', 'utf8');
  const uploaded = await request('/vrmpet3d/models?file=dropped.vrm', {
    method: 'POST',
    headers: { 'content-type': 'application/octet-stream' },
    body: uploadBytes,
  });
  eq(uploaded.status, 200, 'a dropped model is imported from its bytes');
  const uploadEntry = (uploaded.payload?.importedModels ?? []).find(entry => entry.name === 'dropped.vrm');
  ok(Boolean(uploadEntry), 'the reply records the uploaded file');
  ok(String(uploadEntry?.file).startsWith(plugin.importedModelsDir()),
    `the bytes were written into the plugin's own storage (${uploadEntry?.file})`);
  ok(existsSync(uploadEntry.file) && readFileSync(uploadEntry.file).equals(uploadBytes),
    'and the copy is byte-for-byte what was uploaded');
  ok(uploaded.payload.models.some(model => model.id && model.name === 'dropped.vrm'),
    'the rebuilt catalogue lists it, so the picker can show it and switch to it');
  const uploadedAgain = await request('/vrmpet3d/models?file=dropped.vrm', {
    method: 'POST',
    headers: { 'content-type': 'application/octet-stream' },
    body: uploadBytes,
  });
  eq(uploadedAgain.payload.importedModels.filter(entry => entry.name === 'dropped.vrm').length, 1,
    'uploading the same bytes twice records the copy once instead of a second copy');
  const badUpload = await request('/vrmpet3d/models?file=notes.txt', {
    method: 'POST',
    headers: { 'content-type': 'application/octet-stream' },
    body: uploadBytes,
  });
  eq(badUpload.status, 400, 'an upload that is not a model is refused');
  ok(/not a model/.test(badUpload.payload?.error ?? ''), 'and that refusal says what it expected too');
  const emptyUpload = await request('/vrmpet3d/models?file=empty.vrm', {
    method: 'POST',
    headers: { 'content-type': 'application/octet-stream' },
    body: Buffer.alloc(0),
  });
  eq(emptyUpload.status, 400, 'an empty upload is refused');
  ok(/empty/.test(emptyUpload.payload?.error ?? ''), 'and names emptiness as the reason');
  // The JSON path is still the JSON path: a query-less POST with a JSON type is parsed as JSON, and a
  // JSON body that is not a shape this route knows is refused by the OLD message.
  const jsonStillJson = await post({});
  eq(jsonStillJson.status, 400, 'a JSON POST is still read as JSON even though an upload branch exists');
  ok(/expected \{addFile\}/.test(jsonStillJson.payload?.error ?? ''),
    'and it keeps the refusal that names the JSON shapes');
  ok(existsSync(uploadEntry.file), 'none of those refusals removed the uploaded copy');
  const removedUpload = await post({ removeFile: uploadEntry.file });
  eq(removedUpload.payload.importedModels.filter(entry => entry.name === 'dropped.vrm').length, 0,
    'removing it goes through the same FILE verb as a path import');
  ok(!existsSync(uploadEntry.file), 'and deletes the uploaded copy');

  // Disposal takes the route with it, like every other route.
  for (const dispose of effects) dispose();
  eq(routes.length, 0, 'unloading removes the models route too');
  await server.close();

  // The env override stays set for the rest of the run: it is the scratch path, not
  // a temporary patch, and leaving it in place is what keeps the last groups isolated.
  rmSync(scratch, { force: true });
  rmSync(baseSandbox, { recursive: true, force: true });
  rmSync(importSandbox, { recursive: true, force: true });
  rmSync(notADirectory, { force: true });
}

// ---------------------------------------------------------------------------
group('10b. imported motion directories over HTTP');
// ---------------------------------------------------------------------------
{
  // The same shape as group 10, for the OTHER list. Motions could previously only come from the plugin's
  // own `config.motionDirs`, so a `.vrma` needed a config edit plus a DSH restart to be usable at all; the
  // import list is what makes "put the file in a folder and pick it" work. Worth its own checks because the
  // two lists are scanned from different directories and served by different routes.
  const scratch = IMPORTED_MOTIONS_FILE;
  const baseMotions = join(ROOT, 'build', 'fixtures', 'motion-base-sandbox');
  const importMotions = join(ROOT, 'build', 'fixtures', 'motion-guest-sandbox');
  const notADirectory = join(ROOT, 'build', 'fixtures', 'motion-not-a-dir.txt');
  rmSync(scratch, { force: true });
  rmSync(baseMotions, { recursive: true, force: true });
  rmSync(importMotions, { recursive: true, force: true });
  rmSync(notADirectory, { force: true });
  mkdirSync(baseMotions, { recursive: true });
  mkdirSync(importMotions, { recursive: true });
  writeFileSync(join(baseMotions, 'base.vrma'), Buffer.from('glTF base', 'utf8'));
  // A real wave file: the catalog only needs the extension to list it, and the byte route hands the bytes
  // back unchanged, so this checks the plumbing rather than a parser.
  const waveBytes = readFileSync(join(ROOT, 'build', 'fixtures', 'vrma', 'vrmpet3d-wave.vrma'));
  writeFileSync(join(importMotions, 'vrmpet3d-wave.vrma'), waveBytes);
  // The guest directory declares its clip as a one-shot, so the flag has to survive the
  // whole route: read off disk, into the catalog, out over `/vrmpet3d/motions`, where the
  // page picks it up and hands it to the scene with the bytes.
  writeFileSync(join(importMotions, plugin.MOTION_MANIFEST_FILE),
    JSON.stringify({ clips: { 'vrmpet3d-wave.vrma': { loop: false } } }));
  writeFileSync(notADirectory, 'this is a file, not a directory');

  const { ctx, routes, effects } = stubContext();
  plugin.apply(ctx, { motionDirs: [baseMotions] });
  const server = await serveRoutes(routes);
  const request = async (path, method = 'GET', body) => {
    const response = await server.call(path, method, body);
    let payload = null;
    try { payload = JSON.parse(response.body.toString('utf8')); } catch { payload = null; }
    return { ...response, payload };
  };
  const get = () => request('/vrmpet3d/motions');
  const post = (body) => request('/vrmpet3d/motions', 'POST', JSON.stringify(body));

  const state = await get();
  eq(state.status, 200, 'GET /vrmpet3d/motions answers with the imported list');
  eq(state.payload.importedDirs.length, 0, 'a first run imports no motion directory');
  eq(state.payload.catalogFile, resolve(scratch), 'the route names the file it persists to');
  eq(userMotions(state.payload.motions).length, 1, 'the configured directory is scanned');
  eq(userMotions(state.payload.motions)[0].name, 'base.vrma', 'and lists the motion in it');

  // The import is live on the next read — no restart, which is the whole point of this list.
  const added = await post({ add: importMotions });
  eq(added.status, 200, 'POST add imports a motion directory');
  eq(added.payload.persisted, true, 'the import is persisted');
  eq(added.payload.importedDirs[0], resolve(importMotions), 'stored resolved');
  ok(added.payload.motions.some((motion) => motion.name === 'vrmpet3d-wave.vrma'),
    'the imported wave is in the reply catalog');
  const again = await get();
  ok(again.payload.motions.some((motion) => motion.name === 'vrmpet3d-wave.vrma'),
    'and in the next read too, so the import is live rather than reported');
  eq(userMotions(again.payload.motions).length, 2, 'both directories are scanned, and neither is duplicated');
  ok(again.payload.motionDirs.includes(resolve(baseMotions))
    && again.payload.motionDirs.includes(resolve(importMotions)),
  'the dirs in force are the configured ones plus the imported ones');

  // The byte route serves the imported file by the id the catalog minted: that is what the page fetches.
  const wave = again.payload.motions.find((motion) => motion.name === 'vrmpet3d-wave.vrma');
  const bytes = await server.call('/vrmpet3d/motion?m=' + encodeURIComponent(wave.id));
  eq(bytes.status, 200, 'the imported motion is served by its id');
  ok(Buffer.from(bytes.body).equals(waveBytes), 'and the bytes come back unchanged');
  eq(wave.loop, false, "the guest directory's manifest reaches the route: the wave is a one-shot");
  const baseEntry = again.payload.motions.find((motion) => motion.name === 'base.vrma');
  eq(baseEntry.loop, true, 'a directory without a manifest still reports every clip as a loop');

  const persisted = JSON.parse(readFileSync(scratch, 'utf8'));
  eq(persisted.motionDirs.length, 1, 'the list is written to the plugin-owned file');
  eq(persisted.motionDirs[0], resolve(importMotions), 'the persisted entry is the resolved path');

  // Refusals mirror the model route, and none of them mutates the list.
  const refusedMissing = await post({ add: join(ROOT, 'build', 'fixtures', 'nope-' + randomUUID()) });
  eq(refusedMissing.status, 400, 'a missing directory is refused');
  const refusedFile = await post({ add: notADirectory });
  eq(refusedFile.status, 400, 'a file rather than a directory is refused');
  const refusedBody = await post({});
  eq(refusedBody.status, 400, 'a body with neither add nor remove is refused');
  const refusedMethod = await request('/vrmpet3d/motions', 'PUT', '{}');
  eq(refusedMethod.status, 405, 'an unsupported method is refused');
  const unchanged = await get();
  eq(unchanged.payload.importedDirs.length, 1, 'no refusal mutates the list');

  const removed = await post({ remove: importMotions });
  eq(removed.status, 200, 'POST remove drops a motion directory');
  eq(removed.payload.importedDirs.length, 0, 'the reply carries the list after the removal');
  ok(!removed.payload.motions.some((motion) => motion.name === 'vrmpet3d-wave.vrma'),
    'and the catalog no longer lists its file');

  /**
   * AND THE FOLDER IMPORT THAT COPIES: 「选择文件夹并导入 VRMA 动作到插件的本地配置中」.
   *
   * The copy is what makes the import stable — from here the catalogue reads the plugin's own folder, not the one
   * the user picked — and EACH COPY IS ITS OWN ROOT, so the manifest that travelled with it still decides its
   * clips' 循环/单次 (a declared one-shot must not come back as a loop).
   */
  const copySource = join(ROOT, 'build', 'fixtures', 'motion-copy-sandbox');
  rmSync(copySource, { recursive: true, force: true });
  mkdirSync(copySource, { recursive: true });
  writeFileSync(join(copySource, 'wave.vrma'), waveBytes);
  writeFileSync(join(copySource, 'vrmpet3d-motions.json'),
    JSON.stringify({ clips: { 'wave.vrma': { loop: false } } }));
  const copied = await post({ importDir: copySource });
  eq(copied.status, 200, 'a motion FOLDER is imported');
  const copyEntry = (copied.payload?.importedMotions ?? [])[0];
  ok(Boolean(copyEntry && copyEntry.dir), 'the reply carries the imported folder');
  eq(copied.payload?.motionsDir, plugin.importedMotionsDir(), "the reply names the plugin's own storage");
  ok(String(copyEntry?.dir).startsWith(plugin.importedMotionsDir()), 'the folder was COPIED there');
  eq(copyEntry.clips, 1, 'with the one clip it holds');
  ok(existsSync(join(copyEntry.dir, 'wave.vrma')), 'the clip is really on disk in the copy');
  ok(existsSync(join(copyEntry.dir, 'vrmpet3d-motions.json')), "and so is the folder's own manifest");
  const copiedWave = (copied.payload?.motions ?? []).find((motion) => motion.name === 'wave.vrma');
  ok(Boolean(copiedWave), 'the catalogue lists the copy');
  eq(copiedWave?.loop, false, 'and its manifest reached the scan: the declared one-shot is still a one-shot');
  const removedCopy = await post({ unimportDir: copyEntry.dir });
  eq(removedCopy.payload.importedMotions.length, 0, 'removing the import clears the record');
  ok(!existsSync(copyEntry.dir), 'and deletes the copy');
  ok(existsSync(copySource), "while the user's own folder is untouched");

  /**
   * The first-run guide's own state, over its route: the ONE thing that stops the guide coming back.
   *
   * `prompted` marks this activation as already offered WITHOUT ending it (that is what makes a page reload quiet
   * while a restart still asks), and only `completed` writes the flag the next activation reads.
   */
  const freshSetup = await request('/vrmpet3d/setup-state', 'GET');
  eq(freshSetup.status, 200, 'the first-run guide reports its state');
  eq(freshSetup.payload.completed, false, 'a machine that has not been through it says so');
  eq(freshSetup.payload.prompted, false, 'and this activation has not offered it yet');
  const promptedSetup = await request('/vrmpet3d/setup-state', 'POST', JSON.stringify({ prompted: true }));
  eq(promptedSetup.payload.prompted, true, 'marking this activation as offered is recorded');
  eq(promptedSetup.payload.completed, false, 'without ending the guide');
  const doneSetup = await request('/vrmpet3d/setup-state', 'POST', JSON.stringify({ completed: true }));
  eq(doneSetup.payload.completed, true, '完成 marks it finished');
  const setupFile = join(ROOT, 'build', 'fixtures', 'setup-verify.json');
  ok(existsSync(setupFile) && JSON.parse(readFileSync(setupFile, 'utf8')).completed === true,
    "and the flag is persisted in the plugin's own file, which the next activation reads");

  for (const dispose of effects) dispose();
  rmSync(scratch, { force: true });
  rmSync(baseMotions, { recursive: true, force: true });
  rmSync(importMotions, { recursive: true, force: true });
  rmSync(notADirectory, { force: true });
}

// ---------------------------------------------------------------------------
group('11. fixture availability (for the browser pages that ARE wired in)');
// ---------------------------------------------------------------------------
{
  /**
   * The fixtures the wired-in client page inlines, checked from the host side because a page that
   * inlines nothing reports a failure deep inside a Chromium run.
   *
   * This group used to watch the PMD file the `mmd-probe` page needed. MMD was implementation-removed on
   * 2026-10-12 and that page is no longer in `verify-browser.mjs`'s page list, so the check moved to the
   * fixtures those pages still use: the VRM the client-test page derives its gaze axes from, and the VRMA
   * clips it plays. An absent fixture stays a NOTE rather than a failure, because `build/fixtures/` is
   * gitignored (see .gitignore) and a fresh checkout legitimately has none.
   */
  const vrmFixture = join(ROOT, 'build', 'fixtures', 'vrma', 'vrmpet3d-minimal.vrm');
  const motionFixtures = ['vrmpet3d-wave.vrma', 'vrmpet3d-rest.vrma']
    .map(name => join(ROOT, 'build', 'fixtures', 'vrma', name));
  if (existsSync(vrmFixture) && motionFixtures.every(existsSync)) {
    const fixtureBytes = readFileSync(vrmFixture);
    ok(fixtureBytes.length > 1000 && fixtureBytes.subarray(0, 4).toString('latin1') === 'glTF',
      `the VRM fixture the client probe inlines is a real binary glTF (${fixtureBytes.length} bytes)`);
    const motionBytes = motionFixtures.map(path => readFileSync(path));
    ok(motionBytes.every(bytes => bytes.subarray(0, 4).toString('latin1') === 'glTF'),
      `and so are the ${motionBytes.length} VRMA clips it plays`);
  } else {
    console.log('  note: the VRM/VRMA fixtures are absent; the browser client probe will report them.');
    console.log('        generate them with: node scripts/make-vrma-fixtures.mjs');
  }
}

// ---------------------------------------------------------------------------
group('12. what a model contains, over real HTTP (the settings window reads this)');
// ---------------------------------------------------------------------------
{
  const sandbox = join(ROOT, 'build', 'fixtures', 'model-info-sandbox');
  rmSync(sandbox, { recursive: true, force: true });
  mkdirSync(sandbox, { recursive: true });

  // The committed VRM fixture, which carries what the route has to report: expressions (one of them
  // declared and EMPTY), two spring chains with different physics, and three morph targets with no
  // names at all 鈥?so the expression table is the only thing that says what target #0 is.
  const vrmPath = join(ROOT, 'build', 'fixtures', 'vrma', 'vrmpet3d-minimal.vrm');
  ok(existsSync(vrmPath), 'the VRM fixture is present to describe');
  writeFileSync(join(sandbox, 'fish.vrm'), readFileSync(vrmPath));
  // Not a GLB at all, but with an extension this build DOES load: the answer is "cannot describe this",
  // not a 500, and not a 404 from a missing catalog id.
  writeFileSync(join(sandbox, 'body.glb'), Buffer.from('not a GLB payload', 'utf8'));

  const { ctx, routes, provided, effects } = stubContext();
  plugin.apply(ctx, { modelDirs: [sandbox] });
  const server = await serveRoutes(routes);
  const catalog = await server.json('/vrmpet3d/catalog');
  const vrmId = catalog.payload.models.find((model) => model.name === 'fish.vrm')?.id;
  const notGlbId = catalog.payload.models.find((model) => model.name === 'body.glb')?.id;
  ok(typeof vrmId === 'string', `the fixture is catalogued (${vrmId})`);

  const info = await server.json(`/vrmpet3d/model-info?m=${encodeURIComponent(vrmId)}`);
  eq(info.status, 200, 'the model-info route answers for a catalogued model');
  eq(info.payload.supported, true, 'and reports it as a VRM it can describe');
  eq(info.payload.id, vrmId, 'and echoes the id it was asked about');
  eq(info.payload.vrmSpec, '1.0 (extensions.VRMC_vrm)', 'and names the VRM flavour it found');
  const names = (info.payload.expressions || []).map((expression) => expression.name);
  ok(names.includes('blink') && names.includes('happy') && names.includes('wag'),
    `the expressions are listed by name (${names.join(', ')})`);
  eq((info.payload.expressions || []).find((expression) => expression.name === 'surprised')?.binds.length, 0,
    'an expression declared with no binds is listed, and reported as empty');
  // The reverse map, which is the point: the morph targets are unnamed, so the bind is the only
  // evidence that target #0 is `blink`.
  eq(info.payload.expressions.find((expression) => expression.name === 'blink').binds[0].target, 0,
    'an expression reports the morph target index it drives');
  eq(info.payload.expressions.find((expression) => expression.name === 'blink').binds[0].targetName, null,
    'and reports the target as unnamed, exactly as the file has it');

  const groups = (info.payload.springs && info.payload.springs.groups) || [];
  const hair = groups.find((group) => group.name === 'hair');
  const tail = groups.find((group) => group.name === 'tail');
  ok(Boolean(hair) && Boolean(tail), `both spring chains are listed (${groups.map((g) => g.name).join(', ')})`);
  eq(hair.stiffness, 0.4, "a chain carries the file's own stiffness, which is what \"default\" means in the UI");
  eq(hair.dragForce, 0.3, 'and its drag');
  eq(hair.gravityPower, 0.02, 'and its gravity');
  ok(tail.stiffness !== hair.stiffness, 'two chains keep their different physics apart');
  eq(hair.bones, 2, 'a chain reports how many joints it has');

  /**
   * The COLLIDER DETAIL the per-collider switches are built from (operator, 2026-10-14: 「可以做成详细面板一个个开关吗？」).
   *
   * The counts beside it answer "how many"; this list answers "which", and the settings page renders one checkbox per
   * entry. Asserted on the FIXTURE's own model — the app's real 12-sphere model is read in the live half — so the shape is
   * pinned here and the numbers are pinned there.
   */
  const colliderDetail = (info.payload.springs && info.payload.springs.detail) || null;
  ok(Array.isArray(colliderDetail), 'the model info describes its colliders one by one, not just as a count');
  ok(colliderDetail.every((entry) => /^\d+:\d+$/.test(String(entry.key))),
    `every entry carries the <group>:<collider> key the renderer filters by (${colliderDetail.map((e) => e.key).join(' ')})`);
  ok(colliderDetail.every((entry) => typeof entry.group === 'number' && entry.bone !== undefined),
    'and names the group and the bone each collider sits on, so a switch can say what it turns off');
  ok(colliderDetail.length === Number(info.payload.springs.colliders),
    'the detail list covers every collider the file declares');

  /**
   * And its KEY, which has to be the same string the renderer stores overrides under.
   *
   * This is the drift guard for a rule that lives in two files on purpose: `lib/vrm-info.js` imports nothing
   * (no dependency beyond `node:fs`), so it mirrors `core.springChainKey`, and the two halves disagreeing is
   * exactly the bug that made every unnamed chain's sliders inert (operator: "设置面板中存在大量无法修改的未命名
   * 链", 2026-10-09). Compared against core here, and asserted NON-EMPTY, because an empty key can be neither
   * stored nor looked up.
   */
  const coreModule = globalThis.__VRMPET3D_CORE__;
  ok(Boolean(coreModule && coreModule.springChainKey), 'core publishes the chain-key rule');
  const mismatches = [];
  groups.forEach((group) => {
    if (!group.key) mismatches.push(`${group.index}: empty`);
    // The compact shape calls the declared name `name` (it comes from the file's `comment`); the indexed
    // fallback is what a chain with no name gets, which is the common case in VRM 0.x.
    const expected = coreModule.springChainKey({ name: group.name, kind: 'vrm1' }, group.index);
    if (group.key !== expected) mismatches.push(`${group.index}: ${group.key} != ${expected}`);
  });
  eq(mismatches.join(', '), '', 'every chain key matches the rule the renderer uses, and none is empty');
  ok(info.payload.meta && info.payload.meta.licenseUrl === 'https://vrm.dev/licenses/1.0/',
    'and the licence the author wrote into the file travels with it');

  // Cached by (path, size, mtime): the second request must answer the same thing.
  const again = await server.json(`/vrmpet3d/model-info?m=${encodeURIComponent(vrmId)}`);
  eq(again.payload.expressions.length, info.payload.expressions.length, 'the answer is cached and stable');

  /**
   * And the THUMBNAIL the model picker draws beside each name (added 2026-10-13).
   *
   * The picker is a GRID of `<img src>` tiles, so the picture comes from a route of its own rather than from the
   * catalogue — the same split as the asset route, and for the same reason: one image per tile on screen instead
   * of every avatar's thumbnail in one JSON reply. What is asserted is that the bytes handed out are the file's
   * OWN embedded thumbnail (read back through `thumbnailImage`, the helper the route itself uses, so this is a
   * round trip and not a second implementation), and that the two "there is no thumbnail here" cases — a VRM
   * with no meta image, and a file that is not a GLB at all — are a 404 with a reason rather than an empty image
   * or a 500, because the page draws its own placeholder for them.
   */
  const bundled = catalog.payload.models.find((model) => model.source === 'bundled');
  ok(Boolean(bundled), `the built-in model is catalogued (${bundled && bundled.id})`);
  const thumbnail = await server.call(`/vrmpet3d/model-thumbnail?m=${encodeURIComponent(bundled.id)}`);
  eq(thumbnail.status, 200, 'the thumbnail route answers for the built-in model');
  eq(thumbnail.headers['content-type'], 'image/png', 'and serves the image with its own type');
  // Read back from the file the catalogue entry ITSELF names, so this stays a round trip — and stays true
  // whichever bundled model `find` lands on, which is what broke when a second one was added.
  const expectedThumb = vrmInfo.thumbnailImage(vrmInfo.readGlb(join(ROOT, 'assets', 'models', bundled.name)));
  ok(Boolean(expectedThumb) && thumbnail.body.equals(expectedThumb.bytes),
    `and the bytes are the file's OWN thumbnail (${expectedThumb ? `${expectedThumb.width}x${expectedThumb.height}` : 'none found'})`);

  /**
   * + THE MODEL AN EMPTY PREFERENCE RESOLVES TO, and the credit the picker prints for it.
   *
   * Operator, 2026-10-13: 「把BlueFatFish作为默认模型」 and 「需要注明来源和作者」. Both are reached here the way a fresh
   * page reaches them — the catalogue plus the resolver — rather than by reading a constant.
   */
  const defaultId = coreModule.resolveModelId(catalog.payload.models, '');
  const defaultModel = catalog.payload.models.find((model) => model.id === defaultId);
  eq(defaultModel && defaultModel.name, 'BlueFatFish.vrm.br',
    'an empty preference resolves to the bundled default, BlueFatFish.vrm.br');
  /**
   * The credit travels IN the catalogue — one object per bundled entry, built from `BUNDLED_MODEL_CREDITS` — so
   * the picker prints what the host says instead of keeping a second copy of who made what. Every user model
   * carries `credit: null` rather than no key, which is the shape a page (and a probe) reads.
   */
  const creditedNames = catalog.payload.models.filter((model) => model.credit).map((model) => model.name).sort();
  eq(creditedNames.join(', '), 'BlueFatFish.vrm.br, SampleModel.vrm.br',
    'and both bundled models carry a credit, and nothing else does');
  /**
   * …and the host's own translation round-trips back through the resolver both surfaces use.
   *
   * The end-to-end half of a bug that shipped: the pack's manifest names clips by FILE, the host translates those names
   * to ids before the payload goes out, and both surfaces feed that id-keyed block straight back into
   * `motionMapWithDefaults`. Each half was pinned and each half was right — the resolver understood names, the host sent
   * ids — so nothing failed while a fresh profile mapped NO CLIPS AT ALL (operator, 2026-10-15: 「为什么全新安装，模型没有任何动作
   * 了？」). This asserts the ROUND TRIP, on the catalogue this suite has in hand, with the state name taken from the
   * fixture rather than typed here.
   */
  {
    const bundled = plugin.buildMotionCatalog({ motionDirs: [join(ROOT, 'assets', 'motions')] });
    eq(Array.isArray(bundled.motions) && bundled.motions.length > 0, true,
      `the bundled pack is catalogued for this round trip (${bundled.motions.length} clips)`);
    // Exactly what the host sends: the manifest's name-keyed block, TRANSLATED to ids.
    const translated = core.motionMapWithDefaults({}, plugin.bundledMotionDefaults(), bundled.motions);
    const idMapped = Object.keys(translated).reduce((sum, state) => sum + translated[state].length, 0);
    eq(idMapped > 0, true, `the manifest's clip NAMES translate to ids (${idMapped} clips)`);
    const resolved = core.motionMapWithDefaults({}, translated, bundled.motions);
    const mapped = Object.keys(resolved).reduce((sum, state) => sum + resolved[state].length, 0);
    eq(mapped > 0, true,
      `and a fresh profile's EMPTY map resolves through that id-keyed block to real clips (${Object.keys(resolved).length} states, ${mapped} clips)`);
  }
  const fatFish = catalog.payload.models.find((model) => model.name === 'BlueFatFish.vrm.br');
  eq(fatFish && fatFish.credit.author, '木子恶魔', 'BlueFatFish.vrm credits its author');
  eq(fatFish && fatFish.credit.title, '蓝色小肥鱼Deepseek', "and the model's own name");
  eq(fatFish && fatFish.credit.source, 'https://www.aplaybox.com/details/model/ayXkRzVflmnd',
    'and the source the operator supplied');
  eq(fatFish && fatFish.credit.license, '经作者授权分发，需注明来源与作者', 'and the basis it ships on');
  ok(catalog.payload.models.every((model) => (model.source === 'bundled' ? Boolean(model.credit) : model.credit === null)),
    'while every user model carries credit: null rather than no key at all');
  const noThumbnail = await server.call(`/vrmpet3d/model-thumbnail?m=${encodeURIComponent(vrmId)}`);
  eq(noThumbnail.status, 404, 'a VRM that carries no thumbnail answers 404, not an empty image');
  ok(/no thumbnail/.test(noThumbnail.body.toString('utf8')), 'and says which case it is');
  const unknownThumbnail = await server.call('/vrmpet3d/model-thumbnail?m=nope');
  eq(unknownThumbnail.status, 404, 'an unknown model id is a 404, like every other id route');
  const brokenThumbnail = await server.call(`/vrmpet3d/model-thumbnail?m=${encodeURIComponent(notGlbId)}`);
  eq(brokenThumbnail.status, 404, 'and a file that is not a GLB is a 404 rather than a crash');

  /**
   * The described model lives in MEMORY, so opening the settings window does not re-parse the file
   * (operator, 2026-10-11: "模型参数加载太慢了，让它的信息和当前模型一样常驻内存").
   *
   * Two answers from a cache and two answers from two parses are byte-identical, so "it did not parse
   * again" is not assertable over HTTP: it is asserted against the cache's OWN parse counter, read here
   * directly from `lib/vrm-info.js`. Everything below is a DELTA, never an absolute, because the counter
   * is process-wide and earlier groups may already have described a model.
   */
  vrmInfo.clearModelInfoCache();
  const beforeCache = vrmInfo.cacheStats();
  eq(beforeCache.size, 0, 'the described-model cache can be emptied, and says so');
  const firstOverHttp = await server.json(`/vrmpet3d/model-info?m=${encodeURIComponent(vrmId)}`);
  const afterFirstCache = vrmInfo.cacheStats();
  eq(afterFirstCache.parses - beforeCache.parses, 1, 'the first request for a model parses the file');
  eq(afterFirstCache.size, 1, 'and the parsed report is what stays resident');

  const secondOverHttp = await server.json(`/vrmpet3d/model-info?m=${encodeURIComponent(vrmId)}`);
  const afterSecondCache = vrmInfo.cacheStats();
  eq(afterSecondCache.parses - beforeCache.parses, 1,
    'the second request for the SAME unchanged file does not parse it again — it is answered from memory');
  eq(afterSecondCache.hits - beforeCache.hits, 1, 'and the cache reports it as a hit');
  eq(secondOverHttp.payload.expressions.length, firstOverHttp.payload.expressions.length,
    'with an answer identical in shape to the parsed one');

  /**
   * A file that CHANGED is re-parsed, at the SAME path: the freshness check is the size+mtime pair, so a
   * user dropping a new model over an old one is still seen.
   *
   * The edit adds two meshes to the fixture's own glTF document, which is a statement about a NUMBER
   * (`counts.meshes`) rather than about a shape two reports could share — a stale report cannot produce it.
   * The mtime is set explicitly as well as the size changing, so the check is exercised on both halves.
   */
  const edited = JSON.parse(JSON.stringify(vrmInfo.readGlb(vrmPath).json));
  edited.meshes.push({ name: 'extra-a', primitives: [] }, { name: 'extra-b', primitives: [] });
  const editedPath = join(sandbox, 'fish.vrm');
  writeFileSync(editedPath, glbFromJson(edited));
  const editedAt = new Date(Date.now() + 2000);
  utimesSync(editedPath, editedAt, editedAt);
  ok(statSync(editedPath).size !== statSync(vrmPath).size, 'the replacement model is a different size');

  const changed = await server.json(`/vrmpet3d/model-info?m=${encodeURIComponent(vrmId)}`);
  const changedStats = vrmInfo.cacheStats();
  eq(changedStats.parses - afterSecondCache.parses, 1, 'a file that changed is parsed again');
  eq(changed.payload.counts.meshes, info.payload.counts.meshes + 2,
    'and described from the file on disk, not from the report the cache still holds');
  eq(changed.payload.supported, true, 'and the changed model is still describable at all');

  /**
   * And a path the host KNOWS changed is re-parsed at once, without waiting for the size/mtime check: this
   * is the explicit half of the invalidation, the half the import route calls.
   */
  ok(vrmInfo.forgetModelInfo(editedPath), 'a cached model can be forgotten by path');
  eq(vrmInfo.cacheStats().size, changedStats.size - 1, 'and forgetting it drops exactly that entry');
  eq(vrmInfo.cacheStats().keys.indexOf(resolve(editedPath)), -1, 'with the path itself gone from the cache');
  const afterForget = await server.json(`/vrmpet3d/model-info?m=${encodeURIComponent(vrmId)}`);
  eq(vrmInfo.cacheStats().parses - changedStats.parses, 1, 'so the next request parses the file again');
  eq(afterForget.payload.counts.meshes, changed.payload.counts.meshes, 'and answers with what it re-read');

  /**
   * The bound, driven for real: one distinct path per model, past the stated capacity.
   *
   * The failure this prevents is not a wrong answer but a GROWTH — the panel walks a directory of models,
   * and a cache that never evicts would be a second copy of everything the user ever imported.
   */
  const overflowBytes = readFileSync(join(sandbox, 'fish.vrm'));
  const overflow = [];
  for (let i = 0; i < vrmInfo.MODEL_INFO_CACHE_CAPACITY + 2; i += 1) {
    const name = `overflow-${i}.vrm`;
    writeFileSync(join(sandbox, name), overflowBytes);
    overflow.push(name);
  }
  // The same server: `/vrmpet3d/catalog` rebuilds the catalog on every request, so the new files are listed
  // by the time they are asked for and no second listener is needed.
  for (const name of overflow) {
    const listed = await server.json('/vrmpet3d/catalog');
    const id = listed.payload.models.find((model) => model.name === name)?.id;
    await server.json(`/vrmpet3d/model-info?m=${encodeURIComponent(id)}`);
  }
  const bounded = vrmInfo.cacheStats();
  eq(bounded.capacity, 4, 'the described-model cache holds four models');
  eq(bounded.size, bounded.capacity, 'and never holds more than its capacity, however many models are asked for');
  eq(bounded.size <= bounded.capacity, true, 'so it is bounded, not a second copy of the directory');
  ok(bounded.evictions > 0, 'the oldest entry is the one dropped when it overflows');
  vrmInfo.clearModelInfoCache();

  /**
   * The STRUCTURES the parts editor offers, and this is the list that makes a user-built part possible.
   *
   * The page lets a user add "the structures this part owns" by name, so the names have to travel: node names are
   * what a bone-driven hit resolves to, mesh and material names are what an unskinned hit falls back to. The
   * fixture's own fixture names are asserted by name — `hair`, `hair_mid`, `hair_end`, `tail`, `leftEye` — so a
   * list that came back empty, or one that carried only indices, fails here rather than in the settings window.
   */
  const structures = info.payload.structures;
  ok(Array.isArray(structures) && structures.length > 0, `the model lists its structures (${structures.length})`);
  const structureNames = structures.map((entry) => entry.name);
  ok(structureNames.indexOf('hair') !== -1 && structureNames.indexOf('tail') !== -1,
    'including the names a press can actually land on');
  eq(structureNames.indexOf('head') !== -1, true, 'and the humanoid nodes the raycast resolves to');
  eq(new Set(structureNames).size, structureNames.length, 'a name appears once, whatever kind of thing it is');
  eq(structures.every((entry) => ['node', 'mesh', 'material'].indexOf(entry.kind) !== -1), true,
    'every entry says what kind of structure it is, so the picker can group them');
  eq(structureNames.indexOf('vrmpet3d-fixture-mesh') !== -1, true, 'and mesh names are in the list too');
  ok(structures.every((entry) => entry.name.length <= 128), 'with every name capped, because this crosses the wire');

  const notGlb = await server.json(`/vrmpet3d/model-info?m=${encodeURIComponent(notGlbId)}`);
  eq(notGlb.status, 200, 'a model that is not a GLB is answered, not failed');
  eq(notGlb.payload.supported, false, 'and is reported as undescribable');
  ok(typeof notGlb.payload.reason === 'string' && notGlb.payload.reason.length > 0,
    'with a reason the UI can show');

  const unknown = await server.json('/vrmpet3d/model-info?m=nope');
  eq(unknown.status, 404, 'an unknown model id is refused like the asset route refuses it');

  // The settings page, and the one source it needs: the page is a host route like the pet's own, so
  // "the window opens blank" is a 404 here rather than a mystery inside a window nobody can inspect.
  const settingsPage = await server.call('/vrmpet3d/config');
  eq(settingsPage.status, 200, 'the model-parameter page is served');
  const settingsHtml = settingsPage.body.toString('utf8');
  ok(settingsHtml.includes('config-page.js'), 'and it loads its own script rather than inlining it');
  ok(settingsHtml.includes('/vrmpet3d/window/lib/core.js'), 'and core, which is where the settings rules live');
  /**
   * The containers every section is built into — and WHICH of the two pages carries it.
   *
   * `expression-body` was one of them until 2026-10-09, when the operator asked for the standalone expression/
   * 口型 table to be closed: what replaced it is the emotion table plus the per-clip expression and mouth
   * dropdowns in the 动作 section — and those are built by the script INTO `motion-list`. `motion-modes` is gone
   * with the per-clip table the per-state dropdowns replaced.
   *
   * Since 2026-10-11 the settings are TWO pages, so the same three assertions also pin the split from the host
   * side: the 模型参数 page serves the emotion table and the spring list (and NOT the 状态 container), the
   * 通用设置 page serves the motion list and the 碎碎念 boxes (and NONE of the per-model containers), and both
   * link the one stylesheet. A route that answered with the wrong file, or with one shared file, would leave a
   * window whose section is simply absent — the failure the `data-page` assertions in the desktop suite catch in
   * a real window, and this catches without one.
   */
  const globalPage = await server.call('/vrmpet3d/global');
  const globalHtml = globalPage.body.toString('utf8');
  const styleSheet = await server.call('/vrmpet3d/window/lib/pages.css');
  ok(settingsHtml.includes('emotion-body') && settingsHtml.includes('spring-list')
    && !settingsHtml.includes('motion-list') && !settingsHtml.includes('speech-states')
    && settingsHtml.includes('/vrmpet3d/window/lib/pages.css') && styleSheet.status === 200,
    'with the containers the 模型参数 page builds its sections into (and none of the other page\'s)'
      + ', over the one stylesheet both pages link and the host serves');
  ok(globalPage.status === 200
    && globalHtml.includes('motion-list') && globalHtml.includes('speech-states')
    && globalHtml.includes('config-page.js')
    && globalHtml.includes('/vrmpet3d/window/lib/pages.css')
    && !globalHtml.includes('emotion-body') && !globalHtml.includes('spring-list') && !globalHtml.includes('part-body')
    && !settingsHtml.includes('expression-body') && !settingsHtml.includes('motion-modes'),
    'and the 通用设置 page, a second document with its own sections and the same script,'
      + ' without the per-model ones or the tables the operator asked to close');
  const settingsSource = await server.call('/vrmpet3d/window/lib/config-page.js');
  eq(settingsSource.status, 200, 'the settings page\'s own script is whitelisted');
  ok(settingsSource.body.length > 2000, 'and is served whole');
  const notWhitelisted = await server.call('/vrmpet3d/window/lib/../index.js');
  eq(notWhitelisted.status, 404, 'and the whitelist still refuses anything else');

  for (const dispose of effects) dispose();
  eq(routes.length, 0, 'unloading removes the model-info route too');
  await server.close();
  rmSync(sandbox, { recursive: true, force: true });
}

// ---------------------------------------------------------------------------
group('13. the AI 碎碎念 route: one call, made here, from nothing but the settings');
// ---------------------------------------------------------------------------
{
  /**
   * A stand-in for an OpenAI-compatible endpoint that RECORDS what it was sent.
   *
   * The record is the point of this group: "nothing about the session reaches the model" is a statement about
   * the REQUEST BODY, and only a real server on the other end can hold the route to it.
   */
  const seen = [];
  let answer = '  模型写的一句话  ';
  let providerStatus = 200;
  let providerDelayMs = 0;
  const provider = createServer((req, res) => {
    let raw = '';
    req.on('data', (chunk) => { raw += chunk; });
    req.on('end', () => {
      let body = null;
      try { body = JSON.parse(raw); } catch { body = null; }
      seen.push({ url: req.url, headers: req.headers, body });
      const reply = () => {
        if (providerStatus !== 200) {
          res.writeHead(providerStatus, { 'content-type': 'application/json' });
          res.end(JSON.stringify({ error: { message: 'nope' } }));
          return;
        }
        res.writeHead(200, { 'content-type': 'application/json' });
        res.end(JSON.stringify({ choices: [{ message: { role: 'assistant', content: answer } }] }));
      };
      if (providerDelayMs) setTimeout(reply, providerDelayMs);
      else reply();
    });
  });
  await listenOnUsablePort(provider);
  const providerBase = `http://127.0.0.1:${provider.address().port}/v1`;

  /**
   * DSH's own service, stood in for: it records the call and answers with a scripted stream.
   *
   * The chunk shapes are the REAL protocol, read out of the installed `app.asar`: deltas are
   * `{ type: 'text-delta' | 'reasoning-delta', index, text }` and the terminal chunk is
   * `{ type: 'finish', reason: { kind, failure? } }`. The first version of this stub invented
   * `{ type: 'finish', kind: … }` — the same wrong assumption the host code made — which is precisely why it
   * could not catch the host reading `chunk.kind` and swallowing every stream failure.
   */
  const llmCalls = [];
  let dshChunks = [
    { type: 'text-delta', index: 0, text: 'DSH ' },
    { type: 'text-delta', index: 0, text: '说的一句' },
    { type: 'finish', reason: { kind: 'stop' } },
  ];
  const llm = {
    listProviders: () => [
      { provider: 'fake-official', displayName: '假官方' },
      { provider: 'fake-other', displayName: '另一个' },
    ],
    listModels: async (id) => (id === 'fake-official'
      ? [{ provider: id, id: 'fake-1', name: '假模型一' }, { provider: id, id: 'fake-2', name: '假模型二' }]
      : []),
    stream(options) {
      llmCalls.push(options);
      const chunks = dshChunks;
      return { async *[Symbol.asyncIterator]() { for (const chunk of chunks) yield chunk; } };
    },
  };

  const { ctx, routes, effects } = stubContext({ llm });
  plugin.apply(ctx, {});
  const server = await serveRoutes(routes);
  const json = async (path, method = 'GET', body) => {
    const response = await server.call(path, method, body === undefined ? undefined : JSON.stringify(body));
    let payload = null;
    try { payload = JSON.parse(response.body.toString('utf8')); } catch { payload = null; }
    return { ...response, payload };
  };
  const put = (speech) => json('/vrmpet3d/settings', 'POST', { preferences: { speech } });

  // --- the custom provider ---------------------------------------------------
  const configured = await put({
    source: 'ai',
    lines: { working: '兜底的一句' },
    ai: {
      provider: 'custom',
      baseUrl: providerBase,
      model: 'stub-model',
      apiKey: 'k-secret-123',
      persona: '你是一条蓝色小肥鱼',
      prompts: { working: '说一句正在干活的自言自语。' },
      temperature: 1.2,
    },
  });
  eq(configured.status, 200, 'the speech settings are written through the host store');

  const said = await json('/vrmpet3d/say?event=working');
  eq(said.status, 200, 'GET /vrmpet3d/say answers');
  eq(said.payload.text, '模型写的一句话', 'with the model\'s line, trimmed');
  eq(said.payload.provider, 'custom', 'naming the provider that produced it');
  eq(said.payload.model, 'stub-model', 'and the model');
  ok(Number.isFinite(said.payload.ms), 'and how long it took, which is what 试一句 shows');
  eq(seen.length, 1, 'exactly one call reached the provider');
  eq(seen[0].url, '/v1/chat/completions', 'at the OpenAI-compatible path under the configured base URL');
  eq(seen[0].headers.authorization, 'Bearer k-secret-123', 'with the key as a bearer token');
  eq(seen[0].body.model, 'stub-model', 'and the configured model');
  eq(seen[0].body.temperature, 1.2, 'and the configured temperature');
  /**
   * The privacy rule, asserted ON THE WIRE rather than in prose: the request is the persona, the fixed rules
   * and the state's own instruction — nothing else. A route that leaked session text would have to put it in
   * one of these two strings.
   */
  const systemMessage = seen[0].body.messages[0];
  const userMessage = seen[0].body.messages[1];
  eq(systemMessage.role, 'system', 'the persona is the system message');
  ok(systemMessage.content.startsWith('你是一条蓝色小肥鱼'), 'and it opens with what the user wrote');
  ok(systemMessage.content.includes('不要提到代码、文件名、路径'),
    'followed by the rules that keep a line drawable and free of session content');
  eq(userMessage.role, 'user', 'the per-state instruction is the user message');
  eq(userMessage.content, '说一句正在干活的自言自语。', 'and it is exactly what the user wrote for that state');

  /**
   * The SECOND reason this route exists: a press on a PART.
   *
   * The user writes a prompt per part in the settings ("被摸到耳朵时说一句"), and `part` is what selects it — so
   * the assertion is on the WIRE again: the request's user turn must be that part's own instruction, not the
   * state's. The answer echoes the part, and an id nothing knows falls back to the state rather than failing,
   * because a page left open while a part was deleted must keep working.
   */
  /**
   * `parts` is a TOP-LEVEL preference, next to `speech` rather than inside it — `mergePreferences` merges
   * top-level keys only, so a parts table sent inside a speech patch is silently dropped (which is exactly what
   * the first version of this test did, and why the part resolved to null).
   */
  const partsWritten = await json('/vrmpet3d/settings', 'POST', {
    preferences: {
      parts: {
        // Offered every shipped region: this fixture is about which part a press resolves to, and the migration
        // of 2026-10-12 would otherwise insert the rows it has never offered into the list being asserted.
        seeded: ['eye', 'head', 'hand', 'body', 'upperLeg', 'lowerLeg', 'foot', 'chest', 'butt', 'tail'],
        items: [
          { id: 'ear', label: '耳朵', match: ['ErDuo'], speech: { lines: ['别摸耳朵'], prompt: '被摸到耳朵时，说一句撒娇的话。' } },
          { id: 'body', label: '身体', region: 'body', speech: { lines: [], prompt: '' } },
          // A SHIPPED row, with both boxes EMPTY: its instruction and its lines come from the tables in core.
          { id: 'chest', label: '胸部', region: 'chest', speech: { lines: [], prompt: '' } },
          { id: 'butt', label: '屁股', region: 'butt', speech: { lines: [], prompt: '' } },
        ],
      },
    },
  });
  eq(partsWritten.status, 200, 'a part with its own prompt is written through the host store');
  eq(partsWritten.payload.preferences.parts.items.length, 4, 'and the store keeps the four the user built');
  /**
   * NOTE (2026-10-11): the guard that REFUSES a defaults-only patch over authored settings lives in `lib/settings.js`
   * (`authoredWeight` plus `update`'s refusal, unless the caller passes `reset: true`). It was added after the settings
   * page — booting with defaults because eight of its status elements had been deleted from its markup — sent its whole
   * preferences object and wiped every authored field: part structures, per-part 碎碎念, the AI prompts, the status lines.
   *
   * Its dedicated assertions are NOT here yet, and that is a gap worth naming rather than hiding. The first attempt
   * cleared the very parts the checks BELOW depend on, so it has to be written at the END of this group — or against its
   * own store instance — and my last pass through it left the tree red, which is worse than an honest gap.
   */
  answer = '耳朵痒痒的';
  const byPart = await json('/vrmpet3d/say?state=working&part=ear');
  eq(byPart.payload.text, '耳朵痒痒的', 'a press can ask for a line about a part');
  eq(byPart.payload.part, 'ear', 'and the answer says which part it was for');
  eq(seen[seen.length - 1].body.messages[1].content, '被摸到耳朵时，说一句撒娇的话。',
    'with the part\'s own prompt as the instruction, not the state\'s');
  const byStalePart = await json('/vrmpet3d/say?state=working&part=deleted-part');
  eq(byStalePart.payload.part, null, 'an id the settings no longer hold is answered as no part at all');
  eq(seen[seen.length - 1].body.messages[1].content, '说一句正在干活的自言自语。',
    'and falls back to the state\'s instruction rather than failing a page that was left open');
  // A part with an EMPTY prompt uses the state's instruction too: the pet is still working while it is touched.
  const barePart = await json('/vrmpet3d/say?state=working&part=body');
  eq(barePart.payload.part, 'body', 'a part with no prompt of its own still answers as that part');
  eq(seen[seen.length - 1].body.messages[1].content, '说一句正在干活的自言自语。',
    'while the instruction is the state\'s');
  /**
   * And the PER-CLIP AI 提示词 is APPENDED to that instruction, never put in its place.
   *
   * Operator, 2026-10-13: 「允许给每个动作单独定义碎碎念，和AI碎碎念提示词（如果当前是AI碎碎念的话）」. The page sends it
   * beside the state it belongs to — `POST /vrmpet3d/say {event, state, clipPrompt}` — because the instruction can come
   * from three places (the state's box, the shipped starter, a part's own prompt) and a per-clip note has to sit after
   * whichever of them named the subject. Asserted ON THE WIRE for the same reason every other instruction claim here
   * is: the host is the only half that builds the request.
   */
  answer = '这支动作的话';
  const clipPromptSay = await json('/vrmpet3d/say', 'POST',
    { event: 'working', state: 'working', language: 'zh', clipPrompt: '这句要说得得意一点' });
  eq(clipPromptSay.status, 200, 'a request carrying a per-clip 提示词 is answered');
  eq(seen[seen.length - 1].body.messages[1].content, '说一句正在干活的自言自语。\n这句要说得得意一点',
    'with the state\'s own instruction still the base and the clip\'s note appended after it');
  // The cap is the one the settings store applies, so what the panel shows and what the model is told cannot disagree.
  const longClipPrompt = await json('/vrmpet3d/say', 'POST',
    { event: 'working', state: 'working', language: 'zh', clipPrompt: 'x'.repeat(400) });
  eq(longClipPrompt.status, 200, 'an over-long one is accepted');
  eq(seen[seen.length - 1].body.messages[1].content.length,
    '说一句正在干活的自言自语。'.length + 1 + core.MOTION_LIMITS.promptLength,
    'and is cut to the per-clip cap the store uses rather than to a number of its own');
  const blankClipPrompt = await json('/vrmpet3d/say', 'POST',
    { event: 'working', state: 'working', language: 'zh', clipPrompt: '   ' });
  eq(blankClipPrompt.status, 200, 'a box holding only spaces is accepted');
  eq(seen[seen.length - 1].body.messages[1].content, '说一句正在干活的自言自语。',
    'and appends nothing, which is what "an empty box means no per-clip text" looks like on the wire');
  /**
   * A SHIPPED part brings its OWN instruction, with nothing written in its box (operator, 2026-10-12: 「默认AI提示词
   * "被主人摸到胸部了，必须要傲娇的回骂这个摸人家胸的变态主人才行。"（匹配词和AI提示词写进系统底层，AI提示词那里默认留空，
   * 跟未输入状态一样，如果输入了，则以输入的为准）」).
   *
   * Asserted ON THE WIRE because the host is the only half that builds the request — both surfaces send a part ID
   * and nothing else about what to say.
   */
  answer = '变态！';
  const shippedPart = await json('/vrmpet3d/say?state=working&part=chest');
  eq(shippedPart.payload.part, 'chest', 'a shipped 胸部 part answers as that part');
  eq(seen[seen.length - 1].body.messages[1].content,
    '被主人摸到胸部了，必须要傲娇的回骂这个摸人家胸的变态主人才行。',
    'and its own instruction reaches the model, with its box empty');
  // The part's answer is more specific than the NAME of what was touched, so a structure does not outrank it.
  await json('/vrmpet3d/say?state=working&part=chest&structure=bust&chain=Bust');
  eq(seen[seen.length - 1].body.messages[1].content,
    '被主人摸到胸部了，必须要傲娇的回骂这个摸人家胸的变态主人才行。',
    'which stays the instruction whatever the model named the structure it was touched on');
  const shippedButt = await json('/vrmpet3d/say?state=working&part=butt');
  eq(seen[seen.length - 1].body.messages[1].content,
    '被主人摸到屁股了，必须要傲娇的回骂这个摸人家屁股的变态主人才行。',
    'and 屁股 has one of its own');
  /**
   * And the user's own box replaces it — the operator's condition: 「如果输入了，则以输入的为准」.
   */
  await json('/vrmpet3d/settings', 'POST', {
    preferences: {
      parts: {
        seeded: ['eye', 'head', 'hand', 'body', 'upperLeg', 'lowerLeg', 'foot', 'chest', 'butt', 'tail'],
        items: [
          { id: 'ear', label: '耳朵', match: ['ErDuo'], speech: { lines: ['别摸耳朵'], prompt: '被摸到耳朵时，说一句撒娇的话。' } },
          { id: 'body', label: '身体', region: 'body', speech: { lines: [], prompt: '' } },
          { id: 'chest', label: '胸部', region: 'chest', speech: { lines: [], prompt: '我自己的胸部提示词' } },
        ],
      },
    },
  });
  await json('/vrmpet3d/say?state=working&part=chest');
  eq(seen[seen.length - 1].body.messages[1].content, '我自己的胸部提示词',
    'while a prompt the user writes replaces the shipped one');

  /**
   * And the SHIPPED persona is what an EMPTY persona box means, asserted ON THE WIRE.
   *
   * The operator wrote the character on 2026-10-13 and asked for it to be the DEFAULT (「设置碎碎念的默认人格为如下
   * 内容」): `core.cleanSpeechAi` is where an empty box becomes the shipped prose, so the host needs no second
   * fallback — and this is what proves the pair holds end to end rather than only in the cleaner. Only the FIRST
   * line is compared, because the persona is prose and its paragraphs are the core suite's business.
   */
  const clearedPersona = await json('/vrmpet3d/settings', 'POST', {
    preferences: {
      speech: {
        source: 'ai',
        ai: { provider: 'custom', baseUrl: providerBase, model: 'stub-model', apiKey: 'k-secret-123', persona: '' },
      },
    },
  });
  eq(clearedPersona.status, 200, 'an emptied persona box is written through the host store');
  eq(clearedPersona.payload.preferences.speech.ai.persona, core.DEFAULT_SPEECH_PERSONA,
    'which the store reports as the SHIPPED persona, not as nothing');
  const callsBefore = seen.length;
  answer = '米饭！';
  const shippedPersona = await json('/vrmpet3d/say?state=done');
  eq(shippedPersona.status, 200, 'and the pet still answers');
  eq(seen.length, callsBefore + 1, 'with one more call to the provider');
  ok(seen[seen.length - 1].body.messages[0].content
    .startsWith(core.DEFAULT_SPEECH_PERSONA.slice(0, core.DEFAULT_SPEECH_PERSONA.indexOf(String.fromCharCode(10)))),
  'whose system message opens with the shipped character');
  ok(seen[seen.length - 1].body.messages[0].content.indexOf('不要提到代码、文件名、路径') !== -1,
    'followed by the same fixed rules as any other request');
  // Put the user's own persona back, so the assertions after this one see the profile they were written against.
  await json('/vrmpet3d/settings', 'POST', {
    preferences: {
      speech: {
        source: 'ai',
        ai: { provider: 'custom', baseUrl: providerBase, model: 'stub-model', apiKey: 'k-secret-123', persona: '你是一条蓝色小肥鱼' },
      },
    },
  });
  await json('/vrmpet3d/settings', 'POST', {
    preferences: {
      parts: {
        seeded: ['eye', 'head', 'hand', 'body', 'upperLeg', 'lowerLeg', 'foot', 'chest', 'butt', 'tail'],
        items: [
          { id: 'ear', label: '耳朵', match: ['ErDuo'], speech: { lines: ['别摸耳朵'], prompt: '被摸到耳朵时，说一句撒娇的话。' } },
          { id: 'body', label: '身体', region: 'body', speech: { lines: [], prompt: '' } },
          { id: 'chest', label: '胸部', region: 'chest', speech: { lines: [], prompt: '' } },
          { id: 'butt', label: '屁股', region: 'butt', speech: { lines: [], prompt: '' } },
        ],
      },
    },
  });
  /**
   * And when the press names WHAT it touched, that name IS the instruction.
   *
   * This is the operator's request of 2026-10-11: "如果是默认未设置部位的结构，例如 bust，就传给 LLM 让它生成 bust 被
   * 触摸的碎碎念". `bust` is a mesh of 蓝色小肥鱼 that no part claims, so the only thing known about it is the name the
   * model file uses — and it is passed through VERBATIM, because translating it here would be a guess.
   *
   * The part is `body` here on purpose: `bust` belongs to the shipped 胸部 row now (2026-10-12), so the row that
   * has no instruction of its own is what shows the structure name being used as one.
   */
  answer = '别碰那里';
  const byStructure = await json('/vrmpet3d/say?state=working&part=body&structure=bust');
  eq(byStructure.payload.structure, 'bust', 'the structure that was touched is echoed back');
  eq(byStructure.payload.part, 'body', 'with the part that answered for it');
  ok(seen[seen.length - 1].body.messages[1].content.includes('bust'),
    'and the instruction NAMES it, which is what lets a part with no prompt be answered');
  ok(seen[seen.length - 1].body.messages[1].content !== '说一句正在干活的自言自语。',
    'instead of falling back to the state\'s instruction');
  // The part's own prompt still WINS over the structure: a user who wrote one meant it.
  const structureButPrompt = await json('/vrmpet3d/say?state=working&part=ear&structure=bust');
  eq(seen[seen.length - 1].body.messages[1].content, '被摸到耳朵时，说一句撒娇的话。',
    'while a part that HAS a prompt keeps it, whatever structure was touched');
  // A structure name is capped and flattened like every other string from a page: it goes into a prompt.
  const longStructure = await json('/vrmpet3d/say?state=working&part=body&structure=' + encodeURIComponent('x'.repeat(300)));
  eq(longStructure.payload.structure.length, 64, 'a long structure name is cut to what a prompt can hold');
  const junkStructure = await json('/vrmpet3d/say?state=working&part=body&structure=' + encodeURIComponent('a\nb\tc'));
  eq(junkStructure.payload.structure, 'a b c', 'and a multi-line one is flattened to a single word');
  /**
   * And the SPRING CHAIN, which LEADS the instruction when there is one.
   *
   * Operator, 2026-10-11: "触发点击碎碎念的时候，把对应的链名和结构名一起发给 LLM，链名的优先级大于结构名". Both names
   * are on the wire and both are echoed; the instruction opens with the chain, because `LiuHai` is what a person
   * and the model understand while `LiuHai.002` is the rig's own bookkeeping.
   */
  answer = '别拽我的刘海';
  const byChain = await json('/vrmpet3d/say?state=working&part=body&structure=LiuHai.002&chain=LiuHai');
  eq(byChain.payload.chain, 'LiuHai', 'the spring chain that was touched is echoed back');
  eq(byChain.payload.structure, 'LiuHai.002', 'together with the structure it hangs from');
  const chainInstruction = seen[seen.length - 1].body.messages[1].content;
  ok(chainInstruction.includes('LiuHai'), 'and the instruction names the chain');
  ok(chainInstruction.includes('LiuHai.002'), 'with the structure still mentioned inside it');
  ok(chainInstruction.indexOf('LiuHai') < chainInstruction.indexOf('LiuHai.002'),
    'the chain coming FIRST, which is what "链名的优先级大于结构名" means on the wire');
  // A chain with no structure at all is still answerable: the name is the whole instruction.
  const chainOnly = await json('/vrmpet3d/say?state=working&part=body&chain=WeiBa');
  ok(seen[seen.length - 1].body.messages[1].content.includes('WeiBa'),
    'a chain on its own names the thing that was touched');
  eq(chainOnly.payload.structure, null, 'with no structure to report');
  // The part's own prompt still beats BOTH: a user who wrote one meant it.
  await json('/vrmpet3d/say?state=working&part=ear&structure=LiuHai.002&chain=LiuHai');
  eq(seen[seen.length - 1].body.messages[1].content, '被摸到耳朵时，说一句撒娇的话。',
    'while a part that HAS a prompt keeps it, whatever chain and structure were touched');
  // A chain name is capped and flattened like every other string from a page: it goes into a prompt.
  const longChain = await json('/vrmpet3d/say?state=working&part=body&chain=' + encodeURIComponent('y'.repeat(300)));
  eq(longChain.payload.chain.length, 64, 'a long chain name is cut to what a prompt can hold');
  const junkChain = await json('/vrmpet3d/say?state=working&part=body&chain=' + encodeURIComponent('a\nb'));
  eq(junkChain.payload.chain, 'a b', 'and a multi-line one is flattened');
  const junkPart = await json('/vrmpet3d/say?state=working&part=' + encodeURIComponent('../../etc/passwd'));
  eq(junkPart.payload.part, null, 'and a part id that is not a plain key is refused as an id, not looked up');

  const customCatalog = await json('/vrmpet3d/llm');
  eq(customCatalog.payload.custom.configured, true, 'and the catalog reports the custom provider as configured');
  ok(!JSON.stringify(customCatalog.payload).includes('k-secret-123'), 'without ever echoing the credential');

  // The answer is sanitised at the boundary the bubble uses.
  answer = '第一行\n第二行';
  const flattened = await json('/vrmpet3d/say?state=done');
  eq(flattened.payload.text, '第一行 第二行', 'a multi-line answer is flattened into the one line a bubble draws');
  answer = 'x'.repeat(400);
  const capped = await json('/vrmpet3d/say?state=done');
  eq(capped.payload.text.length, 80, 'and a paragraph is cut to the relay cap');
  answer = '   ';
  const empty = await json('/vrmpet3d/say?state=done');
  eq(empty.payload.text, null, 'an answer with no text in it is no line at all');
  /**
   * A 200 with no text is its own diagnosis: an endpoint answering with a tool call, a refusal, or an empty
   * `choices` array looks identical from the outside otherwise, which is how "试一句 失败" becomes unattributable.
   */
  ok(String(empty.payload.error).includes('HTTP 200') && String(empty.payload.error).includes('choices=1'),
    'and the reason says what the endpoint actually answered');

  // Refusals the settings page can show, and a state nothing knows.
  providerStatus = 500;
  const failed = await json('/vrmpet3d/say?state=working');
  eq(failed.payload.text, null, 'a provider failure produces no line, so the user\'s fallback stays up');
  ok(String(failed.payload.error).includes('500'), 'and the reason names the HTTP status');
  providerStatus = 200;
  const unknown = await json('/vrmpet3d/say?state=nonsense');
  eq(unknown.payload.text, null, 'an unknown state is refused');
  eq(unknown.payload.error, 'unknown state', 'with a reason rather than an invented state');

  /**
   * Only ONE call may be in flight. Two at once is the shape a page produces when a state flickers, and the
   * second is told so rather than queued behind the first.
   */
  answer = '并发的一句';
  providerDelayMs = 150;
  const [first, second] = await Promise.all([json('/vrmpet3d/say?state=working'), json('/vrmpet3d/say?state=working')]);
  providerDelayMs = 0;
  eq([first, second].filter((entry) => entry.payload.text !== null).length, 1,
    'two simultaneous requests produce ONE call, not two');
  eq(([first, second].find((entry) => entry.payload.text !== null) || { payload: {} }).payload.text, '并发的一句',
    'and the one that ran is the one that answered');
  ok([first, second].some((entry) => entry.payload.error === '已经有一句在生成中了'),
    'and the other one is told so');

  // --- DSH's own provider ----------------------------------------------------
  /**
   * The provider and the model are refused SEPARATELY, and the operator's own report is why (2026-10-12):
   * 「即便配置了DeepSeek Account，点击试一句那里的生成，仍然会报错'失败：还没有选择 DSH 的 provider 和模型'」.
   *
   * The provider WAS configured — `dshProvider: 'deepseek-account'` was in the store — and only `dshModel` was
   * empty, while the window's model picker went on displaying a model (a `<select>` with no matching value shows
   * its first option). One message for two missing fields is what made that unanswerable from the screen, so the
   * refusal now names the one that is actually missing. Asserted before the complete pair below, so the two
   * halves are read against the same stub.
   */
  await put({ source: 'ai', ai: { provider: 'dsh', dshProvider: 'fake-official', dshModel: '' } });
  const noModel = await json('/vrmpet3d/say?event=done');
  eq(noModel.payload.text, null, 'a DSH route with no model produces no line');
  eq(noModel.payload.error, '还没有选择 DSH 的模型',
    'and says WHICH of the two is missing — the model, when the provider is set');
  eq(llmCalls.length, 0, 'without asking the LLM service at all, because the route is incomplete');
  await put({ source: 'ai', ai: { provider: 'dsh', dshProvider: '', dshModel: 'fake-1' } });
  const noProvider = await json('/vrmpet3d/say?event=done');
  eq(noProvider.payload.error, '还没有选择 DSH 的 provider', 'and the provider, when THAT is what is missing');
  eq(llmCalls.length, 0, 'with no call in that case either');

  const dshConfigured = await put({
    source: 'ai',
    ai: {
      provider: 'dsh',
      dshProvider: 'fake-official',
      dshModel: 'fake-1',
      persona: '你是一条蓝色小肥鱼',
      prompts: { done: '说一句收工的话。' },
    },
  });
  eq(dshConfigured.status, 200, 'the DSH provider is selected in the same settings');
  const dshSaid = await json('/vrmpet3d/say?event=done');
  eq(dshSaid.payload.text, 'DSH 说的一句', 'and its streamed answer becomes the line');
  eq(dshSaid.payload.model, 'fake-official/fake-1', 'reported as the route that produced it');
  eq(llmCalls.length, 1, 'exactly one call reached the service');
  eq(llmCalls[0].provider, 'fake-official', 'with the chosen provider');
  eq(llmCalls[0].model, 'fake-1', 'and the chosen model');
  eq(llmCalls[0].purpose, 'vrmpet3d-speech', 'and a purpose that names what the call is for');
  ok(llmCalls[0].system.includes('你是一条蓝色小肥鱼'), 'the persona goes in the system field');
  eq(llmCalls[0].messages[0].content[0].text, '说一句收工的话。', 'and the state instruction is the user turn');
  /**
   * The two options that cost the operator a real failure on 2026-10-10, asserted by NAME because nothing else
   * in the tree can see them: the DSH adapter defaults the reasoning effort to `high` when the caller says
   * nothing (`dsh-llm-deepseek`: `options.reasoningEffort ?? connection.defaults.reasoningEffort ?? … : "high"`),
   * and `max_tokens` is billed against the THINKING as well as the answer. A 64-token budget therefore came back
   * `max-tokens` with no visible text, and the pet fell back to its own line.
   */
  eq(llmCalls[0].reasoningEffort, 'off',
    'a 碎碎念 asks for NO reasoning, which is what DSH itself does for its own auxiliary short calls');
  eq(llmCalls[0].maxTokens, 256,
    'and a budget with room for a route that thinks anyway, rather than one the answer alone would fill');

  // A stream that ends in failure IS a failure, not a silent empty line. The terminal chunk is
  // `{ type: 'finish', reason: {...} }` — the KIND lives inside `reason`, which is what `BlockAssembler` reads.
  dshChunks = [
    { type: 'text-delta', index: 0, text: '半' },
    { type: 'finish', reason: { kind: 'error', failure: { code: 'AUTH', message: 'bad key' } } },
  ];
  const dshFailed = await json('/vrmpet3d/say?event=done');
  eq(dshFailed.payload.text, null, 'a stream that fails produces no line');
  ok(String(dshFailed.payload.error).includes('AUTH'), 'and the reason carries the failure code');
  ok(String(dshFailed.payload.error).includes('finish=error'), 'naming the finish kind as well as the code');

  /**
   * The failure the operator actually hit: a budget spent on THINKING, so the stream ends `max-tokens` with
   * reasoning deltas and no text at all. It has to come back as a refusal that says so — "the model produced
   * nothing" and "the model thought until the budget ran out" are different problems with different fixes.
   */
  dshChunks = [
    { type: 'reasoning-delta', index: 0, text: '让我想想'.repeat(6) },
    { type: 'finish', reason: { kind: 'max-tokens' } },
  ];
  const thoughtOut = await json('/vrmpet3d/say?event=done');
  eq(thoughtOut.payload.text, null, 'a stream that only thought produces no line');
  ok(String(thoughtOut.payload.error).includes('finish=max-tokens'), 'and says the budget ran out');
  ok(String(thoughtOut.payload.error).includes('思考 24 字'), 'with how much thinking that budget bought');
  ok(String(thoughtOut.payload.error).includes('正文 0 字'), 'and that no text arrived at all');

  // --- the catalog the settings page reads ------------------------------------
  const catalog = await json('/vrmpet3d/llm');
  eq(catalog.status, 200, 'GET /vrmpet3d/llm answers');
  eq(catalog.payload.dsh.available, true, 'and reports that this app has an LLM service');
  eq(catalog.payload.dsh.providers.length, 2, 'with the live provider routes');
  eq(catalog.payload.dsh.providers[0].id, 'fake-official', 'named by their route id');
  eq(catalog.payload.dsh.providers[0].name, '假官方', 'and labelled for a human');
  eq(catalog.payload.dsh.models.length, 0, 'but no model list until a provider is asked about');
  const models = await json('/vrmpet3d/llm?provider=fake-official');
  eq(models.payload.dsh.models.length, 2, 'asking about one provider lists its models');
  eq(models.payload.dsh.models[1].id, 'fake-2', 'with their ids');
  /**
   * The credential rides in the SETTINGS snapshot — the operator's own choice — but never in the STATE channel,
   * which is the one the floating window polls many times a second.
   */
  const state = await json('/vrmpet3d/state');
  ok(!JSON.stringify(state.payload).includes('k-secret-123'), 'the state channel carries no credential');

  // A composition with no LLM service says so instead of failing obscurely.
  for (const dispose of effects) dispose();
  const bare = stubContext();
  plugin.apply(bare.ctx, {});
  const bareServer = await serveRoutes(bare.routes);
  const noService = await bareServer.json('/vrmpet3d/llm');
  eq(noService.payload.dsh.available, false, 'a composition with no LLM service reports it honestly');
  const noCall = await bareServer.json('/vrmpet3d/say?event=working');
  eq(noCall.payload.text, null, 'and a request for a line produces none');
  ok(String(noCall.payload.error).includes('LLM'), 'with a reason that names the missing service');
  for (const dispose of bare.effects) dispose();
  await bareServer.close();
  await server.close();
  provider.close();
}

// ---------------------------------------------------------------------------
group('13c. the rename migrates the store instead of resetting it (2026-10-12)');
// ---------------------------------------------------------------------------
{
  /**
   * THE PROMISE THIS GROUP IS ABOUT. The project was renamed (`dsh-plugin-pet3d` -> `dsh-plugin-vrmpet3d`), and
   * the settings file moved with it: `pet3d-settings.json` -> `vrmpet3d-settings.json`. The operator's REAL
   * settings live in that file — part structures, per-part 碎碎念, the status lines, the model choice — so the
   * rename has to READ the old name and write the new one, or the first launch after the rename boots into
   * defaults over everything they configured.
   *
   * Tested on the SHIPPED file name on purpose, and in a scratch directory: the migration is keyed off
   * `.../vrmpet3d-settings.json`, so an override (`VRMPET3D_SETTINGS_FILE`, which is what the rest of this
   * suite uses) deliberately gets no legacy read — gotcha 37 again, a suite must not pick up the operator's file.
   */
  const legacyDir = join(ROOT, 'build', 'fixtures', 'rename-migration-verify');
  const currentFile = join(legacyDir, 'vrmpet3d-settings.json');
  const legacyFile = join(legacyDir, 'pet3d-settings.json');
  rmSync(legacyDir, { recursive: true, force: true });
  mkdirSync(legacyDir, { recursive: true });
  /**
   * A pre-rename store, written by hand in the shape the old build wrote: a version, the preferences, and the
   * two `live` slots. `authoredWeight` counts what the user wrote, so a part with a structure and a line is the
   * smallest honest way to prove the CONTENT survived rather than just the file being opened.
   */
  writeFileSync(legacyFile, JSON.stringify({
    version: 7,
    preferences: {
      modelId: 'migrated-model',
      parts: {
        seeded: core.STRUCTURE_REGIONS.slice(),
        items: [{ id: 'liuhai', label: '刘海', region: 'head', match: [{ name: 'LiuHai', exact: false }], speech: { lines: ['别戳我'] } }],
      },
      speech: { source: 'custom', lines: { working: '状态台词' } },
    },
    live: { app: 'migrated-model', window: null },
  }, null, 2));

  const { SettingsStore, authoredWeight } = await import(new URL('../lib/settings.js', import.meta.url).href);
  const store = new SettingsStore({ file: currentFile });
  const snapshot = store.snapshot();
  eq(snapshot.preferences.modelId, 'migrated-model', 'the model chosen before the rename is still chosen');
  const userPart = snapshot.preferences.parts.items.filter((item) => item.label === '刘海')[0];
  ok(Boolean(userPart), 'and the user\'s own part row is still there');
  eq(userPart ? userPart.match.length : -1, 1, 'with the structure it owns');
  eq(userPart ? userPart.speech.lines.join('') : '', '别戳我', 'and its 碎碎念');
  eq((snapshot.preferences.speech.lines.working || []).join(''), '状态台词', 'and the per-state box the user wrote');
  eq(snapshot.live.app, 'migrated-model', 'the live slot travels too');
  eq(authoredWeight(snapshot.preferences) > 0, true, 'so the store knows a user authored it, not a fresh page');
  /**
   * The version counter starts at 1 on a host start, even over a file that stored 7: it is a "has anything moved
   * since I last looked" number for the SURFACES, and they re-read after a restart, so the stored number is not a
   * promise. (It is also the 2026-10-08 gotcha that made a suite rewrite a live store's counter — see the note above
   * `SETTINGS_FILE`.) What the rename has to preserve is the PREFERENCES, not this number.
   */
  eq(snapshot.version, 1, 'the version counter is the host\'s own, not the stored one');
  eq(existsSync(currentFile), true, 'and the constructor writes the CURRENT name, so the migration is one-way');
  eq(JSON.parse(readFileSync(currentFile, 'utf8')).preferences.modelId, 'migrated-model',
    'the new file holds the same preferences, not defaults');
  ok(existsSync(legacyFile), 'while the old file is left alone: it is the user\'s data, not a temp file');

  // A store with NO legacy sibling is a fresh profile, and must not invent one.
  const freshDir = join(ROOT, 'build', 'fixtures', 'rename-migration-fresh');
  rmSync(freshDir, { recursive: true, force: true });
  mkdirSync(freshDir, { recursive: true });
  const fresh = new SettingsStore({ file: join(freshDir, 'vrmpet3d-settings.json') });
  eq(authoredWeight(fresh.snapshot().preferences), 0, 'a profile with no settings file at all starts at defaults');
  /**
   * …and the shipped PERSONA does not count as authored, which is what keeps `update`'s refusal alive.
   *
   * The character ships non-empty since 2026-10-13, so counting merely "a persona exists" would score every profile
   * above zero and `wipesAuthored` could never be true: the guard that exists to stop a half-booted settings page
   * from overwriting everything the user wrote would still read as code and never fire. These two are the pair that
   * catches that — a fresh profile, persona and all, weighs 0; a persona the user wrote weighs 1.
   */
  eq(authoredWeight(core.cleanPreferences({})), 0, 'the shipped persona is not something the user authored');
  eq(authoredWeight(core.cleanPreferences({ speech: { ai: { persona: '我是猫' } } })), 1,
    'while a persona they wrote is theirs, and counts');

  rmSync(legacyDir, { recursive: true, force: true });
  rmSync(freshDir, { recursive: true, force: true });
}

// ---------------------------------------------------------------------------
group('13b. the state channel stops believing a report that has gone quiet');
// ---------------------------------------------------------------------------
{
  /**
   * THE REPORT (operator, 2026-10-11): "有时候开始工作的碎碎念不消失，完成任务后还在显示深度求索中".
   *
   * The floating window reacts only when `seq` moves, so this route serving the last report for ever meant a pet whose
   * page had stopped — Chromium stops the frame loop while the DSH window is hidden, so a turn that ends in the
   * background is never computed nor sent — left 工作中 / 深度求索中 on screen underneath a counting clock, with
   * nothing able to tell that from a real long turn. The rule itself lives in `core.hostStateView` and is unit-tested
   * at its edges in `verify.mjs`; what THIS proves is that the route applies it, with a 30 ms window so the test does
   * not wait ninety seconds for the shipped one.
   */
  const { ctx, routes, effects } = stubContext();
  plugin.apply(ctx, { stateStaleMs: 30 });
  const server = await serveRoutes(routes);
  const post = (body) => server.call('/vrmpet3d/state', 'POST', JSON.stringify(body));

  const never = await server.json('/vrmpet3d/state');
  eq(never.payload.state, null, 'a pet that has never reported has no state to serve');
  eq(never.payload.stale, false, 'and is not called stale, because nothing has gone quiet yet');

  await post({ state: 'working', line: '深度求索中' });
  const fresh = await server.json('/vrmpet3d/state');
  eq(fresh.payload.state, 'working', 'a fresh report is served as it was reported');
  eq(fresh.payload.line, '深度求索中', 'with its line');
  eq(fresh.payload.stale, false, 'and is marked fresh');
  // Mutable: the clock posts below move the sequence on, and the staleness bump is measured from a fresh baseline.
  let seqFresh = fresh.payload.seq;
  /**
   * And the TURN CLOCK rides with it — including the stream-less sentinel.
   *
   * The floating window has no turn frames of its own, so this relay is the only way its 用时 can be the app's number.
   * The sentinel is the case that BIT: a deployment whose boundary stream is not wired sends `'state'`, and a sanitiser
   * that turned it into null made the window drop the duration entirely — the operator's "深度求索中的时间也没了".
   */
  await post({ state: 'working', clock: { startedAt: 1_700_000_000_000, endedAt: null } });
  eq((await server.json('/vrmpet3d/state')).payload.clock.startedAt, 1_700_000_000_000,
    'a turn clock is relayed to the window, which has no frames of its own');
  await post({ state: 'working', clock: 'state' });
  eq((await server.json('/vrmpet3d/state')).payload.clock, 'state',
    'and the stream-less sentinel is relayed AS ITSELF, not collapsed to null');
  await post({ state: 'working', clock: { startedAt: 'nonsense' } });
  eq((await server.json('/vrmpet3d/state')).payload.clock, null, 'while a clock that is not a clock is refused');
  await post({ state: 'working' });
  // Re-baselined AFTER the clock posts above, which legitimately moved the sequence on: what is under test here is
  // that going stale bumps it exactly once, not what the absolute number is.
  seqFresh = (await server.json('/vrmpet3d/state')).payload.seq;

  await new Promise((resolve) => setTimeout(resolve, 70));
  const aged = await server.json('/vrmpet3d/state');
  eq(aged.payload.state, null, 'once the report is older than the window it is answered as NO PET REPORTING');
  eq(aged.payload.line, null, 'so the window clears the status label and the 碎碎念 bubble');
  eq(aged.payload.stale, true, 'and says why it did');
  eq(aged.payload.seq, seqFresh + 1,
    'with the sequence bumped ONCE, because the window only looks again when it moves');
  const again = await server.json('/vrmpet3d/state');
  eq(again.payload.seq, aged.payload.seq, 'and it is not bumped again on every read');
  eq(again.payload.state, null, 'while the answer stays "no pet is reporting"');
  eq(again.payload.stale, true, 'with the same reason');

  await post({ state: 'working' });
  const revived = await server.json('/vrmpet3d/state');
  eq(revived.payload.state, 'working', 'and a new report revives the pet');
  eq(revived.payload.stale, false, 'as fresh again');
  ok(revived.payload.seq > again.payload.seq, 'on a sequence the window cannot miss, so it redraws');

  for (const dispose of effects) dispose();
  await server.close();
}

// ---------------------------------------------------------------------------
group('13d. the whale mark: read from the running DSH, then fall back rung by rung');
/**
 * WHY THIS GROUP EXISTS.
 *
 * Since 2026-10-16 `/vrmpet3d/whale` serves DSH's own mark read out of the RUNNING application at activation
 * (the operator: 「宿主最早加载插件的时候就抄下来，抄不到就逐级回落」). That is a delivery chain with four
 * rungs, and the failure it can hide is the quiet one: serving a STILL PNG, or serving the packaged copy
 * while the app's own mark went unread, or reporting a 404 on a machine that had a perfectly good cached
 * copy. Each rung is asserted on its own here, with fixture roots, because the rung that WINS cannot be
 * re-asked over HTTP without re-applying the plugin — and because the real mark is DeepSeek's asset, which
 * this repository must not keep in order to test (`docs/ASSET-CONTRACT.md` §1).
 *
 * The fixtures are laid out the way a real installation is: `<root>/dsh/node_modules/…/dsh-client-ui-chat/
 * lib/client.js` with a `mask:url(data:image/png;base64,…)` declaration in it.
 */
{
  const scratch = join(ROOT, 'build', 'fixtures', 'whale-chain-verify');
  rmSync(scratch, { recursive: true, force: true });
  mkdirSync(scratch, { recursive: true });

  const mark = apngFixture(3);
  const other = apngFixture(1);
  const dshRoot = join(scratch, 'asar-shaped');
  const dshMember = dshLayoutFixture(dshRoot, mark, "the running DSH's own bundle");
  const stillRoot = join(scratch, 'asar-shaped-still');
  dshLayoutFixture(stillRoot, stillPngFixture(), 'a still PNG, which must never be served as the animated mark');
  const localFile = join(scratch, 'local.apng');
  const stateFile = join(scratch, 'state', 'whale-tail.apng');
  writeFileSync(localFile, other);

  /** The parse rule on its own: what a bundle's declaration yields, and what it refuses. */
  {
    const parsed = whaleMark.parseWhaleBundle(readFileSync(dshMember, 'utf8'));
    ok(!parsed.error && parsed.frames === 3 && parsed.width === 28 && parsed.height === 28,
      `the declaration parses to the animated bytes (${parsed.error ?? `${parsed.frames} frames ${parsed.width}x${parsed.height}`})`);
    eq(Buffer.compare(parsed.bytes ?? Buffer.alloc(0), mark), 0, 'byte for byte, with the base64 decoded');
    const still = whaleMark.inspectWhaleImage(stillPngFixture());
    ok(Boolean(still.error) && /still PNG/.test(still.error),
      `and a still PNG is REFUSED by name rather than served as if it animated (${still.error})`);
    const absent = whaleMark.parseWhaleBundle('var css = "color: red";');
    ok(Boolean(absent.error) && absent.error.includes(whaleMark.WHALE_MARKER),
      'a bundle with no declaration says which declaration it looked for');
  }

  /** Rung 1 wins over the packaged copy, and refreshes the cached copy on its way past. */
  {
    const found = whaleMark.resolveWhaleMark({ asar: dshRoot, localFile, stateFile });
    eq(found.source, dshMember, "the mark comes from the running DSH's own bundle, not from the packaged file");
    eq(Buffer.compare(found.bytes ?? Buffer.alloc(0), mark), 0, 'and it is that bundle\'s bytes, not the other file\'s');
    ok(existsSync(stateFile), 'a successful read caches a copy in the plugin\'s own state directory');
    ok(existsSync(stateFile) && Buffer.compare(readFileSync(stateFile), mark) === 0, 'holding those same bytes');
  }

  /** Rung 2: no readable DSH, so the packaged file answers — as it always did. */
  {
    const found = whaleMark.resolveWhaleMark({ asar: join(scratch, 'nothing-here'), localFile });
    ok(String(found.source).startsWith("the plugin's own mark:"),
      `with no DSH to read, the packaged file answers (${found.source ?? found.error})`);
    eq(Buffer.compare(found.bytes ?? Buffer.alloc(0), other), 0, 'and it is that file\'s bytes');
  }

  /** Rung 3: no DSH and no packaged file, but a copy a previous activation left is still a mark. */
  {
    const found = whaleMark.resolveWhaleMark({ asar: join(scratch, 'nothing-here'), localFile: join(scratch, 'absent.apng'), stateFile });
    ok(String(found.source).startsWith('the copy a previous activation left'),
      `the cached copy is the third rung (${found.source ?? found.error})`);
    eq(Buffer.compare(found.bytes ?? Buffer.alloc(0), mark), 0, 'and it is the bytes the first rung cached');
  }

  /** Rung 4: nothing anywhere is a REPORTED failure, not a throw and not a silent still image. */
  {
    const found = whaleMark.resolveWhaleMark({ asar: join(scratch, 'nothing-here'), localFile: join(scratch, 'absent.apng'), stateFile: join(scratch, 'no-copy.apng') });
    ok(Boolean(found.error) && Array.isArray(found.tried) && found.tried.length > 0,
      `nothing to read is an error naming what was tried (${found.tried?.length ?? 0} paths)`);
    ok(!found.bytes, 'and no bytes are invented for the route to serve');
  }

  /**
   * A DSH whose bundle carries a STILL PNG must not win: the whole point of reading the running app is the
   * animated half, and `/vrmpet3d/whale` answering with a still image would look like a working route while
   * the tail never moved.
   */
  {
    const found = whaleMark.resolveWhaleMark({ asar: stillRoot, localFile });
    ok(String(found.source).startsWith("the plugin's own mark:"),
      'a still PNG in DSH\'s bundle is refused, and the chain falls through to the packaged file');
    eq(Buffer.compare(found.bytes ?? Buffer.alloc(0), other), 0, 'so what is served is still an animated image');
  }

  rmSync(scratch, { recursive: true, force: true });
}

// ---------------------------------------------------------------------------
/**
 * `--fetch` predates the rename: it downloads the MMD sample `build/probe/mmd-probe.js` used. That page is
 * no longer wired into `verify-browser.mjs` (MMD was implementation-removed on 2026-10-12) and nothing in
 * this suite needs the file, so the flag is kept only so the on-disk chapter and the note about it in
 * .gitignore stay honest. The fixtures the live browser pages need come from `make-vrma-fixtures.mjs`.
 */
if (process.argv.includes('--fetch')) {
  const target = join(ROOT, 'build', 'fixtures', 'miku');
  const files = [
    ['miku_v2.pmd', 'https://cdn.jsdelivr.net/gh/moeru-ai/three-mmd@main/examples/vanilla/src/assets/miku/miku_v2.pmd'],
    ['eyeM2.bmp', 'https://cdn.jsdelivr.net/gh/moeru-ai/three-mmd@main/examples/vanilla/src/assets/miku/eyeM2.bmp'],
  ];
  mkdirSync(target, { recursive: true });
  for (const [name, url] of files) {
    const destination = join(target, name);
    if (existsSync(destination)) {
      console.log(`  have  ${name}`);
      continue;
    }
    const response = await fetch(url);
    if (!response.ok) {
      console.error(`  FAIL  ${name}: HTTP ${response.status}`);
      process.exitCode = 1;
      continue;
    }
    writeFileSync(destination, Buffer.from(await response.arrayBuffer()));
    console.log(`  got   ${name} (${(statSync(destination).size / 1024).toFixed(0)} KB)`);
  }
}

console.log(`\n${'-'.repeat(60)}`);
if (failed === 0) {
  console.log(`host + model: ${passed} checks passed`);
  process.exit(process.exitCode ?? 0);
}
console.log(`host + model: ${passed} passed, ${failed} FAILED`);
for (const failure of failures) console.log(`  - ${failure}`);
process.exit(1);
